// Small illustrated food icons, drawn in SVG so the website remains completely self-contained.
const foodPalette={
  red:'#ea5149',green:'#7fb65e',darkgreen:'#3e833c',cream:'#f4e6ae',yellow:'#f8d45c',
  orange:'#f4a04d',brown:'#b77345',blue:'#75b9df',pink:'#efa3aa',purple:'#a384c8',
  white:'#f9f8ef',gray:'#d7dedc',black:'#262622'
};
const stroke='#242424';
const art=(body)=>`<svg class="food-illustration" viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g stroke="${stroke}" stroke-width="3.1" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;
const p=(d,fill)=>`<path d="${d}" fill="${fill}"/>`;
const ell=(cx,cy,rx,ry,fill)=>`<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${fill}"/>`;
const rect=(x,y,w,h,fill,rx=0)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}"/>`;
function coloredFood(item,large=false){
 const id=String(item.id||'').toLowerCase();
 const cat=String(item.category||'').toLowerCase();
 let shape='', c=foodPalette;
 if(id==='milk'||id==='cream'||id==='oatmilk'||id==='almondmilk'){
   shape=p('M20 20 L30 8 H51 L60 21 V66 H20 Z',c.white)+p('M51 8 L66 22 V63 L60 66 V21 Z',c.blue)+p('M20 20 H60 V32 H20 Z',c.gray)+rect(20,35,40,23,c.blue)+`<text x="40" y="51" fill="#202020" stroke="none" font-size="12" font-family="Arial,sans-serif" font-weight="900" text-anchor="middle">${id==='milk'?'MILK':id==='cream'?'CREAM':'MILK'}</text>`+ell(42,15,4,4,c.blue);
 } else if(id==='avocado'){
   shape=p('M41 8 C23 8 25 26 17 36 C5 55 16 72 39 73 C64 75 74 55 62 36 C57 26 58 8 41 8 Z',c.darkgreen)+p('M42 14 C30 14 31 30 23 39 C13 54 23 66 40 67 C56 68 64 54 56 39 C50 30 52 14 42 14 Z',c.cream)+ell(40,47,13,15,c.brown)+ell(36,41,4,5,'#d99961');
 } else if(id==='tomato'||id==='cherrytomatoes'){
   shape=ell(40,45,29,26,c.red)+p('M39 22 Q22 11 18 25 L33 26 L40 12 L47 26 L62 24 Q54 13 39 22 Z',c.darkgreen)+p('M16 47 Q19 57 25 60','none');
 } else if(['apple','greenapple','pear'].includes(id)){
   const green=id.includes('green')||id==='pear';
   shape=p('M39 25 Q23 14 15 32 Q8 52 27 67 Q36 72 40 66 Q50 74 59 64 Q76 40 60 25 Q50 18 39 25 Z',green?c.green:c.red)+p('M39 25 Q38 11 44 8','none')+p('M42 14 Q53 6 61 14 Q53 23 42 14 Z',c.darkgreen);
 } else if(id==='banana'){
   shape=p('M16 17 Q20 55 53 55 Q66 54 71 41 Q70 65 50 69 Q19 72 12 34 L9 20 Z',c.yellow)+p('M10 19 L18 17 L18 25 L11 26 Z',c.brown);
 } else if(id==='strawberry'||id==='strawberries'||id==='raspberries'){
   shape=p('M40 24 Q20 14 16 36 Q12 51 40 73 Q65 54 64 36 Q59 15 40 24 Z',id==='raspberries'?'#ce3e71':c.red)+p('M22 23 L35 26 L40 13 L46 26 L59 21 L53 34 L28 34 Z',c.darkgreen)+[ [30,40],[47,41],[37,52],[49,56],[27,55] ].map(a=>ell(a[0],a[1],1.6,2.3,c.cream)).join('');
 } else if(['lemon','lime','orange','grapefruit','kiwi','peach','mango','coconut','pineapple','watermelon','melon','blueberries','frozenberries','grapes'].includes(id)){
   if(id==='pineapple') shape=p('M32 27 L22 10 L39 21 L42 5 L48 21 L63 11 L51 29 Z',c.darkgreen)+p('M23 30 Q41 22 58 30 L56 57 Q43 75 27 58 Z',c.yellow)+p('M27 34 L53 56 M51 34 L27 55 M24 45 H56','none');
   else if(id==='watermelon') shape=p('M12 24 Q40 15 68 24 Q60 56 40 66 Q20 57 12 24 Z',c.red)+p('M12 24 Q40 15 68 24 Q64 33 59 39 Q40 31 21 39 Z',c.green)+ell(32,48,2,3,c.black)+ell(45,49,2,3,c.black);
   else shape=ell(40,43,27,27,({lemon:c.yellow,lime:c.green,orange:c.orange,grapefruit:c.pink,kiwi:'#9dbe72',peach:'#f4ac83',mango:c.orange,coconut:c.brown,melon:c.cream,blueberries:c.blue,frozenberries:c.purple,grapes:c.purple})[id])+p('M38 18 Q41 9 49 13', 'none')+p('M39 18 Q29 7 20 14 Q27 23 39 18 Z',c.darkgreen)+p('M21 40 Q20 52 28 58','none');
 } else if(id==='carrot'){
   shape=p('M31 23 Q42 20 53 33 L24 70 Q21 45 31 23 Z',c.orange)+p('M35 25 Q19 21 18 11 Q30 11 40 23 M38 25 Q39 9 49 6 Q52 18 45 28',c.darkgreen)+p('M32 40 L39 43 M29 52 L34 54','none');
 } else if(['potato','sweetpotato'].includes(id)){
   shape=p('M20 30 Q27 14 46 20 Q65 20 65 43 Q59 67 34 65 Q10 60 15 40 Z',id==='potato'?'#cfb38a':c.orange)+ell(32,38,2,2,c.brown)+ell(50,51,2,2,c.brown);
 } else if(id==='eggplant'){
   shape=p('M43 22 Q67 27 62 49 Q57 69 29 69 Q16 66 20 57 Q26 42 43 22 Z',c.purple)+p('M35 26 Q24 19 29 11 L42 20 L51 13 L53 26 Z',c.darkgreen);
 } else if(id==='mushroom'){
   shape=rect(31,38,17,29,c.cream,5)+p('M13 40 Q15 14 40 13 Q66 13 68 40 Z',c.red)+ell(31,27,5,5,c.white)+ell(50,30,4,4,c.white);
 } else if(id==='bellpepper'){
   shape=p('M35 20 Q14 12 15 37 Q11 67 27 67 Q38 61 40 65 Q51 70 61 57 Q70 25 52 19 Q44 14 35 20 Z',c.red)+p('M40 22 Q34 10 43 8 M31 24 Q39 29 48 23',c.darkgreen);
 } else if(id==='corn'){
   shape=ell(40,42,15,29,c.yellow)+p('M29 55 Q19 48 21 25 Q34 30 40 57 Q47 35 59 25 Q60 52 51 67 Z',c.green)+p('M34 22 V58 M44 23 V57 M27 32 H53 M27 43 H53 M29 54 H51','none');
 } else if(id==='broccoli'||id==='cauliflower'){
   shape=rect(35,44,12,24,c.green,3)+ell(26,39,15,17,id==='broccoli'?c.darkgreen:c.cream)+ell(43,26,17,18,id==='broccoli'?c.green:c.cream)+ell(55,40,14,16,id==='broccoli'?c.darkgreen:c.cream);
 } else if(['onion','garlic'].includes(id)){
   shape=p('M41 12 Q43 28 55 33 Q68 51 54 63 Q39 75 25 62 Q12 48 26 33 Q38 26 41 12 Z',id==='onion'?'#deb3db':c.cream)+p('M40 29 Q24 48 38 64 M44 29 Q59 50 44 64','none');
 } else if(['lettuce','spinach','kale','arugula','cabbage','celery','asparagus','basil','parsley','cilantro','springonion','zucchini','cucumber'].includes(id)){
   shape=p('M40 69 Q17 60 15 39 Q11 13 36 12 Q64 9 65 38 Q64 59 40 69 Z',c.green)+p('M40 68 Q41 35 46 21 M37 48 L24 34 M43 43 L55 30','none');
 } else if(id==='eggs'){
   shape=ell(34,42,21,28,c.white)+ell(48,43,18,25,c.cream);
 } else if(['cheese','mozzarella','parmesan','feta','creamcheese'].includes(id)){
   shape=p('M11 36 L51 16 L69 29 V62 H11 Z',c.yellow)+p('M11 36 L69 29 M51 16 V33','none')+ell(32,49,5,5,'#e6b64d')+ell(53,43,4,4,'#e6b64d');
 } else if(['bread','bagel','pita','tortilla','crackers','breadcrumbs'].includes(id)){
   shape=p('M17 32 Q10 12 28 16 Q40 8 52 16 Q70 14 62 33 V65 H17 Z',c.brown)+p('M23 33 Q19 20 32 23 Q43 18 52 24 Q60 21 57 34 V60 H23 Z',c.cream);
 } else if(['chicken','turkey','ham','bacon','beef','sausages'].includes(id)){
   shape=p('M25 22 Q44 8 61 27 Q72 41 51 56 Q34 64 20 48 Q10 34 25 22 Z',c.pink)+ell(32,35,10,8,'#fae0d7')+p('M51 52 L66 66','none')+ell(68,67,6,6,c.cream);
 } else if(['fish','tuna','salmon','shrimp'].includes(id)){
   shape=p('M13 42 Q32 13 53 34 L69 23 L67 58 L53 48 Q29 69 13 42 Z',id==='salmon'||id==='shrimp'?c.pink:c.blue)+ell(28,39,3,3,c.black)+p('M40 29 Q47 40 41 52','none');
 } else if(['icecream','frozenpeas','frozenberries'].includes(id)){
   shape=p('M20 45 Q16 22 38 17 Q59 13 61 42 Q58 57 40 59 Q24 58 20 45 Z',id==='frozenpeas'?c.green:c.pink)+p('M30 58 L40 72 L52 58',c.cream);
 } else if(['rice','pasta','noodles','oats','cereal','quinoa','couscous','flour','beans','lentils','chickpeas','blackbeans'].includes(id)){
   shape=p('M12 36 H68 Q62 62 51 66 H29 Q18 60 12 36 Z',c.blue)+p('M18 34 Q24 24 31 32 Q40 20 48 32 Q56 24 62 34',c.cream)+p('M26 45 Q40 48 54 45','none');
 } else if(['honey','jam','peanutbutter','nutella','mayo','mustard','ketchup','pesto','tomatosauce','salsa','soy sauce','soy sauce','hot sauce','oliveoil'].includes(id)||/sauce|oil|vinegar|syrup|spread/.test(id)){
   shape=rect(22,24,36,43,id==='honey'?c.yellow:id==='ketchup'||id==='tomatosauce'?c.red:id==='pesto'?c.green:c.cream,6)+rect(26,16,28,10,c.brown,3)+rect(25,38,30,16,c.white,2)+p('M30 46 H50','none');
 } else if(['juice','water','soda','coffee','tea'].includes(id)||/milk/.test(id)){
   shape=p('M28 14 H51 V25 Q59 29 59 41 V68 H20 V41 Q20 29 28 25 Z',c.blue)+rect(24,38,31,20,c.white,2)+rect(31,8,18,8,c.gray,2);
 } else if(['chocolate','chocolatechips','darkchocolate','cocoapowder'].includes(id)){
   shape=rect(15,19,50,47,c.brown,4)+[0,1,2].map(i=>[0,1].map(j=>rect(21+i*14,26+j*18,11,13,'#d59b74',2)).join('')).join('');
 } else {
   const colors={'fridge basics':c.blue,'produce':c.green,'protein':c.pink,'pantry staples':c.cream,'sauces & extras':c.orange,'frozen':c.blue};
   let base=colors[cat]||c.yellow;
   shape=rect(19,21,42,47,base,9)+rect(24,13,32,12,c.cream,4)+rect(26,39,28,17,c.white,3)+p('M32 47 H48','none');
 }
 return art(shape);
}
