const extraRecipes=[{"id":111,"title":"Cottage Cheese Berry Bowl","type":"Breakfast","time":5,"about":"Creamy cottage cheese, fresh berries, and a drizzle of honey.","need":["cottagecheese","strawberry","blueberries","honey"],"steps":["Spoon cottage cheese into a bowl.","Wash and slice the strawberries, then add them with the blueberries.","Drizzle with honey and serve chilled."]},{"id":112,"title":"Savory Cottage Cheese Toast","type":"Breakfast","time":8,"about":"Golden toast with cottage cheese, crisp cucumber, and juicy tomato.","need":["bread","cottagecheese","tomato","cucumber","pepper"],"steps":["Toast the bread until golden and crisp.","Spoon cottage cheese generously over the toast.","Top with thin slices of tomato and cucumber.","Finish with freshly ground black pepper and serve."]},{"id":113,"title":"Cottage Cheese Banana Pancakes","type":"Breakfast","time":20,"about":"Soft oat pancakes with cottage cheese and naturally sweet banana.","need":["cottagecheese","banana","eggs","oats","bakingpowder"],"steps":["Blend cottage cheese, banana, eggs, oats, and a little baking powder into a thick batter.","Let the batter stand for 3 minutes so the oats absorb some moisture.","Heat a good nonstick pan over medium-low heat and spoon in small pancakes.","Cook for 2–3 minutes per side, turning gently, until golden and the centers are fully set.","Serve warm."]},{"id":114,"title":"Cottage Cheese Tomato Pasta","type":"Dinner","time":20,"about":"A silky tomato pasta sauce blended with cottage cheese.","need":["cottagecheese","pasta","tomatosauce","garlic","oliveoil"],"steps":["Cook the pasta according to the packet directions, reserving a little pasta water before draining.","Gently cook finely chopped garlic in olive oil, then add tomato sauce and simmer for 5 minutes.","Blend the warm tomato sauce with cottage cheese until smooth.","Return the sauce to the pan over low heat, add the pasta, and loosen with a little reserved pasta water.","Warm gently without boiling and serve."]},{"id":115,"title":"Cottage Cheese & Spinach Omelette","type":"Breakfast","time":12,"about":"A tender folded omelette with spinach and creamy cottage cheese.","need":["eggs","cottagecheese","spinach","oliveoil","pepper"],"steps":["Warm olive oil in a nonstick pan and wilt the spinach.","Beat the eggs with a little black pepper and pour them into the pan.","Cook gently until the underside is set and the top is almost set.","Spoon cottage cheese onto one half, fold over, and cook gently until the egg is fully set and the filling is warm.","Slide onto a plate and serve."]},{"id":116,"title":"Lemon Ricotta Toast","type":"Breakfast","time":8,"about":"Creamy ricotta toast brightened with lemon and honey.","need":["bread","ricotta","lemon","honey"],"steps":["Toast the bread until crisp.","Stir ricotta with finely grated lemon zest and a small squeeze of lemon juice.","Spread the lemon ricotta onto the toast.","Drizzle with honey and serve."]},{"id":117,"title":"Ricotta & Spinach Pasta","type":"Dinner","time":20,"about":"Creamy ricotta, wilted spinach, and parmesan tossed with pasta.","need":["ricotta","spinach","pasta","garlic","parmesan","oliveoil"],"steps":["Cook the pasta according to the packet directions and reserve a mug of pasta water.","Gently cook chopped garlic in olive oil, then add spinach and stir until wilted.","Reduce the heat and stir in ricotta, grated parmesan, and a splash of pasta water.","Add the drained pasta and toss until coated, adding more pasta water as needed.","Serve with a little extra parmesan."]},{"id":118,"title":"Halloumi & Pepper Wrap","type":"Lunch","time":20,"about":"Golden halloumi and tender peppers wrapped with crisp lettuce.","need":["halloumi","bellpepper","tortilla","lettuce","oliveoil"],"steps":["Slice the halloumi and cut the bell pepper into strips.","Cook the pepper in olive oil until tender and lightly browned, then set aside.","In the same pan, cook the halloumi for 1–2 minutes per side until golden.","Warm the tortilla and fill it with lettuce, pepper, and halloumi.","Roll tightly, cut in half, and serve."]},{"id":119,"title":"Halloumi Couscous Bowl","type":"Lunch","time":20,"about":"Warm grilled halloumi with fluffy couscous and a lemony salad.","need":["halloumi","couscous","cucumber","tomato","lemon","oliveoil"],"steps":["Prepare the couscous according to the packet directions and fluff with a fork.","Dice the cucumber and tomato, then toss with lemon juice and a little olive oil.","Slice the halloumi and pan-fry until golden on both sides.","Spoon couscous into bowls and top with the salad and warm halloumi."]},{"id":120,"title":"Strawberry Kefir Smoothie","type":"Drink","time":5,"about":"A creamy strawberry and banana smoothie made with kefir.","need":["kefir","strawberry","banana"],"steps":["Wash and hull the strawberries and peel the banana.","Blend the fruit with cold kefir until smooth.","Add a little more kefir if you prefer a thinner smoothie, then pour into a glass."]},{"id":121,"title":"Roasted Beetroot & Feta Salad","type":"Lunch","time":40,"about":"Sweet roasted beetroot with feta, peppery greens, and walnuts.","need":["beetroot","feta","arugula","walnuts","oliveoil","vinegar"],"steps":["Heat the oven to 200°C. Peel the beetroot and cut it into small, even cubes.","Toss with a little olive oil and roast for 25–30 minutes, until tender. Let cool slightly.","Arrange arugula in a bowl and add the beetroot.","Crumble over feta and walnuts.","Dress with a little olive oil and vinegar, toss gently, and serve."]},{"id":122,"title":"Radish & Cucumber Yogurt Dip","type":"Snack","time":10,"about":"A fresh, crunchy yogurt dip with radishes, cucumber, and lemon.","need":["radish","cucumber","greekyogurt","lemon","garlic"],"steps":["Grate the cucumber and squeeze out excess liquid.","Finely chop the radishes and grate a small clove of garlic.","Mix the vegetables and garlic into Greek yogurt.","Add lemon juice to taste and chill briefly before serving."]},{"id":123,"title":"Creamy Leek & Potato Soup","type":"Dinner","time":30,"about":"A comforting, simple soup with leeks, potatoes, and a little milk.","need":["leek","potato","onion","milk","butter"],"steps":["Slice the leek and rinse thoroughly between the layers. Peel and dice the potatoes and onion.","Melt butter in a saucepan and gently cook the leek and onion until softened.","Add the potatoes and enough water to just cover. Simmer for 15–20 minutes until the potatoes are tender.","Blend until smooth, then stir in milk to reach your preferred consistency.","Warm gently and serve."]},{"id":124,"title":"Roasted Pumpkin & Chickpea Bowl","type":"Lunch","time":35,"about":"Golden roasted pumpkin and chickpeas over fresh spinach.","need":["pumpkin","chickpeas","spinach","oliveoil","paprika"],"steps":["Heat the oven to 200°C. Peel and dice the pumpkin into small cubes.","Drain the chickpeas and pat dry. Toss them and the pumpkin with olive oil and paprika.","Spread on a baking tray and roast for 25–30 minutes, turning once, until the pumpkin is tender.","Place spinach in bowls and top with the warm pumpkin and chickpeas, allowing the spinach to wilt slightly."]},{"id":125,"title":"Pumpkin & Red Lentil Soup","type":"Dinner","time":30,"about":"A thick golden soup with pumpkin, red lentils, and cumin.","need":["pumpkin","redlentils","onion","cumin","oliveoil"],"steps":["Peel and dice the pumpkin and onion, and rinse the red lentils.","Cook the onion in olive oil until soft, then stir in cumin.","Add the pumpkin and lentils with enough water to cover generously.","Simmer for 20–25 minutes until the pumpkin is tender and the lentils have softened, adding more water if needed.","Blend to your preferred texture and serve."]},{"id":126,"title":"Edamame Fried Rice","type":"Lunch","time":25,"about":"Colorful fried rice with edamame, carrots, and scrambled egg.","need":["edamame","rice","eggs","carrot","soyauce","sesameoil"],"steps":["Cook the rice according to the packet directions and spread it out briefly so steam can escape.","Cook the edamame according to its packet directions; shell it if needed. Finely dice the carrot.","Heat sesame oil in a large pan and stir-fry the carrot until tender.","Push the carrot aside, add beaten eggs, and stir until set.","Add the rice and edamame, season with soy sauce, and stir-fry until everything is hot."]},{"id":127,"title":"Lemon Herb Bulgur Salad","type":"Lunch","time":20,"about":"Fluffy bulgur tossed with crunchy vegetables, parsley, and lemon.","need":["bulgur","tomato","cucumber","parsley","lemon","oliveoil"],"steps":["Cook the bulgur according to the packet directions, then fluff and let cool slightly.","Finely dice the tomato and cucumber and chop the parsley.","Toss the vegetables and parsley with the bulgur.","Dress with lemon juice and olive oil and serve warm or chilled."]},{"id":128,"title":"Red Lentil Tomato Dahl","type":"Dinner","time":30,"about":"A warming one-pot red lentil dahl with tomato and curry spices.","need":["redlentils","tomatosauce","onion","garlic","curry","oliveoil"],"steps":["Rinse the lentils and finely chop the onion and garlic.","Cook the onion in olive oil until soft, then stir in garlic and curry powder for 30 seconds.","Add the lentils, tomato sauce, and enough water to cover generously.","Simmer gently for 20–25 minutes, stirring often and adding water as needed, until the lentils have broken down and the dahl is thick.","Serve hot."]},{"id":129,"title":"Tahini Lemon Hummus","type":"Snack","time":10,"about":"Smooth, creamy hummus with tahini, lemon, and garlic.","need":["tahini","chickpeas","lemon","garlic","oliveoil"],"steps":["Drain and rinse cooked chickpeas, reserving a few for the top.","Blend the chickpeas with tahini, lemon juice, garlic, and a little olive oil.","Add cold water a spoonful at a time and blend until smooth and creamy.","Spoon into a bowl, swirl the top, and finish with the reserved chickpeas and a little olive oil."]},{"id":130,"title":"Maple Tahini Banana Toast","type":"Breakfast","time":8,"about":"Golden toast with sesame tahini, banana, maple syrup, and cinnamon.","need":["bread","tahini","banana","maplesyrup","cinnamon"],"steps":["Toast the bread until golden.","Stir the tahini until smooth and spread it over the toast.","Arrange banana slices on top.","Drizzle lightly with maple syrup and dust with cinnamon."]},{"id":131,"title":"Cottage Cheese Berry Rice Cakes","type":"Snack","time":5,"about":"Crisp rice cakes topped with cottage cheese, berries, and honey.","need":["ricecakes","cottagecheese","strawberry","honey"],"steps":["Spread cottage cheese over the rice cakes.","Wash and thinly slice the strawberries, then arrange them on top.","Drizzle lightly with honey and eat straight away while the rice cakes are crisp."]},{"id":132,"title":"Peanut Butter Banana Rice Cakes","type":"Snack","time":5,"about":"A quick crunchy snack with peanut butter, banana, and cinnamon.","need":["ricecakes","peanutbutter","banana","cinnamon"],"steps":["Spread peanut butter over the rice cakes.","Top with banana slices.","Dust lightly with cinnamon and serve immediately."]},{"id":133,"title":"Peanut Butter Stuffed Dates","type":"Snack","time":10,"about":"Soft dates filled with peanut butter and finished with chocolate chips.","need":["dates","peanutbutter","chocolatechips"],"steps":["Slice each date lengthwise without cutting all the way through.","Remove and discard the pits.","Fill each date with a little peanut butter.","Press a few chocolate chips into the filling and serve."]},{"id":134,"title":"Banana Date Smoothie","type":"Drink","time":5,"about":"A creamy banana smoothie sweetened with soft dates.","need":["dates","banana","milk","cinnamon"],"steps":["Split the dates and remove the pits. If they are firm, soak them briefly in warm water and drain.","Blend the pitted dates, banana, cold milk, and a pinch of cinnamon until completely smooth.","Add a little more milk if you prefer a thinner drink, then pour into a glass."]}];
