const trendRecipes=[{"id":135,"title":"Hot Honey Beef Loaded Sweet Potato","type":"Dinner","time":60,"about":"A fluffy baked sweet potato piled with spiced ground beef, cottage cheese, avocado, and hot honey.","need":["sweetpotato","groundbeef","cottagecheese","avocado","hothoney","oliveoil","paprika","cumin"],"steps":["Heat the oven to 200°C. Scrub a medium sweet potato, prick it several times, and rub lightly with olive oil.","Bake for 45–55 minutes, until completely tender in the center; larger potatoes may need longer.","Meanwhile, cook the ground beef in a little olive oil, breaking it into crumbles. Add paprika and cumin, and cook until the beef reaches 71°C in the center, checked with a food thermometer.","Split the potato, gently fluff the orange flesh with a fork, and spoon the warm beef over it.","Add cottage cheese and sliced avocado, then drizzle with hot honey and serve."],"source":{"name":"Sweet potato bowl inspiration: Dished by Kate","url":"https://dishedbykate.com/viral-beef-protein-bowls/"}},{"id":136,"title":"Hot Honey Chicken Loaded Sweet Potato","type":"Dinner","time":60,"about":"A baked sweet potato with golden ground chicken, creamy cottage cheese, avocado, and a sweet-spicy drizzle.","need":["sweetpotato","groundchicken","cottagecheese","avocado","hothoney","oliveoil","paprika","cumin"],"steps":["Heat the oven to 200°C. Scrub a medium sweet potato, prick it several times, and rub lightly with olive oil.","Bake for 45–55 minutes until a knife slips easily through the center; allow more time for a large potato.","Cook the ground chicken in a little olive oil, breaking it up finely. Stir in paprika and cumin, and cook until the chicken reaches 74°C in the center, checked with a food thermometer.","Open the sweet potato and loosen the flesh with a fork.","Pile on the golden chicken, add cottage cheese and avocado slices, and finish with hot honey."],"source":{"name":"Sweet potato bowl inspiration: Dished by Kate","url":"https://dishedbykate.com/viral-beef-protein-bowls/"}},{"id":137,"title":"Smash Burger Tacos","type":"Dinner","time":20,"about":"Crisp beef-topped tortillas with melted cheese, lettuce, pickles, and a quick burger sauce.","need":["groundbeef","tortilla","cheese","lettuce","pickles","mayo","mustard","oliveoil"],"steps":["Mix mayonnaise with a little mustard for the sauce, then shred the lettuce and slice the pickles.","Press a thin, even layer of ground beef onto one side of each small tortilla, right to the edges.","Heat a lightly oiled frying pan over medium-high heat. Place a tortilla beef-side down and press firmly with a spatula.","Cook until browned, then flip, add cheese, and cook until the tortilla is crisp and the beef reaches 71°C. Adjust the heat so the tortilla does not burn.","Top with lettuce, pickles, and burger sauce. Fold and serve immediately."],"source":{"name":"Trend inspiration: Good Food","url":"https://www.bbcgoodfood.com/recipes/smash-burger-tacos"}},{"id":138,"title":"Cottage Cheese Flatbread Wrap","type":"Lunch","time":50,"about":"A soft baked cottage-cheese-and-egg wrap filled with turkey, crisp lettuce, and tomato.","need":["cottagecheese","eggs","turkey","lettuce","tomato","pepper","oliveoil"],"steps":["Heat the oven to 180°C. Line a baking tray with baking paper and brush the paper lightly with olive oil.","Blend 200 g cottage cheese with 2 eggs and a little black pepper until just smooth.","Pour into a thin, even rectangle on the tray. Bake for 30–40 minutes, until set throughout and lightly golden at the edges.","Leave to cool until it releases easily from the paper; lifting it too soon can tear it.","Fill with ready-to-eat cooked turkey slices, lettuce, and tomato. Roll gently, slice in half, and serve."],"source":{"name":"Flatbread inspiration: Feel Good Foodie","url":"https://feelgoodfoodie.net/recipe/cottage-cheese-flatbread/"}},{"id":139,"title":"Crispy Rice & Edamame Salad","type":"Lunch","time":50,"about":"Toasty rice, edamame, cucumber, and avocado with a lime-soy dressing.","need":["rice","edamame","cucumber","avocado","lime","soyauce","sesameoil"],"steps":["Heat the oven to 200°C. Cook the rice according to its packet directions, then spread it out briefly so excess steam can escape.","Toss the cooked rice with a little sesame oil and soy sauce. Spread thinly on a lined baking tray.","Bake for 20–25 minutes, stirring halfway, until lightly golden and crisp. Stop before the grains become hard, and let cool briefly.","Cook the edamame according to the packet directions and remove the pods if needed. Dice the cucumber and avocado.","Mix lime juice with a little soy sauce and sesame oil. Toss with the vegetables and add the crispy rice just before serving."],"source":{"name":"Crispy rice inspiration: Love and Lemons","url":"https://www.loveandlemons.com/crispy-rice/"}},{"id":140,"title":"Crispy Smashed Potato Salad","type":"Lunch","time":55,"about":"Golden smashed potatoes tossed with a tangy yogurt dressing and crunchy cucumber.","need":["potato","cucumber","greekyogurt","mustard","lemon","springonion","oliveoil"],"steps":["Heat the oven to 220°C. Boil small potatoes until completely tender, about 15–20 minutes, then drain and let steam dry.","Put the potatoes on an oiled baking tray and gently flatten each with the bottom of a glass.","Brush with olive oil and roast for 25–30 minutes until the edges are deeply golden and crisp.","Mix Greek yogurt with mustard and lemon juice. Chop the cucumber and green onions and stir them into the dressing.","Let the potatoes cool for a few minutes, then fold them through the dressing just before serving so they keep some crunch."],"source":{"name":"Trend inspiration: Poppy Cooks","url":"https://www.poppycooks.com/recipes/viral-smash-potato-salad/"}},{"id":141,"title":"Hot Honey Chicken Rice Bowl","type":"Lunch","time":25,"about":"Golden ground chicken, rice, cottage cheese, cucumber, and avocado with hot honey.","need":["groundchicken","rice","cottagecheese","cucumber","avocado","hothoney","oliveoil","paprika"],"steps":["Cook the rice according to the packet directions.","Cook the ground chicken in olive oil, breaking it into small pieces. Add paprika and continue cooking until it reaches 74°C in the center, checked with a food thermometer.","Dice the cucumber and slice the avocado.","Spoon rice into a bowl and arrange the chicken, cottage cheese, cucumber, and avocado on top.","Drizzle with hot honey just before serving."],"source":{"name":"Bowl inspiration: Pinch Me Good","url":"https://pinchmegood.com/ground-beef-sweet-potato-bowl/"}},{"id":142,"title":"Baked Feta & Tomato Pasta","type":"Dinner","time":40,"about":"Roasted tomatoes and soft baked feta turn into a creamy pasta sauce.","need":["pasta","feta","tomato","garlic","basil","oliveoil","pepper"],"steps":["Heat the oven to 200°C. Put chopped ripe tomatoes and whole peeled garlic cloves in a baking dish with olive oil and black pepper.","Nestle a block of feta in the middle and turn it once to coat lightly with oil.","Bake for about 30 minutes, until the tomatoes are soft and the feta is warmed through and lightly golden.","Meanwhile, cook the pasta according to its packet directions, reserving some pasta water before draining.","Mash the baked feta, garlic, and tomatoes into a sauce. Toss with the pasta and torn basil, adding pasta water as needed to loosen."],"source":{"name":"Trend inspiration: Feel Good Foodie","url":"https://feelgoodfoodie.net/recipe/baked-feta-pasta/"}}];
