const studentRecipes=[{"id":143,"title":"3-Ingredient Cheesy Tomato Pasta","type":"Dinner","time":18,"about":"A filling bowl of cheesy tomato pasta, cooked in one pan.","need":["pasta","tomatosauce","cheese"],"amounts":{"pasta":"100 g","tomatosauce":"150 g","cheese":"30 g grated"},"equipment":"One saucepan","steps":["Put the dry pasta, tomato sauce, and about 250 ml water in a small saucepan. Add a little more water if needed to just cover the pasta.","Bring to a gentle simmer and cook uncovered, stirring often, until the pasta is tender. Follow the pasta packet timing and add small splashes of water if the pan becomes dry.","When the pasta is cooked and the sauce is thick, take the pan off the heat.","Stir in the cheese until melted and serve."],"student":true,"servings":1},{"id":144,"title":"Crispy Tuna Melt Tortilla","type":"Lunch","time":10,"about":"A warm, crisp tortilla filled with tuna, tomato, and melted cheese.","need":["tortilla","tuna","cheese","tomato"],"amounts":{"tortilla":"1 large","tuna":"1 small tin, drained","cheese":"30 g grated","tomato":"1 small, thinly sliced"},"equipment":"One nonstick frying pan","steps":["Lay the tortilla flat and put the tuna, tomato slices, and cheese over one half.","Fold the empty half over the filling.","Cook in a dry nonstick frying pan over medium-low heat for 2–3 minutes on each side, until crisp and the cheese has melted.","Cut into wedges and eat while warm."],"student":true,"servings":1},{"id":145,"title":"Microwave Beans & Cheese Potato","type":"Dinner","time":20,"about":"A proper jacket potato with hot baked beans and a cheesy top.","need":["potato","bakedbeans","cheese"],"amounts":{"potato":"1 large baking potato (250–300 g)","bakedbeans":"½ a 400 g tin","cheese":"30 g grated"},"equipment":"Microwave, plate, and bowl","steps":["Scrub the potato and prick it several times with a fork. Put it on a microwave-safe plate.","Microwave on high for 5 minutes, turn it over, then cook for another 3–5 minutes. Continue in 1-minute bursts until it is soft all the way through; timing depends on the potato and microwave.","Put the baked beans in a microwave-safe bowl, cover loosely, and heat in 1-minute bursts, stirring until piping hot.","Split the potato and fluff the inside with a fork. Add the beans and cheese.","Microwave briefly again if needed to melt the cheese, then serve."],"student":true,"servings":1},{"id":146,"title":"Buttery Soy Egg Rice","type":"Dinner","time":20,"about":"Warm rice with buttery eggs and a splash of soy sauce.","need":["rice","eggs","butter","soyauce"],"amounts":{"rice":"75 g dry","eggs":"2","butter":"10 g","soyauce":"1–2 tsp"},"equipment":"One saucepan and frying pan","steps":["Cook the rice in water according to the packet directions.","Melt the butter in a nonstick frying pan over medium-low heat.","Crack in the eggs and cook until the whites and yolks are set to your liking, turning or covering briefly if needed to set the top.","Spoon the hot rice into a bowl, add the eggs, and drizzle with soy sauce and the buttery pan juices."],"student":true,"servings":1},{"id":147,"title":"Peanut Butter Pea Noodles","type":"Dinner","time":15,"about":"Creamy peanut noodles with peas, made in one saucepan.","need":["noodles","peanutbutter","frozenpeas","soyauce","lime"],"amounts":{"noodles":"90 g dry","peanutbutter":"1½ tbsp","frozenpeas":"100 g","soyauce":"1 tbsp","lime":"½"},"equipment":"One saucepan","steps":["Bring water to the boil in a saucepan. Cook the noodles and peas, adding them at the right times for their packet directions so both finish together.","Keep a mug of cooking water, then drain the noodles and peas.","Return them to the warm pan with the peanut butter, soy sauce, and lime juice.","Stir off the heat, adding cooking water a spoonful at a time, until everything is coated in a creamy sauce. Serve straight away."],"student":true,"servings":1},{"id":148,"title":"Creamy Tomato Chickpeas on Toast","type":"Lunch","time":15,"about":"A warm, filling bean-on-toast lunch with a creamy tomato sauce.","need":["chickpeas","cannedtomatoes","greekyogurt","bread","garlic"],"amounts":{"chickpeas":"½ a 400 g tin, drained","cannedtomatoes":"200 g","greekyogurt":"2 tbsp","bread":"2 thick slices","garlic":"1 small clove, finely chopped"},"equipment":"One saucepan and toaster","steps":["Put the canned tomatoes and garlic in a small saucepan and simmer for 5 minutes, stirring occasionally.","Add the drained chickpeas and cook for another 4–5 minutes, until hot and the sauce has thickened.","Toast the bread.","Take the pan off the heat, stir in the yogurt, and spoon everything over the toast."],"student":true,"servings":1},{"id":149,"title":"One-Pot Broccoli Cheese Rice","type":"Dinner","time":25,"about":"Soft rice, broccoli, and melted cheese with just one pan to wash.","need":["rice","broccoli","milk","cheese"],"amounts":{"rice":"75 g dry","broccoli":"150 g, cut into small florets","milk":"75 ml","cheese":"35 g grated"},"equipment":"One saucepan with a lid","steps":["Cook the rice in water according to the packet directions, using a saucepan with a lid.","Add the small broccoli florets for the final 5–7 minutes, replacing the lid so they steam until tender. Add a splash of water if the pan becomes dry.","When the rice is fully cooked and the water has been absorbed, stir in the milk and cheese.","Warm gently, stirring until creamy, and serve."],"student":true,"servings":1},{"id":150,"title":"Cheesy Egg Toastie","type":"Breakfast","time":12,"about":"Buttery toast filled with soft scrambled eggs and melted cheese.","need":["bread","eggs","cheese","butter"],"amounts":{"bread":"2 slices","eggs":"2","cheese":"25 g grated","butter":"10 g"},"equipment":"One nonstick frying pan","steps":["Beat the eggs. Melt half the butter in a nonstick pan and scramble the eggs gently until set, then slide onto a plate.","Put the eggs and cheese between the bread slices.","Melt the remaining butter in the same pan and add the sandwich.","Toast over medium-low heat for 2–3 minutes on each side, pressing gently, until golden and the cheese has melted."],"student":true,"servings":1},{"id":151,"title":"One-Pan Egg & Potato Hash","type":"Dinner","time":25,"about":"Crisp little potato pieces, sweet onion, and eggs in one pan.","need":["potato","eggs","onion","oliveoil"],"amounts":{"potato":"250 g, cut into 1 cm cubes","eggs":"2","onion":"½ small, finely chopped","oliveoil":"1 tbsp"},"equipment":"One nonstick frying pan with a lid","steps":["Heat the olive oil in a nonstick pan. Add the potato cubes and onion with 2 tablespoons water.","Cover and cook over medium heat for 10–12 minutes, stirring a few times, until the potatoes are nearly tender. Add a little water if they catch.","Remove the lid and cook for another 4–5 minutes until the potatoes are tender and golden.","Make two spaces, crack in the eggs, and cover again. Cook gently until the egg whites and yolks are set, then serve."],"student":true,"servings":1},{"id":152,"title":"One-Pot Tomato Bean Rice","type":"Dinner","time":25,"about":"A hearty cupboard meal of rice and beans in a simple tomato sauce.","need":["rice","beans","cannedtomatoes","cumin"],"amounts":{"rice":"75 g dry","beans":"½ a 400 g tin of cooked beans, drained","cannedtomatoes":"200 g","cumin":"½ tsp"},"equipment":"One saucepan with a lid","steps":["Put the rice, canned tomatoes, cumin, and about 150 ml water in a small saucepan.","Bring to a gentle simmer, cover, and cook over low heat according to the rice packet timing, stirring occasionally so the tomatoes do not catch.","Add more water in small splashes if needed. Stir in the cooked beans for the final 5 minutes.","When the rice is tender and the beans are hot, let stand covered for 2 minutes, then fluff and serve."],"student":true,"servings":1},{"id":153,"title":"Crispy Chickpea Pita","type":"Lunch","time":15,"about":"A warm pita stuffed with paprika chickpeas and thick yogurt.","need":["pita","chickpeas","greekyogurt","paprika","oliveoil"],"amounts":{"pita":"1 large","chickpeas":"½ a 400 g tin, drained and patted dry","greekyogurt":"3 tbsp","paprika":"½ tsp","oliveoil":"2 tsp"},"equipment":"One frying pan","steps":["Heat the olive oil in a frying pan. Add the dry chickpeas and cook for 8–10 minutes, shaking the pan regularly, until lightly crisp and hot.","Stir in the paprika for the final 30 seconds, then move the chickpeas to a plate.","Warm the pita briefly in the same pan and split it open.","Spread yogurt inside the pita, add the chickpeas, and serve straight away."],"student":true,"servings":1},{"id":154,"title":"One-Pot Lentil Tomato Pasta","type":"Dinner","time":30,"about":"Red lentils melt into an easy tomato pasta sauce for a filling dinner.","need":["pasta","redlentils","cannedtomatoes","onion"],"amounts":{"pasta":"75 g dry","redlentils":"40 g dry, rinsed","cannedtomatoes":"200 g","onion":"½ small, finely chopped"},"equipment":"One saucepan","steps":["Put the rinsed red lentils, onion, canned tomatoes, and 300 ml water in a saucepan.","Simmer gently for 10 minutes, stirring regularly.","Add the pasta and enough extra hot water to just cover it. Cook according to the pasta packet timing, stirring often and adding water as needed.","Continue until both the pasta and lentils are tender and the sauce is thick; some lentils may need a few extra minutes. Serve hot."],"student":true,"servings":1},{"id":155,"title":"3-Ingredient Sweetcorn Quesadilla","type":"Lunch","time":10,"about":"A crisp cheesy tortilla with sweetcorn from the cupboard.","need":["tortilla","corn","cheese"],"amounts":{"tortilla":"1 large","corn":"100 g canned sweetcorn, drained","cheese":"40 g grated"},"equipment":"One nonstick frying pan","steps":["Scatter cheese and drained sweetcorn over one half of the tortilla.","Fold the empty half over.","Cook in a dry nonstick pan over medium-low heat for 2–3 minutes on each side, until golden and the cheese is melted.","Cut into wedges and serve."],"student":true,"servings":1},{"id":156,"title":"3-Ingredient Banana Pancakes","type":"Breakfast","time":15,"about":"Small, soft pancakes made from banana, oats, and eggs.","need":["banana","oats","eggs"],"amounts":{"banana":"1 large ripe","oats":"40 g","eggs":"2"},"equipment":"Blender or fork, plus a good nonstick pan","steps":["Blend the banana, oats, and eggs into a thick batter. Alternatively, mash the banana thoroughly and mix in the eggs and finely crushed oats.","Let stand for 3 minutes so the oats can soften.","Warm a good nonstick pan over medium-low heat and spoon in small pancakes.","Cook for 2–3 minutes per side, turning gently, until golden and fully set in the middle. Serve warm."],"student":true,"servings":1},{"id":157,"title":"Peanut Butter Banana Porridge","type":"Breakfast","time":7,"about":"A big warm bowl of oats with banana and a peanut butter swirl.","need":["oats","milk","banana","peanutbutter"],"amounts":{"oats":"50 g","milk":"200–250 ml","banana":"1","peanutbutter":"1 tbsp"},"equipment":"Microwave and a large deep bowl","steps":["Put the oats and milk in a large, deep microwave-safe bowl with plenty of room for the oats to bubble up.","Microwave on high in 1-minute bursts, stirring between bursts, until thick and the oats are soft, usually 2–4 minutes depending on your microwave.","Stir in half the banana, mashed, and leave to stand for 1 minute.","Top with the remaining banana slices and swirl in the peanut butter."],"student":true,"servings":1},{"id":158,"title":"Cottage Cheese Cucumber Toast","type":"Lunch","time":5,"about":"A quick, generous cottage cheese lunch on crisp toast.","need":["bread","cottagecheese","cucumber","oliveoil"],"amounts":{"bread":"2 thick slices","cottagecheese":"150 g","cucumber":"⅓, thinly sliced","oliveoil":"1 tsp"},"equipment":"Toaster","steps":["Toast the bread until crisp.","Spoon the cottage cheese generously over both slices.","Arrange the cucumber slices on top.","Drizzle lightly with olive oil and eat straight away."],"student":true,"servings":1},{"id":159,"title":"Tuna & Bean Lunch Bowl","type":"Lunch","time":10,"about":"A no-cook bowl made with two cupboard tins and fresh tomato.","need":["tuna","beans","tomato","oliveoil","lemon"],"amounts":{"tuna":"1 small tin, drained","beans":"½ a 400 g tin of cooked beans, drained and rinsed","tomato":"1 large, diced","oliveoil":"2 tsp","lemon":"½"},"equipment":"One bowl","steps":["Drain the tuna and drain and rinse the cooked canned beans.","Put them in a bowl with the diced tomato.","Add olive oil and lemon juice, then toss gently.","Serve immediately, or chill until ready to eat."],"student":true,"servings":1},{"id":160,"title":"Egg & Bean Breakfast Wrap","type":"Breakfast","time":12,"about":"A hearty egg, bean, and cheese wrap for breakfast or a quick dinner.","need":["tortilla","eggs","beans","cheese","butter"],"amounts":{"tortilla":"1 large","eggs":"2","beans":"100 g cooked canned beans, drained","cheese":"25 g grated","butter":"5 g"},"equipment":"One nonstick frying pan","steps":["Beat the eggs. Melt the butter in a nonstick pan over medium-low heat.","Add the eggs and stir gently. When nearly set, add the drained cooked beans and cook until the eggs are set and the beans are hot.","Spoon onto the tortilla and scatter over the cheese.","Fold in the sides and roll up. Place seam-side down in the same pan for a minute, then turn briefly to warm the other side.","Cut in half and serve."],"student":true,"servings":1}];
for(const x of studentRecipes){if(!recipes.some(r=>r.id===x.id))recipes.push(x)}
