const moreEasyRecipes=[{"id":161,"title":"Pesto Eggs on Toast","type":"Breakfast","time":8,"about":"Crisp toast, soft eggs, and pesto do all the work.","need":["bread","eggs","pesto"],"amounts":{"bread":"2 slices","eggs":"2","pesto":"1 tbsp"},"equipment":"Nonstick frying pan and toaster","steps":["Toast the bread. Warm the pesto in a nonstick pan over low-medium heat.","Crack the eggs into the pesto. Cover and cook gently until the whites and yolks are set.","Lift the eggs and pesto onto the toast and eat warm."],"student":true,"servings":1,"balanced":false},{"id":162,"title":"3-Ingredient Yogurt Flatbreads","type":"Lunch","time":20,"about":"Soft, warm flatbreads with a cool yogurt dip.","need":["flour","greekyogurt","bakingpowder"],"amounts":{"flour":"100 g, plus a little for dusting","greekyogurt":"150 g, divided","bakingpowder":"½ tsp"},"equipment":"Bowl and nonstick frying pan","steps":["Mix the flour and baking powder, then stir in 100 g yogurt to make a soft dough. Add a teaspoon of water if dry.","Knead briefly on a floured surface, divide into two, and roll each about 5 mm thick.","Cook in a dry nonstick pan over medium heat for 3–4 minutes per side, until golden in spots and cooked through. Lower the heat if they brown too quickly.","Serve warm with the remaining 50 g yogurt for dipping."],"student":true,"servings":1,"balanced":false},{"id":163,"title":"Pea & Egg Drop Noodle Soup","type":"Dinner","time":15,"about":"A comforting noodle bowl with silky egg ribbons and peas.","need":["noodles","eggs","frozenpeas","soyauce"],"amounts":{"noodles":"75 g dried","eggs":"2, beaten","frozenpeas":"100 g","soyauce":"1–2 tsp"},"equipment":"One saucepan","steps":["Bring 500 ml water to a simmer. Add the noodles and cook according to the packet.","Add the peas for the final 3–4 minutes, ensuring they are piping hot.","Lower to a gentle simmer. Slowly pour in the beaten eggs while stirring, then simmer for 1–2 minutes until the egg is fully cooked.","Stir in the soy sauce, starting with 1 teaspoon, and serve."],"student":true,"servings":1,"balanced":true},{"id":164,"title":"3-Ingredient Pizza Potato","type":"Dinner","time":20,"about":"A fluffy jacket potato with a bubbly pizza topping.","need":["potato","tomatosauce","mozzarella"],"amounts":{"potato":"1 large (250–300 g)","tomatosauce":"3 tbsp","mozzarella":"60 g, torn"},"equipment":"Microwave, oven grill, and oven-safe dish","steps":["Scrub the potato, prick it with a fork, and microwave on a microwave-safe plate for 5 minutes. Turn and cook for 3–5 minutes more, then in short bursts until soft throughout.","Split the potato, fluff the middle, and spoon in the tomato sauce. Top with mozzarella.","Transfer to an oven-safe dish and grill until the cheese bubbles and the sauce is hot. Handle the hot dish carefully."],"student":true,"servings":1,"balanced":false},{"id":165,"title":"Chickpea Pickle Crunch Sandwich","type":"Lunch","time":10,"about":"A creamy, tangy sandwich made from cupboard staples.","need":["bread","chickpeas","mayo","pickles"],"amounts":{"bread":"2 large slices","chickpeas":"150 g canned, drained and rinsed","mayo":"1 tbsp","pickles":"2 small, chopped"},"equipment":"Bowl and fork","steps":["Mash the chickpeas roughly with a fork, leaving some texture.","Mix in the mayo and chopped pickles.","Pile onto the bread and close the sandwich. Toast the bread first if you prefer more crunch."],"student":true,"servings":1,"balanced":false},{"id":166,"title":"Lemon, Pea & Feta Couscous","type":"Lunch","time":12,"about":"Fresh, filling couscous with sweet peas and tangy feta.","need":["couscous","frozenpeas","feta","lemon"],"amounts":{"couscous":"75 g dry, preferably wholewheat","frozenpeas":"100 g","feta":"50 g, crumbled","lemon":"½, juiced"},"equipment":"Saucepan and heatproof bowl","steps":["Cook the peas in boiling water according to the packet, until piping hot. Drain.","Put the couscous in a heatproof bowl and add boiling water in the ratio stated on the packet. Cover and leave for the stated time.","Fluff with a fork, then fold in the peas, feta, and lemon juice."],"student":true,"servings":1,"balanced":true},{"id":167,"title":"Crispy Cabbage Egg Pancake","type":"Lunch","time":18,"about":"A golden skillet pancake with a tender, veggie-packed middle.","need":["cabbage","eggs","flour","soyauce","oliveoil"],"amounts":{"cabbage":"150 g, very finely shredded","eggs":"2","flour":"2 tbsp","soyauce":"1 tsp","oliveoil":"1 tsp"},"equipment":"Bowl and nonstick frying pan","steps":["Beat the eggs with the flour and soy sauce until smooth. Fold in the finely shredded cabbage.","Heat the oil in a small nonstick pan over medium-low heat. Add the mixture and press it into an even pancake about 1 cm thick.","Cover and cook for 5–6 minutes until the bottom is golden. Slide onto a plate, invert into the pan, and cook another 4–5 minutes until set throughout.","Cut into wedges and serve hot."],"student":true,"servings":1,"balanced":true},{"id":168,"title":"Sticky Honey-Soy Tofu Rice","type":"Dinner","time":25,"about":"Crisp tofu, sticky glaze, and a satisfying bowl of rice.","need":["tofu","rice","soyauce","honey","oliveoil"],"amounts":{"tofu":"180 g firm, patted dry and cubed","rice":"75 g dry","soyauce":"2 tsp","honey":"2 tsp","oliveoil":"1 tsp"},"equipment":"Saucepan and nonstick frying pan","steps":["Cook the rice according to the packet.","Heat the oil in a nonstick pan over medium heat. Add the tofu and cook for 8–10 minutes, turning until golden.","Mix the soy sauce and honey with 1 tablespoon water. Pour over the tofu and stir for 1–2 minutes until glossy.","Serve over the hot rice."],"student":true,"servings":1,"balanced":false},{"id":169,"title":"Garlicky Tomato Butter Beans","type":"Dinner","time":15,"about":"A creamy, cosy bean skillet, with no cream needed.","need":["beans","cannedtomatoes","butter","garlic"],"amounts":{"beans":"1 small tin white beans (about 240 g drained), rinsed","cannedtomatoes":"200 g","butter":"10 g","garlic":"1 clove, finely chopped"},"equipment":"One saucepan","steps":["Melt the butter over low-medium heat. Add the garlic and stir for 30 seconds without letting it brown.","Add the tomatoes and simmer for 5 minutes, stirring occasionally.","Add the beans and simmer another 5 minutes until piping hot.","Mash a few beans against the side of the pan to thicken the sauce, then serve in a bowl."],"student":true,"servings":1,"balanced":true},{"id":170,"title":"Apple & Cheddar Toasts","type":"Lunch","time":10,"about":"Sweet apple, sharp cheese, and crisp toast.","need":["bread","apple","cheese"],"amounts":{"bread":"2 slices, preferably wholegrain","apple":"1 small, thinly sliced","cheese":"50 g cheddar, grated"},"equipment":"Toaster and oven grill","steps":["Lightly toast the bread, then place it on a grill-safe tray.","Layer on the apple and cheese.","Grill until the cheese is melted and golden, watching closely so the edges do not burn."],"student":true,"servings":1,"balanced":false},{"id":171,"title":"Sweet Pepper & Tomato Eggs","type":"Dinner","time":20,"about":"An easy, saucy egg skillet with plenty of vegetables.","need":["bellpepper","eggs","cannedtomatoes","oliveoil"],"amounts":{"bellpepper":"1, thinly sliced","eggs":"2","cannedtomatoes":"200 g","oliveoil":"1 tsp"},"equipment":"Small frying pan with lid","steps":["Heat the oil over medium heat. Add the pepper and cook for 5–6 minutes until softened.","Add the tomatoes and simmer for 5 minutes, adding a splash of water if very thick.","Make two wells and crack in the eggs. Cover and cook gently for 5–7 minutes, until both whites and yolks are set."],"student":true,"servings":1,"balanced":true},{"id":172,"title":"Creamy Cheesy White Bean Mash","type":"Dinner","time":10,"about":"Comfort-food mash with the filling power of beans.","need":["beans","cheese","milk","butter"],"amounts":{"beans":"1 small tin white beans (about 240 g drained), rinsed","cheese":"35 g, grated","milk":"3 tbsp","butter":"1 tsp"},"equipment":"Saucepan and fork or potato masher","steps":["Put the beans, milk, and butter in a saucepan over low-medium heat.","Warm for 4–5 minutes, stirring, until piping hot.","Mash roughly, then stir in the cheese until melted. Add a little water if you prefer a looser mash."],"student":true,"servings":1,"balanced":false},{"id":173,"title":"Cheesy Pea & Egg Savory Oats","type":"Breakfast","time":12,"about":"A warm, savoury breakfast bowl that keeps things simple.","need":["oats","eggs","cheese","frozenpeas"],"amounts":{"oats":"60 g","eggs":"1","cheese":"25 g, grated","frozenpeas":"80 g"},"equipment":"One saucepan","steps":["Put the oats and peas in a saucepan with 250 ml water. Simmer for 5–7 minutes, stirring often, until the peas are piping hot and the oats are creamy.","Beat the egg in a cup. Reduce the heat and stir it steadily into the oats.","Cook for another 2–3 minutes, stirring until the egg is fully cooked. Add water if needed, then stir in the cheese."],"student":true,"servings":1,"balanced":true},{"id":174,"title":"Peanut Butter & Jam French Toast","type":"Breakfast","time":15,"about":"A crisp, gooey toast pocket for a sweet breakfast.","need":["bread","eggs","milk","peanutbutter","jam"],"amounts":{"bread":"2 slices","eggs":"1","milk":"2 tbsp","peanutbutter":"1 tbsp","jam":"1 tbsp"},"equipment":"Shallow bowl and nonstick frying pan","steps":["Spread one bread slice with peanut butter and the other with jam. Press together into a sandwich.","Beat the egg and milk in a shallow bowl. Dip both sides of the sandwich briefly into the mixture.","Cook in a good nonstick pan over medium-low heat for 3–4 minutes per side, until golden and the egg coating is fully cooked.","Rest for a minute, then cut in half."],"student":true,"servings":1,"balanced":false},{"id":175,"title":"2-Ingredient Banana Oat Cookies","type":"Snack","time":25,"about":"Soft, chewy cookies made with just ripe banana and oats.","need":["banana","oats"],"amounts":{"banana":"1 large very ripe","oats":"60 g"},"equipment":"Bowl, fork, and baking tray","steps":["Heat the oven to 180°C and line a small tray with baking paper.","Mash the banana thoroughly, then stir in the oats. Leave for 5 minutes to thicken.","Shape into four small, flat cookies. They will not spread much.","Bake for 15–18 minutes until firm and lightly golden at the edges. Cool slightly before eating."],"student":true,"servings":1,"balanced":true},{"id":176,"title":"2-Ingredient Chocolate Banana Soft Serve","type":"Snack","time":10,"about":"A creamy frozen treat with banana sweetness and cocoa.","need":["banana","cocoapowder"],"amounts":{"banana":"2 ripe, sliced and frozen solid","cocoapowder":"1 tbsp unsweetened"},"equipment":"Food processor or strong blender","steps":["Preparation ahead: freeze the sliced bananas in a single layer for at least 4 hours. The 10-minute recipe time starts with already-frozen banana.","Let the frozen banana stand for 5 minutes, then blend with the cocoa, stopping to scrape down the sides.","Keep blending until thick and creamy. Add water a teaspoon at a time only if the blender needs help.","Serve immediately for a soft-serve texture."],"student":true,"servings":1,"balanced":true},{"id":177,"title":"Creamy Spinach & Lentil Bowl","type":"Dinner","time":15,"about":"A simple, protein-rich bowl with a tangy yogurt finish.","need":["lentils","spinach","cannedtomatoes","greekyogurt"],"amounts":{"lentils":"1 small tin cooked lentils (about 240 g drained), rinsed","spinach":"80 g","cannedtomatoes":"200 g","greekyogurt":"3 tbsp"},"equipment":"One saucepan","steps":["Put the tomatoes and lentils in a saucepan. Simmer for 7–8 minutes, adding a splash of water if needed.","Stir in the spinach and cook for 2–3 minutes until wilted and everything is piping hot.","Take off the heat, let cool for a minute, and swirl through the yogurt."],"student":true,"servings":1,"balanced":true},{"id":178,"title":"Black Bean & Salsa Sweet Potato","type":"Dinner","time":20,"about":"A colourful loaded potato with beans and a cool yogurt topping.","need":["sweetpotato","blackbeans","salsa","greekyogurt"],"amounts":{"sweetpotato":"1 medium-large (250–300 g)","blackbeans":"150 g canned, drained and rinsed","salsa":"3 tbsp","greekyogurt":"3 tbsp"},"equipment":"Microwave, plate, and bowl","steps":["Scrub and prick the sweet potato. Microwave on a microwave-safe plate for 5 minutes, turn, then continue in 2-minute bursts until soft throughout.","Mix the beans and salsa in a microwave-safe bowl. Cover loosely and microwave in 1-minute bursts, stirring until piping hot.","Split the potato, fluff the inside, and fill with the bean mixture.","Spoon the yogurt on top and serve."],"student":true,"servings":1,"balanced":true},{"id":179,"title":"Warm Carrot, Lentil & Feta Salad","type":"Lunch","time":20,"about":"Sweet carrots and lentils make a salad that feels like a meal.","need":["lentils","carrot","feta","oliveoil","lemon"],"amounts":{"lentils":"1 small tin cooked lentils (about 240 g drained), rinsed","carrot":"2 medium, thinly sliced","feta":"40 g, crumbled","oliveoil":"1 tsp","lemon":"½, juiced"},"equipment":"One frying pan with lid","steps":["Heat the oil over medium heat. Add the carrots and 2 tablespoons water, cover, and cook for 7–9 minutes until tender. Add more water if the pan dries out.","Remove the lid and stir in the lentils. Heat for 3–4 minutes until piping hot.","Take off the heat and toss with lemon juice. Top with feta and eat warm."],"student":true,"servings":1,"balanced":true},{"id":180,"title":"Sesame Tofu & Edamame Noodles","type":"Dinner","time":18,"about":"A satisfying noodle bowl with two easy plant proteins.","need":["noodles","tofu","edamame","soyauce","sesameoil"],"amounts":{"noodles":"75 g dry, preferably wholewheat","tofu":"150 g firm, cubed","edamame":"100 g shelled frozen","soyauce":"2 tsp","sesameoil":"1 tsp"},"equipment":"Saucepan and nonstick frying pan","steps":["Cook the noodles according to the packet. Cook the edamame in the same pan for the full time specified on its packet, adding it earlier if needed. Drain.","Meanwhile, heat the sesame oil over medium heat in a nonstick pan. Add the tofu and cook for 6–8 minutes, turning until lightly golden.","Add the drained noodles, edamame, soy sauce, and 2 tablespoons water.","Toss over the heat for 1–2 minutes until hot throughout."],"student":true,"servings":1,"balanced":true}];
