const everydayRecipes=[{"id":181,"title":"Freezer Veg Egg Rice","type":"Lunch / Dinner","time":25,"about":"A filling rice bowl made with a bag of freezer vegetables.","need":["rice","eggs","mixedveg","soyauce"],"amounts":{"rice":"75 g dry","eggs":"2, beaten","mixedveg":"150 g frozen","soyauce":"1–2 tsp"},"equipment":"Saucepan and nonstick frying pan","steps":["Cook the rice according to its packet. Cook the mixed vegetables in the same pan for the full time stated on their packet, adding them earlier if needed. Drain well.","Tip into a good nonstick pan with 2 tablespoons water over medium heat. Push to one side and pour in the eggs.","Stir the eggs until fully set, then mix everything together. Stir in the soy sauce and serve piping hot."],"student":true,"servings":1,"balanced":true},{"id":182,"title":"Easy Egg & Veg Noodle Bowl","type":"Lunch / Dinner","time":10,"about":"A packet of noodles becomes a proper meal with eggs and vegetables.","need":["instantnoodles","eggs","mixedveg"],"amounts":{"instantnoodles":"1 single-serving packet with seasoning","eggs":"2, beaten","mixedveg":"150 g frozen"},"equipment":"One saucepan","steps":["Bring 450 ml water to a simmer. Add the frozen vegetables and cook for the time on their packet.","Add the noodle block for the final cooking time on its packet, plus half the seasoning sachet to start.","Pour in the beaten eggs slowly while stirring. Simmer for 1–2 minutes until the egg is fully cooked. Add water if needed, then serve."],"student":true,"servings":1,"balanced":false},{"id":183,"title":"Chickpea & Veg Couscous","type":"Lunch / Dinner","time":15,"about":"A quick cupboard-and-freezer bowl that keeps you full.","need":["couscous","chickpeas","mixedveg","stockcubes"],"amounts":{"couscous":"75 g dry, preferably wholewheat","chickpeas":"150 g canned, drained and rinsed","mixedveg":"150 g frozen","stockcubes":"¼ reduced-salt cube"},"equipment":"Saucepan and heatproof bowl","steps":["Cook the vegetables in boiling water according to the packet. Add the chickpeas for the last 3 minutes to heat through, then drain.","Prepare the couscous in a heatproof bowl using the boiling-water ratio on its packet, dissolving the quarter stock cube in that water first. Cover for the stated time.","Fluff with a fork and fold in the hot chickpeas and vegetables."],"student":true,"servings":1,"balanced":true},{"id":184,"title":"One-Pot Cheesy Pea Rice","type":"Lunch / Dinner","time":25,"about":"Soft, savoury rice with sweet peas and a cheesy finish.","need":["rice","frozenpeas","stockcubes","parmesan"],"amounts":{"rice":"75 g dry white rice","frozenpeas":"120 g","stockcubes":"¼ reduced-salt cube","parmesan":"25 g, finely grated"},"equipment":"One saucepan with lid","steps":["Dissolve the stock cube in the amount of water specified for 75 g rice on the rice packet.","Add the rice, cover, and cook gently according to the packet. Add the peas for their full packet cooking time, adding a splash more water if needed.","When the rice is tender and peas are piping hot, take off the heat. Stir in the parmesan and a splash of hot water for a creamy finish."],"student":true,"servings":1,"balanced":true},{"id":185,"title":"Tomato Bean & Pasta Soup","type":"Lunch / Dinner","time":25,"about":"A chunky soup hearty enough to count as a meal.","need":["cannedtomatoes","beans","pasta","stockcubes"],"amounts":{"cannedtomatoes":"200 g","beans":"150 g canned, drained and rinsed","pasta":"60 g dry, small shapes","stockcubes":"¼ reduced-salt cube"},"equipment":"One saucepan","steps":["Put the tomatoes, 350 ml water, and stock cube in a saucepan and bring to a simmer.","Add the pasta and simmer for its packet cooking time, stirring often. Add water if the soup becomes too thick.","Stir in the beans for the final 4–5 minutes and cook until piping hot. Serve when the pasta is tender."],"student":true,"servings":1,"balanced":true},{"id":186,"title":"Tomato & Egg Noodles","type":"Lunch / Dinner","time":15,"about":"A simple, savoury noodle bowl with a silky tomato coating.","need":["noodles","tomatopaste","eggs","oliveoil"],"amounts":{"noodles":"75 g dry","tomatopaste":"1 tbsp","eggs":"2, beaten","oliveoil":"1 tsp"},"equipment":"Saucepan and nonstick frying pan","steps":["Cook the noodles according to the packet. Reserve a little cooking water, then drain.","Heat the oil over medium-low heat. Stir in the tomato paste for 1 minute, then add 3 tablespoons cooking water.","Push the sauce to one side, add the eggs, and stir until fully set.","Add the noodles and toss everything together, adding a splash more water if needed."],"student":true,"servings":1,"balanced":false},{"id":187,"title":"Crispy Fish Finger Wrap","type":"Lunch / Dinner","time":25,"about":"An easy crunchy wrap with familiar freezer favourites.","need":["tortilla","fishfingers","lettuce","mayo"],"amounts":{"tortilla":"1 large","fishfingers":"4 frozen","lettuce":"2 large leaves, shredded","mayo":"1 tbsp"},"equipment":"Oven and baking tray","steps":["Cook the fish fingers from frozen exactly as directed on their packet, until piping hot throughout.","Warm the tortilla briefly according to its packet.","Spread on the mayo, add the lettuce and cooked fish fingers, fold in the sides, and roll up. Cut in half."],"student":true,"servings":1,"balanced":false},{"id":188,"title":"Fish Fingers, Wedges & Peas","type":"Lunch / Dinner","time":40,"about":"A simple homemade plate using freezer staples.","need":["fishfingers","potato","oliveoil","frozenpeas"],"amounts":{"fishfingers":"4 frozen","potato":"200 g, cut into slim wedges","oliveoil":"1 tsp","frozenpeas":"120 g"},"equipment":"Oven, baking tray, and saucepan","steps":["Heat the oven to the temperature on the fish finger packet. Toss the potato wedges with the oil and spread on a tray.","Roast the wedges for 30–35 minutes, turning halfway, until tender and golden. Adjust timing for the oven temperature.","Add the fish fingers on a separate part of the tray for their full packet cooking time, ensuring they are piping hot throughout.","Cook the peas according to their packet and serve everything together."],"student":true,"servings":1,"balanced":false},{"id":189,"title":"Green Bean, Potato & Egg Salad","type":"Lunch / Dinner","time":25,"about":"A hearty warm salad with a simple yogurt-mustard dressing.","need":["greenbeans","potato","eggs","greekyogurt","mustard"],"amounts":{"greenbeans":"120 g, trimmed","potato":"200 g, cut into small cubes","eggs":"2","greekyogurt":"3 tbsp","mustard":"1 tsp"},"equipment":"Two saucepans and a bowl","steps":["Cover the potato cubes with water and simmer for 10–12 minutes until tender. Add the green beans for the last 5–6 minutes, until cooked. Drain.","Meanwhile, cook the eggs in gently boiling water for 10–12 minutes until hard-boiled. Cool under cold water, peel, and quarter.","Mix the yogurt and mustard with a teaspoon of water. Toss with the warm potatoes and beans, then add the eggs."],"student":true,"servings":1,"balanced":true},{"id":190,"title":"Chicken & Green Bean Rice","type":"Lunch / Dinner","time":25,"about":"A straightforward chicken rice bowl with crisp green vegetables.","need":["rice","chicken","greenbeans","soyauce","oliveoil"],"amounts":{"rice":"75 g dry","chicken":"120 g already-cooked chicken, sliced","greenbeans":"150 g, trimmed and halved","soyauce":"2 tsp","oliveoil":"1 tsp"},"equipment":"Saucepan and nonstick frying pan with lid","steps":["Cook the rice according to the packet.","Heat the oil over medium heat. Add the green beans and 3 tablespoons water. Cover and cook for 5–6 minutes until tender.","Add the cooked chicken, soy sauce, and a splash of water. Cover and heat, stirring occasionally, until the chicken is steaming hot all the way through.","Serve over the rice immediately."],"student":true,"servings":1,"balanced":true},{"id":191,"title":"3-Ingredient Pizza Toasts","type":"Lunch / Dinner","time":12,"about":"Crispy toast with a rich tomato base and bubbly cheese.","need":["bread","tomatopaste","cheese"],"amounts":{"bread":"2 slices","tomatopaste":"1 tbsp","cheese":"50 g, grated"},"equipment":"Toaster and oven grill","steps":["Lightly toast the bread and place on a grill-safe tray.","Mix the tomato paste with 1 tablespoon water. Spread over the toast and top with cheese.","Grill until the cheese bubbles and turns golden, watching closely so the bread does not burn."],"student":true,"servings":1,"balanced":false},{"id":192,"title":"Tuna & Crunchy Salad Sandwich","type":"Lunch / Dinner","time":7,"about":"A reliable sandwich with a generous tuna filling.","need":["bread","tuna","saladmix","mayo"],"amounts":{"bread":"2 large slices, preferably wholegrain","tuna":"1 small tin, drained","saladmix":"1 large handful, washed if needed","mayo":"1 tbsp"},"equipment":"One bowl","steps":["Mix the drained tuna with the mayo.","Pile the tuna and salad leaves onto one bread slice, then close with the other.","Cut in half and serve."],"student":true,"servings":1,"balanced":true},{"id":193,"title":"Easy Egg & Potato Salad Bowl","type":"Lunch / Dinner","time":25,"about":"A filling salad bowl with a creamy two-ingredient dressing.","need":["saladmix","eggs","potato","greekyogurt","mustard"],"amounts":{"saladmix":"2 large handfuls, washed if needed","eggs":"2","potato":"200 g, cut into small cubes","greekyogurt":"3 tbsp","mustard":"1 tsp"},"equipment":"Two saucepans and a bowl","steps":["Cover the potatoes with water and simmer for 10–12 minutes until tender. Drain and let steam dry.","Meanwhile, hard-boil the eggs for 10–12 minutes, then cool under cold water, peel, and quarter.","Mix the yogurt and mustard with a teaspoon of water. Toss with the potatoes.","Arrange on the salad leaves with the eggs and serve."],"student":true,"servings":1,"balanced":true},{"id":194,"title":"Peach & Cinnamon Porridge","type":"Breakfast","time":8,"about":"Warm, creamy oats with a sweet cupboard-fruit topping.","need":["oats","milk","cannedpeaches","cinnamon"],"amounts":{"oats":"50 g","milk":"200 ml","cannedpeaches":"120 g, drained, packed in juice","cinnamon":"¼ tsp"},"equipment":"One saucepan","steps":["Put the oats, milk, and cinnamon in a saucepan.","Simmer gently for 5–6 minutes, stirring often, until creamy. Add a splash of water if needed.","Chop the peach slices and stir half into the oats. Spoon the rest on top and serve."],"student":true,"servings":1,"balanced":true},{"id":195,"title":"3-Ingredient Peach Yogurt Bowl","type":"Breakfast","time":5,"about":"A quick breakfast with fruit, oats, and creamy yogurt.","need":["greekyogurt","cannedpeaches","oats"],"amounts":{"greekyogurt":"170 g plain unsweetened","cannedpeaches":"120 g, drained, packed in juice","oats":"35 g"},"equipment":"One bowl","steps":["Spoon the yogurt into a bowl and stir in the oats.","Chop or slice the peaches and arrange on top.","Leave for a few minutes if you prefer softer oats, or eat straight away."],"student":true,"servings":1,"balanced":true},{"id":196,"title":"Simple Vegetable Rice Soup","type":"Lunch / Dinner","time":25,"about":"A cosy, budget-friendly soup with beans and freezer vegetables.","need":["rice","mixedveg","beans","stockcubes"],"amounts":{"rice":"50 g dry","mixedveg":"150 g frozen","beans":"150 g canned, drained and rinsed","stockcubes":"¼ reduced-salt cube"},"equipment":"One saucepan","steps":["Put the rice, stock cube, and 500 ml water in a saucepan. Bring to a gentle simmer.","Cook for the rice packet timing. Add the frozen vegetables early enough to cook for their full packet time.","Add the beans for the final 4–5 minutes and simmer until piping hot. Add water if you prefer more broth.","Serve when the rice and vegetables are tender."],"student":true,"servings":1,"balanced":true}];
