const campusTrendRecipes=[{"id":197,"title":"Creamy Dumpling Skillet","type":"Lunch / Dinner","time":20,"about":"Frozen dumplings get a creamy, veggie-filled upgrade.","need":["frozendumplings","mixedveg","cream","soyauce"],"amounts":{"frozendumplings":"6–8 frozen vegetable dumplings suitable for steaming","mixedveg":"120 g frozen","cream":"3 tbsp","soyauce":"1 tsp"},"equipment":"One nonstick frying pan with lid","steps":["Cook the frozen vegetables in the pan with a splash of water for the full packet time, until piping hot. Transfer to a bowl.","Steam the vegetable dumplings in the same pan with its lid on, following their packet steaming directions and adding water as needed, until fully cooked.","When the dumplings are fully cooked, return the vegetables. Add the cream, soy sauce, and 2 tablespoons water.","Simmer gently for 1–2 minutes until hot throughout and the sauce lightly coats the dumplings."],"student":true,"servings":1,"balanced":false,"source":{"name":"Trend inspiration — simplified version","url":"https://www.delish.com/cooking/recipe-ideas/g71664808/viral-recipes/"}},{"id":198,"title":"Cheeseburger Rice Bowl","type":"Lunch / Dinner","time":25,"about":"All the burger flavours in an easy rice bowl.","need":["rice","groundbeef","cheese","pickles","ketchup"],"amounts":{"rice":"75 g dry","groundbeef":"125 g lean","cheese":"25 g, grated","pickles":"2 small, sliced","ketchup":"1 tbsp"},"equipment":"Saucepan and nonstick frying pan","steps":["Cook the rice according to the packet.","Cook the beef in a good nonstick pan over medium heat, breaking it into small pieces. Cook thoroughly until it reaches 71°C in the centre, checked with a food thermometer.","Spoon the rice into a bowl and top with the hot beef and cheese.","Add the pickles and ketchup."],"student":true,"servings":1,"balanced":false,"source":{"name":"Trend inspiration — simplified version","url":"https://www.delish.com/cooking/recipe-ideas/g71664808/viral-recipes/"}},{"id":199,"title":"Hot Honey Chicken Tortilla Pizza","type":"Lunch / Dinner","time":15,"about":"A crisp tortilla base with a creamy topping and sweet heat.","need":["tortilla","chicken","cottagecheese","mozzarella","hothoney"],"amounts":{"tortilla":"1 large","chicken":"100 g already-cooked, finely shredded","cottagecheese":"60 g","mozzarella":"40 g, torn","hothoney":"1 tsp"},"equipment":"Oven and baking tray","steps":["Heat the oven to 200°C. Put the tortilla on a baking tray and bake for 2 minutes to firm the base.","Mash or blend the cottage cheese, then spread it thinly over the tortilla. Add the chicken and mozzarella.","Bake for 8–10 minutes until the edges are crisp and the chicken is piping hot all the way through.","Drizzle with hot honey and cut into wedges."],"student":true,"servings":1,"balanced":false},{"id":200,"title":"Cottage Cheese Pizza Dip & Toast","type":"Lunch / Dinner","time":15,"about":"A bubbly pizza-style dip, with toast for scooping.","need":["cottagecheese","tomatosauce","mozzarella","bread"],"amounts":{"cottagecheese":"150 g","tomatosauce":"3 tbsp","mozzarella":"40 g, torn","bread":"2 slices"},"equipment":"Oven, small oven-safe dish, and toaster","steps":["Heat the oven to 200°C. Mash the cottage cheese until smoother and spoon into a small oven-safe dish.","Spread the tomato sauce over the cottage cheese and add the mozzarella.","Bake for 10–12 minutes until bubbling and hot throughout.","Toast the bread, cut into fingers, and serve alongside for dipping."],"student":true,"servings":1,"balanced":false,"source":{"name":"Trend inspiration — simplified version","url":"https://canadiangrocer.com/high-protein-few-ingredient-recipes-driving-tiktok-food-trends"}},{"id":201,"title":"Smashed Chickpea Tacos","type":"Lunch / Dinner","time":15,"about":"Crispy little tacos with a filling chickpea-and-cheese centre.","need":["chickpeas","tortilla","cheese","salsa","oliveoil"],"amounts":{"chickpeas":"150 g canned, drained and rinsed","tortilla":"2 small","cheese":"35 g, grated","salsa":"3 tbsp","oliveoil":"1 tsp"},"equipment":"Bowl and nonstick frying pan","steps":["Mash the chickpeas with 1 tablespoon salsa. Add a teaspoon of water if very dry.","Divide the filling between the tortillas, sprinkle on the cheese, and fold in half.","Heat the oil over medium-low heat. Cook the folded tacos for 2–3 minutes per side until crisp, with hot filling and melted cheese.","Serve with the remaining salsa."],"student":true,"servings":1,"balanced":true,"source":{"name":"Trend inspiration — simplified version","url":"https://www.delish.com/cooking/recipe-ideas/g71664808/viral-recipes/"}},{"id":202,"title":"Cottage Cheese Pizza Bagel","type":"Lunch / Dinner","time":12,"about":"A toasted bagel with a creamy, cheesy pizza topping.","need":["bagel","tomatosauce","cottagecheese","cheese"],"amounts":{"bagel":"1, split","tomatosauce":"2 tbsp","cottagecheese":"80 g","cheese":"30 g, grated"},"equipment":"Toaster and oven grill","steps":["Lightly toast the bagel halves and put them on a grill-safe tray.","Spread with tomato sauce, then spoon over the cottage cheese and grated cheese.","Grill until bubbling, golden, and hot throughout. Watch closely so the bagel edges do not burn."],"student":true,"servings":1,"balanced":false,"source":{"name":"Trend inspiration — simplified version","url":"https://canadiangrocer.com/high-protein-few-ingredient-recipes-driving-tiktok-food-trends"}},{"id":203,"title":"Cheesy Spinach Egg Fold","type":"Breakfast","time":12,"about":"An egg-filled tortilla fold that works for a quick breakfast or lunch.","need":["tortilla","eggs","spinach","cheese","oliveoil"],"amounts":{"tortilla":"1 large","eggs":"2, beaten","spinach":"1 large handful, roughly chopped","cheese":"30 g, grated","oliveoil":"1 tsp"},"equipment":"One nonstick frying pan","steps":["Heat the oil over medium-low heat. Add the spinach and stir until wilted.","Pour in the eggs, spread evenly, and place the tortilla over the top. Press gently and cook until the egg is set underneath.","Carefully flip so the tortilla is underneath. Add the cheese to one half and fold over.","Cook gently for 1–2 minutes per side until the egg is fully set and cheese melted."],"student":true,"servings":1,"balanced":true},{"id":204,"title":"PB & Jam Overnight Oats","type":"Breakfast","time":5,"about":"A spoonable take on a peanut butter and jam sandwich.","need":["oats","milk","greekyogurt","peanutbutter","jam"],"amounts":{"oats":"50 g","milk":"100 ml","greekyogurt":"80 g plain","peanutbutter":"1 tbsp","jam":"2 tsp"},"equipment":"Jar or lidded bowl","steps":["Mix the oats, milk, and yogurt in a clean jar or bowl.","Swirl in the peanut butter and jam.","Cover and refrigerate for at least 6 hours or overnight. The 5-minute time is hands-on preparation.","Stir in the morning, adding a splash of water if too thick."],"student":true,"servings":1,"balanced":true,"waitMinutes":360,"wait":"6 hr chill"},{"id":205,"title":"Carrot Cake Overnight Oats","type":"Breakfast","time":8,"about":"Creamy oats with carrot, cinnamon, and a yogurt topping.","need":["oats","milk","carrot","greekyogurt","cinnamon"],"amounts":{"oats":"50 g","milk":"120 ml","carrot":"½ medium, finely grated","greekyogurt":"80 g plain","cinnamon":"¼ tsp"},"equipment":"Jar, lid, and grater","steps":["Mix the oats, milk, grated carrot, cinnamon, and half the yogurt in a clean jar.","Cover and refrigerate overnight, at least 6 hours. The 8-minute time is hands-on preparation.","In the morning, stir and top with the remaining yogurt. Add a splash of water if needed."],"student":true,"servings":1,"balanced":true,"waitMinutes":360,"wait":"6 hr chill"},{"id":206,"title":"Tuna Sushi-Style Rice Bowl","type":"Lunch / Dinner","time":20,"about":"A sushi-inspired bowl using tinned tuna and everyday toppings.","need":["rice","tuna","cucumber","mayo","soyauce"],"amounts":{"rice":"75 g dry","tuna":"1 small tin, drained","cucumber":"¼, diced","mayo":"1 tbsp","soyauce":"1 tsp"},"equipment":"Saucepan and bowl","steps":["Cook the rice according to the packet and spoon into a bowl while fresh and hot.","Mix the tuna with the mayo and soy sauce.","Top the rice with the tuna mixture and diced cucumber. Serve straight away."],"student":true,"servings":1,"balanced":false,"source":{"name":"Trend inspiration — simplified version","url":"https://www.delish.com/cooking/recipe-ideas/g71664808/viral-recipes/"}},{"id":207,"title":"One-Pot Onion & Cheese Pasta","type":"Lunch / Dinner","time":35,"about":"A simpler French-onion-inspired pasta with a cheesy finish.","need":["pasta","onion","butter","stockcubes","cheese"],"amounts":{"pasta":"90 g dry","onion":"1 medium, thinly sliced","butter":"10 g","stockcubes":"¼ reduced-salt cube","cheese":"35 g, grated"},"equipment":"One saucepan with lid","steps":["Melt the butter over medium-low heat. Add the onion and cook for 12–15 minutes, stirring often, until soft and golden. Add a splash of water if it sticks.","Add the pasta, stock cube, and 300 ml water. Bring to a gentle simmer.","Cook for the pasta packet time, stirring often and adding small splashes of water as needed, until the pasta is tender and the liquid coats it.","Take off the heat and stir in the cheese."],"student":true,"servings":1,"balanced":false,"source":{"name":"Trend inspiration — simplified version","url":"https://www.delish.com/cooking/recipe-ideas/g71664808/viral-recipes/"}},{"id":208,"title":"Hot Honey Halloumi Rice Bowl","type":"Lunch / Dinner","time":25,"about":"Salty, sweet, crunchy, and filling with just four ingredients.","need":["halloumi","rice","cucumber","hothoney"],"amounts":{"halloumi":"100 g, sliced","rice":"75 g dry","cucumber":"¼, diced","hothoney":"1 tsp"},"equipment":"Saucepan and nonstick frying pan","steps":["Cook the rice according to its packet.","Pat the halloumi dry. Cook in a good dry nonstick pan over medium heat for 1–2 minutes per side until golden.","Spoon the rice into a bowl and add the halloumi and cucumber.","Drizzle with hot honey and serve warm."],"student":true,"servings":1,"balanced":false},{"id":209,"title":"3-Ingredient Chocolate Cottage Mousse","type":"Dessert","time":5,"about":"A creamy chocolate dessert made in the blender.","need":["cottagecheese","cocoapowder","honey"],"amounts":{"cottagecheese":"150 g","cocoapowder":"1 tbsp unsweetened","honey":"2 tsp"},"equipment":"Blender and small bowl","steps":["Blend the cottage cheese, cocoa, and honey until completely smooth, stopping to scrape down the sides.","Add water a teaspoon at a time only if the blender needs help.","Spoon into a bowl and eat immediately, or cover and refrigerate for 30 minutes for a firmer texture. The 5-minute time excludes optional chilling."],"student":true,"servings":1,"balanced":false,"source":{"name":"Trend inspiration — simplified version","url":"https://www.delish.com/cooking/recipe-ideas/g71664808/viral-recipes/"}},{"id":210,"title":"Strawberry Chocolate Yogurt Bark","type":"Snack","time":10,"about":"A three-ingredient freezer treat for study-break snacking.","need":["greekyogurt","strawberry","chocolatechips"],"amounts":{"greekyogurt":"170 g plain","strawberry":"80 g, thinly sliced","chocolatechips":"15 g"},"equipment":"Small freezer-safe tray and baking paper","steps":["Line a small freezer-safe tray with baking paper. Spread the yogurt about 1 cm thick.","Press on the strawberry slices and scatter over the chocolate chips.","Freeze for at least 4 hours until solid. The 10-minute time is hands-on preparation.","Break into pieces and let stand for 2 minutes before eating. Keep any remaining pieces in the freezer."],"student":true,"servings":1,"balanced":false,"waitMinutes":240,"wait":"4 hr freeze"},{"id":211,"title":"Banana Bread Breakfast Mug","type":"Breakfast","time":8,"about":"A soft, oat-based banana mug bake for one.","need":["banana","eggs","oats","bakingpowder","cinnamon"],"amounts":{"banana":"1 small very ripe","eggs":"1","oats":"35 g, finely blended or crushed","bakingpowder":"¼ tsp","cinnamon":"¼ tsp"},"equipment":"Large microwave-safe mug and fork","steps":["Mash the banana thoroughly in a large microwave-safe mug with plenty of room to rise.","Beat in the egg, then stir in the finely ground oats, baking powder, and cinnamon.","Microwave on high for 90 seconds, then in 15–20 second bursts until risen and fully set in the centre with no wet egg mixture. Timing varies by microwave.","Let stand for 2 minutes before eating; the mug will be hot."],"student":true,"servings":1,"balanced":true},{"id":212,"title":"Berry Yogurt Custard Toast","type":"Breakfast","time":20,"about":"Crisp toast with a soft yogurt custard and jammy berries.","need":["bread","greekyogurt","eggs","strawberry","honey"],"amounts":{"bread":"2 thick slices","greekyogurt":"3 tbsp plain","eggs":"1","strawberry":"60 g, sliced","honey":"1 tsp"},"equipment":"Oven, tray, and bowl","steps":["Heat the oven to 180°C and line a tray with baking paper.","Press the centre of each bread slice down with a spoon to make a shallow well, leaving the crust intact.","Beat the yogurt, egg, and honey until smooth. Divide between the bread wells and top with strawberries.","Bake for 12–16 minutes until the custard is fully set with no wet egg mixture. Let cool slightly before eating."],"student":true,"servings":1,"balanced":true}];
