const thirdPantryRecipes=[{"id":213,"title":"3-Ingredient Creamy Spinach Tortellini","type":"Lunch / Dinner","time":15,"about":"Soft cheese tortellini in a creamy spinach sauce.","need":["tortellini","frozenspinach","creamcheese"],"amounts":{"tortellini":"200 g chilled cheese tortellini","frozenspinach":"100 g","creamcheese":"40 g"},"equipment":"One saucepan","steps":["Cook the frozen spinach with a little water in a saucepan for its full packet cooking time, until piping hot.","Add enough boiling water for the tortellini, bring back to a simmer, and cook the pasta for its packet time.","Reserve some cooking water, then drain carefully. Return to the pan off the heat and stir in the cream cheese. Add cooking water a spoonful at a time to make a sauce."],"student":true,"servings":1,"balanced":false},{"id":214,"title":"Tomato & Bean Tortellini Pot","type":"Lunch / Dinner","time":18,"about":"A filling one-pot pasta dinner with beans and greens.","need":["tortellini","kidneybeans","cannedtomatoes","spinach"],"amounts":{"tortellini":"150 g chilled cheese tortellini","kidneybeans":"120 g canned, drained and rinsed","cannedtomatoes":"200 g","spinach":"60 g"},"equipment":"One saucepan","steps":["Simmer the tomatoes and 100 ml water in a saucepan for 5 minutes.","Add the kidney beans and tortellini. Simmer for the tortellini packet time, stirring gently and adding water if the sauce is too thick.","Stir in the spinach and cook for another 2 minutes until wilted and everything is piping hot."],"student":true,"servings":1,"balanced":true},{"id":215,"title":"Smoky Kidney Bean Rice","type":"Lunch / Dinner","time":25,"about":"An easy tomato-and-bean rice bowl with gentle smoky warmth.","need":["rice","kidneybeans","cannedtomatoes","paprika"],"amounts":{"rice":"75 g dry","kidneybeans":"150 g canned, drained and rinsed","cannedtomatoes":"200 g","paprika":"½ tsp smoked or sweet"},"equipment":"One saucepan with lid","steps":["Put the rice, tomatoes, paprika, and 200 ml water in a saucepan. Bring to a gentle simmer.","Cover and cook for the rice packet timing, stirring occasionally and adding small splashes of water if needed.","Add the kidney beans for the final 5 minutes. Serve when the rice is tender and beans are piping hot."],"student":true,"servings":1,"balanced":true},{"id":216,"title":"Kidney Bean & Corn Quesadilla","type":"Lunch / Dinner","time":12,"about":"Crisp outside, melty and filling inside.","need":["tortilla","kidneybeans","corn","cheese"],"amounts":{"tortilla":"1 large","kidneybeans":"120 g canned, drained and rinsed","corn":"60 g canned, drained","cheese":"35 g, grated"},"equipment":"Bowl and nonstick frying pan","steps":["Mash the kidney beans roughly with a fork and 1 tablespoon water.","Spread over half the tortilla. Add the corn and cheese, then fold closed.","Cook in a dry nonstick pan over medium-low heat for 3–4 minutes per side, until crisp and the filling is piping hot."],"student":true,"servings":1,"balanced":true},{"id":217,"title":"Sweet Chili Chicken Noodles","type":"Lunch / Dinner","time":15,"about":"A quick noodle bowl using cooked chicken and freezer vegetables.","need":["noodles","chicken","mixedveg","sweetchili"],"amounts":{"noodles":"75 g dry","chicken":"100 g already-cooked, sliced","mixedveg":"150 g frozen","sweetchili":"1 tbsp"},"equipment":"One saucepan","steps":["Cook the frozen vegetables in boiling water for their packet time, adding the noodles for their full packet time too. Drain.","Return to the pan with the cooked chicken, sweet chili sauce, and 3 tablespoons water.","Cover and heat gently, stirring, until the chicken is steaming hot throughout. Add a splash of water if needed."],"student":true,"servings":1,"balanced":true},{"id":218,"title":"Sticky Sweet Chili Tofu Rice","type":"Lunch / Dinner","time":25,"about":"Golden tofu, green broccoli, and a simple sticky glaze.","need":["rice","tofu","broccoli","sweetchili","oliveoil"],"amounts":{"rice":"75 g dry","tofu":"150 g firm, patted dry and cubed","broccoli":"120 g, small florets","sweetchili":"1 tbsp","oliveoil":"1 tsp"},"equipment":"Saucepan and nonstick frying pan with lid","steps":["Cook the rice according to the packet.","Heat the oil over medium heat. Cook the tofu for 6–8 minutes, turning until golden. Transfer to a plate.","Add the broccoli and 3 tablespoons water to the pan. Cover and cook for 4–6 minutes until tender.","Return the tofu, add the sweet chili sauce and 1 tablespoon water, and toss until hot. Serve over the rice."],"student":true,"servings":1,"balanced":true},{"id":219,"title":"Easy Yogurt-Dough Pizza","type":"Lunch / Dinner","time":30,"about":"A homemade pizza base with just flour and yogurt.","need":["selfraisingflour","greekyogurt","tomatosauce","cheese"],"amounts":{"selfraisingflour":"100 g, plus a little for dusting","greekyogurt":"90 g","tomatosauce":"2 tbsp","cheese":"50 g, grated"},"equipment":"Bowl, oven, and baking tray","steps":["Heat the oven to 220°C. Mix the flour and yogurt into a soft dough, adding a teaspoon of water if dry.","Knead briefly on a floured surface. Roll into a thin 18–20 cm round and put on a lined baking tray.","Bake the plain base for 5 minutes. Spread with tomato sauce and add the cheese.","Bake for another 10–12 minutes until the base is cooked underneath and the cheese is golden."],"student":true,"servings":1,"balanced":false},{"id":220,"title":"Cheesy Spinach Pinwheels","type":"Lunch / Dinner","time":30,"about":"Soft, savoury rolls with a spinach-and-cheese swirl.","need":["selfraisingflour","greekyogurt","frozenspinach","cheese"],"amounts":{"selfraisingflour":"100 g, plus a little for dusting","greekyogurt":"90 g","frozenspinach":"80 g","cheese":"40 g, grated"},"equipment":"Saucepan, bowl, oven, and tray","steps":["Heat the oven to 200°C. Cook the spinach according to its packet until piping hot, then cool briefly and squeeze out the excess water.","Mix the flour and yogurt into a soft dough. Roll on a floured surface into a rectangle about 5 mm thick.","Scatter on the spinach and cheese. Roll up from the long side and cut into four thick rounds.","Put cut-side up on a lined tray and bake for 18–22 minutes, until golden and cooked through."],"student":true,"servings":1,"balanced":false},{"id":221,"title":"Classic Egg Mayo Roll","type":"Lunch / Dinner","time":18,"about":"A proper soft-roll sandwich with a simple egg filling.","need":["breadrolls","eggs","mayo","cucumber"],"amounts":{"breadrolls":"1 large","eggs":"2","mayo":"1 tbsp","cucumber":"¼, thinly sliced"},"equipment":"Saucepan and bowl","steps":["Hard-boil the eggs for 10–12 minutes. Cool under cold water, peel, and chop.","Mix the eggs with the mayo.","Split the bread roll and fill with the cucumber and egg mixture."],"student":true,"servings":1,"balanced":false},{"id":222,"title":"Sweet Chili Chicken Salad Roll","type":"Lunch / Dinner","time":8,"about":"A fresh chicken roll with a creamy sweet chili dressing.","need":["breadrolls","chicken","saladmix","greekyogurt","sweetchili"],"amounts":{"breadrolls":"1 large, preferably wholegrain","chicken":"100 g ready-to-eat cooked chicken, chilled","saladmix":"1 large handful, washed if needed","greekyogurt":"2 tbsp","sweetchili":"2 tsp"},"equipment":"One bowl","steps":["Mix the yogurt and sweet chili sauce, then fold in the cooked chicken.","Split the roll, add the salad leaves, and spoon in the chicken.","Serve immediately, using cooked chicken that has been stored according to its pack instructions."],"student":true,"servings":1,"balanced":true},{"id":223,"title":"No-Bake Berry Cheesecake Cup","type":"Dessert","time":10,"about":"A small creamy cheesecake-style treat without an oven.","need":["digestives","creamcheese","greekyogurt","jam"],"amounts":{"digestives":"2 biscuits","creamcheese":"40 g","greekyogurt":"80 g plain","jam":"2 tsp berry jam"},"equipment":"Small glass, bowl, and spoon","steps":["Crush the biscuits roughly and put most in the bottom of a small glass.","Beat the cream cheese and yogurt until smooth, then swirl in half the jam.","Spoon over the crumbs. Add the remaining jam and biscuit crumbs on top.","Eat straight away, or cover and chill for 30 minutes for a firmer texture."],"student":true,"servings":1,"balanced":false},{"id":224,"title":"Banana Biscuit Yogurt Pot","type":"Breakfast","time":5,"about":"Crunchy, creamy layers for a very easy breakfast.","need":["digestives","greekyogurt","banana","peanutbutter"],"amounts":{"digestives":"2 biscuits, roughly crushed","greekyogurt":"170 g plain","banana":"1 small, sliced","peanutbutter":"1 tbsp"},"equipment":"One glass or bowl","steps":["Spoon half the yogurt into a glass or bowl.","Add half the banana and biscuit crumbs, then repeat the layers.","Swirl the peanut butter over the top and eat straight away."],"student":true,"servings":1,"balanced":false},{"id":225,"title":"Vanilla Berry Overnight Oats","type":"Breakfast","time":5,"about":"A creamy make-ahead breakfast with a gentle vanilla flavour.","need":["oats","milk","greekyogurt","vanilla","frozenberries"],"amounts":{"oats":"50 g","milk":"100 ml","greekyogurt":"80 g plain","vanilla":"¼ tsp","frozenberries":"100 g, prepared according to the packet"},"equipment":"Jar or lidded bowl","steps":["Mix the oats, milk, yogurt, and vanilla in a clean jar. Cover and refrigerate for at least 6 hours or overnight.","Prepare the berries according to the packet, including any required heating, then cool and refrigerate separately.","In the morning, stir the oats, loosen with a splash of water if needed, and top with the berries."],"student":true,"servings":1,"balanced":true,"waitMinutes":360,"wait":"6 hr chill"},{"id":226,"title":"Vanilla Mug Sponge","type":"Dessert","time":7,"about":"A small warm sponge cake made with cupboard basics.","need":["selfraisingflour","milk","sugar","oliveoil","vanilla"],"amounts":{"selfraisingflour":"4 level tbsp (about 35 g)","milk":"3 tbsp","sugar":"1 tbsp","oliveoil":"1 tbsp mild-flavoured","vanilla":"¼ tsp"},"equipment":"Large microwave-safe mug and spoon","steps":["Stir the flour and sugar in a large microwave-safe mug with plenty of room to rise.","Mix in the milk, oil, and vanilla until smooth, scraping the bottom corners.","Microwave on high for 60 seconds, then in 10–15 second bursts until the top is set and a skewer comes out without wet batter. Timing varies by microwave.","Leave for 2 minutes before eating; the mug will be hot."],"student":true,"servings":1,"balanced":false},{"id":227,"title":"Spinach & Bean Skillet Eggs","type":"Lunch / Dinner","time":20,"about":"A filling, veggie-packed pan of eggs in tomato sauce.","need":["frozenspinach","kidneybeans","eggs","cannedtomatoes"],"amounts":{"frozenspinach":"100 g","kidneybeans":"120 g canned, drained and rinsed","eggs":"2","cannedtomatoes":"200 g"},"equipment":"One frying pan with lid","steps":["Cook the spinach in the pan with a splash of water for its full packet time, until piping hot.","Add the tomatoes and kidney beans. Simmer for 5 minutes, adding a splash of water if needed.","Make two wells and crack in the eggs. Cover and cook gently until both whites and yolks are fully set, about 5–7 minutes."],"student":true,"servings":1,"balanced":true},{"id":228,"title":"Sweet Chili Peanut Tofu Noodles","type":"Lunch / Dinner","time":15,"about":"Creamy peanut noodles with tofu and a fresh cucumber crunch.","need":["noodles","tofu","peanutbutter","sweetchili","cucumber"],"amounts":{"noodles":"75 g dry","tofu":"150 g firm, cubed","peanutbutter":"1 tbsp","sweetchili":"1 tbsp","cucumber":"¼, cut into sticks"},"equipment":"One saucepan and bowl","steps":["Cook the noodles according to the packet. Add the tofu to simmer for the last 4 minutes, or longer if its packet requires it.","Mix the peanut butter and sweet chili sauce in a bowl with 2 tablespoons hot cooking water.","Drain the noodles and tofu, reserving a little water. Toss with the sauce, loosening as needed.","Top with the cucumber sticks and serve."],"student":true,"servings":1,"balanced":true}];
for(const x of thirdPantryRecipes){if(!recipes.some(r=>r.id===x.id))recipes.push(x)}
Object.assign(paintedIngredientImages,{"kidneybeans":"assets/ingredients/kidneybeans.webp","frozenspinach":"assets/ingredients/frozenspinach.webp","tortellini":"assets/ingredients/tortellini.webp","selfraisingflour":"assets/ingredients/selfraisingflour.webp","breadrolls":"assets/ingredients/breadrolls.webp","digestives":"assets/ingredients/digestives.webp","vanilla":"assets/ingredients/vanilla.webp","sweetchili":"assets/ingredients/sweetchili.webp"});

