const detailedRecipeMethods=[{"id":1,"need":["bread","avocado","eggs"],"amounts":{"bread":"2 slices","avocado":"½ medium","eggs":"2"},"servings":1,"equipment":"Toaster, saucepan, and bowl","steps":["Toast bread (2 slices) for 2–3 minutes until golden. Scoop avocado (½ medium) into a bowl and mash with a fork, leaving some texture.","Put eggs (2) in a saucepan, cover with water, and bring to a gentle boil. Cook for 10–12 minutes for firm whites and yolks. Cool under cold water, peel, and slice.","Spread the avocado over the warm toast, add the sliced eggs, and serve immediately."],"time":18,"title":"Avocado Toast"},{"id":2,"need":["eggs","cheese","milk"],"amounts":{"eggs":"2","cheese":"35 g, grated","milk":"1 tbsp, 15 ml"},"servings":1,"equipment":"Bowl and good nonstick frying pan","steps":["Beat eggs (2) with milk (1 tbsp, 15 ml) for 20–30 seconds until the white and yolk are combined. Set out cheese (35 g, grated).","Warm a small nonstick pan over medium-low heat. Pour in the eggs and tilt to cover the base. Cook for 2–3 minutes, gently pulling set edges toward the centre so uncooked egg can flow underneath.","Sprinkle cheese over one half. Fold the other half over and cook gently for another 1–2 minutes until the cheese melts and the egg is fully set, with no liquid egg remaining. Slide onto a plate."],"time":10,"title":"Cheesy Omelette"},{"id":3,"need":["pasta","tomato","oliveoil","cheese"],"amounts":{"pasta":"90 g dry","tomato":"2 medium, 240 g","oliveoil":"1 tsp, 5 ml","cheese":"35 g, grated"},"servings":1,"equipment":"Saucepan and frying pan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Dice tomato (2 medium, 240 g) into 1 cm pieces. Warm olive oil (1 tsp, 5 ml) over medium heat, add the tomatoes, and cook for 8–10 minutes, stirring, until soft and saucy. Add 1–2 tablespoons pasta water if dry.","Add the drained pasta and cheese (35 g, grated). Toss over low heat for 1 minute, adding a little reserved water until the sauce coats the pasta. Serve hot."],"time":20,"title":"Tomato Pasta"},{"id":4,"need":["chicken","rice","carrot","oliveoil"],"amounts":{"chicken":"150 g raw boneless chicken, cut into 2 cm pieces","rice":"75 g dry","carrot":"1 medium, 80 g","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Two saucepans and a nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Peel carrot (1 medium, 80 g) and cut into thin half-moons. Simmer in a small pan of water for 5–7 minutes until tender, then drain.","Heat olive oil (1 tsp, 5 ml) in a nonstick frying pan over medium heat. Add chicken (150 g raw boneless chicken, cut into 2 cm pieces) and cook for about 7–10 minutes, turning often. Check the thickest piece reaches 74°C with a food thermometer; continue cooking if needed.","Divide the rice, cooked chicken, and carrot into a bowl. Spoon over any juices from the frying pan and serve piping hot."],"time":25,"title":"Chicken Rice Bowl"},{"id":5,"need":["yogurt","strawberry","banana","honey"],"amounts":{"yogurt":"170 g plain","strawberry":"100 g","banana":"½ small","honey":"1 tsp"},"servings":1,"equipment":"Bowl and chopping board","steps":["Wash, hull, and slice strawberries (100 g). Peel and slice banana (½ small).","Spoon yogurt (170 g plain) into a bowl. Arrange the fruit on top and drizzle with honey (1 tsp).","Serve straight away, or cover and refrigerate while you finish preparing breakfast."],"time":5,"title":"Berry Yogurt Bowl"},{"id":6,"need":["tortilla","cheese","tomato"],"amounts":{"tortilla":"1 large or 2 small","cheese":"50 g","tomato":"1 medium, 120 g"},"servings":1,"equipment":"Chopping board and nonstick frying pan","steps":["Dice tomato (1 medium, 120 g) and blot away excess juice so the tortilla stays crisp. Spread cheese (50 g) and the tomato over half of tortillas (1 large or 2 small), leaving a 1 cm border.","Fold closed and place in a dry nonstick pan over medium-low heat. Cook for 2–3 minutes per side, pressing gently, until both sides are golden and the cheese has melted.","Rest on a board for 1 minute so the filling settles. Cut into wedges and serve hot."],"time":10,"title":"Cheese Quesadilla"},{"id":7,"need":["rice","eggs","carrot","mushroom","oliveoil"],"amounts":{"rice":"75 g dry","eggs":"2","carrot":"1 medium, 80 g","mushroom":"150 g","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Saucepan and large nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Finely dice carrot (1 medium, 80 g) and slice mushroom (150 g). Heat olive oil (1 tsp, 5 ml) over medium heat; cook the carrot with 1 tablespoon water for 4 minutes, then add the mushrooms and cook for 4–5 minutes until softened.","Beat eggs (2), push the vegetables to one side, and pour into the clear part of the pan. Stir for 1–2 minutes until fully set.","Add the freshly cooked rice. Break up any clumps and stir-fry for 2–3 minutes until everything is steaming hot. Serve immediately."],"time":30,"title":"Veggie Fried Rice"},{"id":8,"need":["banana","oats","eggs","milk"],"amounts":{"banana":"1 small, peeled","oats":"40 g","eggs":"1","milk":"2 tbsp"},"servings":1,"equipment":"Bowl or blender and good nonstick frying pan","steps":["Mash banana (1 small, peeled) very thoroughly. Beat in eggs (1) and milk (2 tbsp), then stir in oats (40 g); blend briefly if you prefer a smoother batter.","Leave the batter for 5 minutes so the oats absorb the liquid. It should be thick enough to fall slowly from a spoon; add water 1 teaspoon at a time if too stiff.","Warm a good nonstick pan over medium-low heat. Spoon in small 2-tablespoon pancakes, leaving space to flip them.","Cook for 2–3 minutes on the first side until the edges set. Turn carefully and cook for another 2 minutes until golden and cooked through with no wet egg mixture. Serve warm."],"time":20,"title":"Banana Oat Pancakes"},{"id":9,"need":["lettuce","tomato","cucumber","oliveoil"],"amounts":{"lettuce":"2 large leaves, washed","tomato":"1 medium, 120 g","cucumber":"¼ medium, 80 g","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Chopping board and salad bowl","steps":["Wash and dry lettuce (2 large leaves, washed). Cut tomato (1 medium, 120 g) into wedges and cucumber (¼ medium, 80 g) into bite-size pieces.","Put the vegetables in a bowl. Add olive oil (1 tsp, 5 ml) and toss gently for about 20 seconds so the leaves are lightly coated.","Serve immediately so the leaves stay crisp. If preparing ahead, keep the oil separate until serving."],"time":8,"title":"Garden Salad"},{"id":10,"need":["pasta","mushroom","cream","cheese"],"amounts":{"pasta":"90 g dry","mushroom":"150 g","cream":"60 ml","cheese":"20 g"},"servings":1,"equipment":"Saucepan and frying pan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Wipe mushroom (150 g) clean and slice thinly. Put in a nonstick pan over medium heat with 2 tablespoons water. Cook for 6–8 minutes, stirring, until softened and most moisture has evaporated.","Lower the heat. Stir in cream (60 ml) and cheese (20 g), then simmer very gently for 1–2 minutes until the cheese melts. Avoid a hard boil.","Add the pasta and toss for 1 minute. Add reserved cooking water 1 tablespoon at a time until the sauce is glossy and coats the pasta."],"time":20,"title":"Creamy Mushroom Pasta"},{"id":11,"need":["bread","eggs","cheese","tomato"],"amounts":{"bread":"2 slices","eggs":"2","cheese":"25 g","tomato":"1 medium, 120 g"},"servings":1,"equipment":"Saucepan, toaster, and chopping board","steps":["Put eggs (2) in a saucepan and cover with water. Bring to a gentle boil and cook for 10–12 minutes until hard-boiled. Cool under cold water, peel, and slice.","Toast bread (2 slices) and slice tomato (1 medium, 120 g). Lay cheese (25 g) on one warm bread slice.","Add the eggs and tomato, close with the other slice, and press gently. Cut in half and serve."],"time":18,"title":"Egg Sandwich"},{"id":12,"need":["bread","peanutbutter","banana","honey"],"amounts":{"bread":"2 slices","peanutbutter":"1 tbsp, 15 g","banana":"1 small, peeled","honey":"1 tsp"},"servings":1,"equipment":"Toaster and chopping board","steps":["Toast bread (2 slices) for 2–3 minutes until golden and crisp. Peel and slice banana (1 small, peeled).","Spread peanut butter (1 tbsp, 15 g) over the warm toast, dividing it evenly. Arrange the banana slices on top.","Drizzle with honey (1 tsp) and eat straight away while the toast is crisp."],"time":5,"title":"PB Banana Toast"},{"id":13,"need":["tortilla","beans","cheese","tomato"],"amounts":{"tortilla":"1 large or 2 small","beans":"150 g canned white beans, drained and rinsed","cheese":"35 g, grated","tomato":"1 medium, 120 g"},"servings":1,"equipment":"Small saucepan and nonstick frying pan","steps":["Put beans (150 g canned white beans, drained and rinsed) in a small saucepan with 2 tablespoons water. Heat over medium-low heat for 3–4 minutes, stirring, until piping hot. Mash about half with a fork.","Dice tomato (1 medium, 120 g). Warm tortillas (1 large or 2 small) in a dry pan for about 20 seconds per side until flexible.","Spoon the beans down the middle, then add cheese (35 g, grated) and the tomato. Fold in the sides and roll tightly.","Place seam-side down in the dry pan over low heat for 1–2 minutes per side, until lightly crisp and the cheese melts."],"time":12,"title":"Bean & Cheese Wrap"},{"id":14,"need":["strawberry","banana","milk","yogurt"],"amounts":{"strawberry":"100 g","banana":"1 small, peeled","milk":"150 ml","yogurt":"80 g"},"servings":1,"equipment":"Blender","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. ","Put milk (150 ml), yogurt (80 g), strawberries (100 g), banana (1 small, peeled) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":5,"title":"Strawberry Smoothie"},{"id":15,"need":["tomato","onion","garlic","cream"],"amounts":{"tomato":"3 medium, 350 g","onion":"½ medium, 60 g","garlic":"1 small clove","cream":"2 tbsp"},"servings":1,"equipment":"Saucepan and stick blender","steps":["Chop onion (½ medium, 60 g) and garlic (1 small clove) finely. Chop tomato (3 medium, 350 g) into 2 cm pieces.","Put the onion in a saucepan with 3 tablespoons water. Cover and cook over medium-low heat for 5 minutes until softened, adding water if needed. Stir in the garlic for 30 seconds.","Add the tomatoes and 200 ml water. Bring to a simmer and cook uncovered for 15 minutes, stirring occasionally, until the tomatoes collapse.","Remove from the heat and blend carefully until smooth, following your blender’s instructions for hot liquids. Stir in cream (2 tbsp) and warm gently for 1–2 minutes without boiling. Add water if too thick."],"time":30,"title":"Tomato Soup"},{"id":16,"need":["tortilla","chicken","cheese","bellpepper"],"amounts":{"tortilla":"1 large or 2 small","chicken":"120 g ready-to-eat cooked chicken, shredded","cheese":"40 g","bellpepper":"½ small"},"servings":1,"equipment":"Nonstick frying pan with lid","steps":["Thinly slice bell pepper (½ small). Put in the pan with 2 tablespoons water, cover, and cook over medium heat for 4–5 minutes until softened.","Add chicken (120 g ready-to-eat cooked chicken, shredded) and 1 tablespoon water. Cover and heat for 3–4 minutes, stirring, until the chicken reaches 74°C throughout. Transfer to a plate and wipe the pan dry.","Fill half of tortillas (1 large or 2 small) with the chicken, pepper, and cheese (40 g). Fold closed.","Cook in the dry pan over medium-low heat for 2–3 minutes per side, until crisp and the cheese melts. Rest for 1 minute, then cut into wedges."],"time":18,"title":"Chicken Quesadilla"},{"id":17,"need":["pasta","pesto","cheese"],"amounts":{"pasta":"90 g dry","pesto":"1 tbsp, 20 g","cheese":"35 g, grated"},"servings":1,"equipment":"One saucepan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Return the drained pasta to the pan off the heat. Stir in pesto (1 tbsp, 20 g) and 2 tablespoons reserved cooking water.","Add cheese (35 g, grated) and toss until evenly coated. Loosen with a little more cooking water if needed, then serve."],"time":15,"title":"Pesto Pasta"},{"id":18,"need":["pasta","tuna","mayo","cucumber"],"amounts":{"pasta":"90 g dry","tuna":"1 small tin, about 100 g drained","mayo":"1 tbsp","cucumber":"¼ medium, 80 g"},"servings":1,"equipment":"Saucepan, colander, and bowl","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","For a cool salad, rinse the drained pasta briefly under cold running water, drain well, and shake off the excess. Dice cucumber (¼ medium, 80 g).","Mix tuna (1 small tin, about 100 g drained) and mayo (1 tbsp) in a bowl. Fold in the pasta and cucumber until coated.","Eat straight away, or cover and refrigerate promptly until serving."],"time":18,"title":"Tuna Pasta Salad"},{"id":19,"need":["oats","apple","milk","honey","cinnamon"],"amounts":{"oats":"50 g","apple":"1 small","milk":"200 ml","honey":"1 tsp","cinnamon":"¼ tsp"},"servings":1,"equipment":"Saucepan and grater","steps":["Wash apple (1 small), remove the core, and grate or dice into 1 cm pieces. Put in a saucepan with oats (50 g), milk (200 ml), and cinnamon (¼ tsp).","Bring to a gentle simmer over medium-low heat. Cook for 5–7 minutes, stirring often, until the oats are soft and the apple is tender. Add water a tablespoon at a time if too thick.","Spoon into a bowl, drizzle over honey (1 tsp), and let cool for 1 minute before eating."],"time":12,"title":"Apple Cinnamon Oats"},{"id":20,"need":["pasta","garlic","butter","cheese"],"amounts":{"pasta":"90 g dry","garlic":"1 small clove","butter":"10 g","cheese":"35 g, grated"},"servings":1,"equipment":"Saucepan and small frying pan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Finely chop garlic (1 small clove). Melt butter (10 g) in a small pan over low heat. Add the garlic and cook for 30–60 seconds until fragrant; keep it pale so it does not become bitter.","Add 2 tablespoons pasta water, the drained pasta, and cheese (35 g, grated). Toss over low heat for about 1 minute, adding more water if needed for a light glossy sauce."],"time":15,"title":"Garlic Butter Pasta"},{"id":21,"need":["rice","beans","tomatosauce"],"amounts":{"rice":"75 g dry","beans":"150 g canned white beans, drained and rinsed","tomatosauce":"150 g"},"servings":1,"equipment":"Saucepan and small saucepan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Put beans (150 g canned white beans, drained and rinsed) and tomato sauce (150 g) in a small saucepan. Simmer gently for 5–7 minutes, stirring, until the beans are piping hot. Add 1–2 tablespoons water if thick.","Spoon the rice into a bowl and add the hot beans and tomato sauce. Serve immediately."],"time":25,"title":"Rice and Beans Bowl"},{"id":22,"need":["eggs","spinach","cheese"],"amounts":{"eggs":"2","spinach":"50 g","cheese":"35 g, grated"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Wash and roughly chop spinach (50 g). Put in a nonstick pan with 1 tablespoon water and cook over medium-low heat for 1–2 minutes until wilted. Let excess moisture evaporate.","Beat eggs (2) in a bowl and pour over the spinach. Cook gently for 2–3 minutes, drawing the set edges toward the middle.","Sprinkle cheese (35 g, grated) on one half, fold over, and cook for another 1–2 minutes until the cheese melts and the egg is fully set throughout."],"time":10,"title":"Spinach Omelette"},{"id":23,"need":["potato","cheese","beans"],"amounts":{"potato":"1 large baking potato, 250–300 g","cheese":"35 g, grated","beans":"150 g canned white beans, drained and rinsed"},"servings":1,"equipment":"Microwave, plate, and saucepan","steps":["Scrub potato (1 large baking potato, 250–300 g), prick all over with a fork, and place on a microwave-safe plate. Microwave on high for 5 minutes, turn, then cook for 3–5 minutes more. Continue in 1-minute bursts until soft all the way through.","Meanwhile, heat beans (150 g canned white beans, drained and rinsed) with 2 tablespoons water in a saucepan for 3–4 minutes, stirring until piping hot.","Split the potato and fluff the flesh with a fork. Add the hot beans and cheese (35 g, grated). Microwave for 20–30 seconds more if needed to melt the cheese. Stand for 1 minute before eating."],"time":20,"title":"Baked Potato Bowl"},{"id":24,"need":["chicken","noodles","carrot","onion"],"amounts":{"chicken":"150 g raw boneless chicken, cut into 2 cm pieces","noodles":"60 g dry","carrot":"1 medium, 80 g","onion":"½ medium, 60 g"},"servings":1,"equipment":"One saucepan","steps":["Cut chicken (150 g raw boneless chicken, cut into 2 cm pieces) into 2 cm pieces. Peel and finely dice carrot (1 medium, 80 g) and onion (½ medium, 60 g).","Put the chicken, carrot, and onion in a saucepan with 550 ml water. Bring to a gentle simmer and cook for 12–15 minutes, until the carrot is tender and the thickest chicken piece reaches 74°C.","Add noodles (60 g dry) and simmer for their full packet cooking time, usually 3–6 minutes. Add more boiling water if you want a looser soup.","Check the noodles are tender and everything is steaming hot, then ladle into a bowl."],"time":25,"title":"Chicken Noodle Soup"},{"id":25,"need":["yogurt","strawberry","apple","honey"],"amounts":{"yogurt":"170 g plain","strawberry":"100 g","apple":"½ small","honey":"1 tsp"},"servings":1,"equipment":"Glass or bowl and chopping board","steps":["Wash, hull, and slice strawberries (100 g). Core and finely dice apple (½ small).","Spoon half of yogurt (170 g plain) into a glass, add half the fruit, then repeat the layers.","Drizzle honey (1 tsp) over the top and serve immediately, or cover and keep refrigerated until needed."],"time":5,"title":"Fruit & Yogurt Parfait"},{"id":26,"need":["bread","cheese","tomato","butter"],"amounts":{"bread":"2 slices","cheese":"50 g","tomato":"1 medium, 120 g","butter":"10 g"},"servings":1,"equipment":"Nonstick frying pan","steps":["Slice tomato (1 medium, 120 g) thinly and blot away excess juice. Put cheese (50 g) and the tomato between bread (2 slices).","Spread butter (10 g) thinly on the outsides of the sandwich. Warm a nonstick pan over medium-low heat.","Cook the sandwich for 3–4 minutes on each side, pressing gently, until evenly golden and the cheese has melted. Lower the heat if it browns before the centre is hot.","Rest for 1 minute, cut in half, and serve."],"time":12,"title":"Tomato Grilled Cheese"},{"id":27,"need":["tofu","bellpepper","carrot","oliveoil"],"amounts":{"tofu":"200 g","bellpepper":"1 small","carrot":"1 medium, 80 g","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"One large nonstick frying pan with lid","steps":["Pat tofu (200 g) dry and cut into 2 cm cubes. Slice bell pepper (1 small) and cut carrot (1 medium, 80 g) into thin matchsticks.","Heat olive oil (1 tsp, 5 ml) over medium heat. Cook the tofu for 6–8 minutes, turning, until golden. Transfer to a plate.","Add the carrot, pepper, and 2 tablespoons water to the pan. Cover for 3 minutes, then uncover and stir-fry for another 2–3 minutes until tender-crisp.","Return the tofu and toss for 1–2 minutes until hot. Serve immediately."],"time":20,"title":"Tofu Veggie Stir-Fry"},{"id":28,"need":["frozenberries","banana","milk","honey"],"amounts":{"frozenberries":"100 g","banana":"1 small, peeled","milk":"200 ml","honey":"1 tsp"},"servings":1,"equipment":"Blender and small pan if the berry packet requires heating","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. Prepare the frozen berries according to their packet, including any required heating; cool completely before blending.","Put milk (200 ml), frozen berries (100 g), banana (1 small, peeled), honey (1 tsp) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":8,"title":"Frozen Berry Smoothie"},{"id":29,"need":["tomato","mozzarella","basil","oliveoil"],"amounts":{"tomato":"2 medium, 240 g","mozzarella":"100 g","basil":"5–6 leaves","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Chopping board and plate","steps":["Wash tomato (2 medium, 240 g) and cut into 5 mm slices. Drain mozzarella (100 g) and slice to a similar thickness.","Arrange the tomato and mozzarella on a plate, alternating the slices. Tear basil (5–6 leaves) over the top.","Drizzle with olive oil (1 tsp, 5 ml) just before serving. Serve immediately, or refrigerate until ready to dress."],"time":8,"title":"Caprese Salad"},{"id":30,"need":["tomato","cucumber","feta","oliveoil","onion"],"amounts":{"tomato":"1 medium, 120 g","cucumber":"¼ medium, 80 g","feta":"50 g","oliveoil":"1 tsp, 5 ml","onion":"¼ small, thinly sliced"},"servings":1,"equipment":"Chopping board and bowl","steps":["Cut tomato (1 medium, 120 g) into wedges, dice cucumber (¼ medium, 80 g), and thinly slice onion (¼ small, thinly sliced).","Combine in a bowl and crumble over feta (50 g). Add olive oil (1 tsp, 5 ml) and toss gently so the feta remains in small chunks.","Serve straight away, or cover and refrigerate until needed."],"time":10,"title":"Greek Salad"},{"id":31,"need":["tortilla","chicken","lettuce","parmesan","mayo"],"amounts":{"tortilla":"1 large or 2 small","chicken":"120 g ready-to-eat cooked chicken, shredded","lettuce":"2 large leaves, washed","parmesan":"15 g","mayo":"1 tbsp"},"servings":1,"equipment":"Bowl and chopping board","steps":["Wash and dry lettuce (2 large leaves, washed), then shred. Mix mayo (1 tbsp) with parmesan (15 g) and 1 teaspoon water to make a loose dressing.","Fold in chicken (120 g ready-to-eat cooked chicken, shredded). Lay tortillas (1 large or 2 small) flat and arrange the lettuce and dressed chicken down the middle.","Fold in the sides, roll tightly, and cut in half. Serve cold, using ready-to-eat chicken stored according to its packet."],"time":10,"title":"Chicken Caesar Wrap"},{"id":32,"need":["bread","ham","cheese","butter"],"amounts":{"bread":"2 slices","ham":"2 ready-to-eat slices, 50 g","cheese":"35 g, grated","butter":"10 g"},"servings":1,"equipment":"Nonstick frying pan","steps":["Layer ham (2 ready-to-eat slices, 50 g) and cheese (35 g, grated) between bread (2 slices). Spread butter (10 g) thinly on the outsides.","Place in a nonstick frying pan over medium-low heat. Cook for 3–4 minutes per side, pressing lightly, until golden and the cheese has melted.","If the bread browns too quickly, lower the heat and cover briefly to warm the centre. Cut in half and serve hot."],"time":12,"title":"Ham & Cheese Toastie"},{"id":33,"need":["bagel","creamcheese"],"amounts":{"bagel":"1","creamcheese":"35 g"},"servings":1,"equipment":"Toaster and knife","steps":["Split bagels (1) horizontally and toast the cut sides for 2–3 minutes until lightly golden.","Spread cream cheese (35 g) evenly over the warm halves.","Serve immediately, while the outside is crisp and the middle is still soft."],"time":5,"title":"Bagel with Cream Cheese"},{"id":34,"need":["bagel","salmon","creamcheese","cucumber"],"amounts":{"bagel":"1","salmon":"120 g raw boneless salmon fillet","creamcheese":"35 g","cucumber":"¼ medium, 80 g"},"servings":1,"equipment":"Oven, tray, and toaster","steps":["Heat the oven to 200°C (180°C fan). Put salmon (120 g raw boneless salmon fillet) on a baking-paper-lined tray. Bake for about 12–18 minutes, depending on thickness, until the centre reaches 63°C and the flesh flakes easily. Remove any skin and check for bones before serving.","Split and toast bagels (1) for 2–3 minutes. Thinly slice cucumber (¼ medium, 80 g).","Spread cream cheese (35 g) on the bagel halves. Flake the cooked salmon over the cheese, add cucumber, and close the sandwich. Serve warm."],"time":25,"title":"Salmon & Cream Cheese Bagel"},{"id":35,"need":["tortilla","eggs","cheese","bellpepper"],"amounts":{"tortilla":"1 large or 2 small","eggs":"2","cheese":"35 g, grated","bellpepper":"½ small"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Finely dice bell pepper (½ small). Put in a nonstick pan with 2 tablespoons water, cover, and cook over medium-low heat for 3–4 minutes until softened.","Beat eggs (2), add to the pan, and stir gently for 2–3 minutes until the egg is fully set.","Warm tortillas (1 large or 2 small) in a dry pan for 20 seconds per side. Spoon the egg mixture down the middle and add cheese (35 g, grated).","Fold in the sides and roll tightly. Return seam-side down to the pan for 1 minute to seal and melt the cheese."],"time":15,"title":"Breakfast Burrito"},{"id":36,"need":["mango","greekyogurt","honey","almonds"],"amounts":{"mango":"150 g peeled flesh","greekyogurt":"170 g plain","honey":"1 tsp","almonds":"15 g"},"servings":1,"equipment":"Bowl and chopping board","steps":["Peel and stone mango (150 g peeled flesh), then cut the flesh into 1 cm cubes. Roughly chop almonds (15 g).","Spoon Greek yogurt (170 g plain) into a bowl. Add the mango and almonds, then drizzle over honey (1 tsp).","Serve straight away for the best contrast between creamy yogurt and crunchy almonds."],"time":5,"title":"Mango Yogurt Bowl"},{"id":37,"need":["flour","milk","eggs","blueberries","bakingpowder"],"amounts":{"flour":"75 g plain flour","milk":"100 ml","eggs":"1","blueberries":"60 g","bakingpowder":"½ tsp"},"servings":1,"equipment":"Bowl and good nonstick frying pan","steps":["Mix flour (75 g plain flour) with baking powder (½ tsp). Beat eggs (1) with milk (100 ml), then stir into the flour just until no dry patches remain. Fold in washed blueberries (60 g).","Let the batter stand for 3 minutes. Warm a good nonstick pan over medium-low heat.","Use about 2 tablespoons batter per pancake. Cook for 2–3 minutes until small bubbles appear and the edges look set.","Flip gently and cook for 1–2 minutes more, until golden and fully cooked in the centre. Repeat with the remaining batter."],"time":20,"title":"Blueberry Pancakes"},{"id":38,"need":["bread","eggs","milk","cinnamon","maplesyrup"],"amounts":{"bread":"2 slices","eggs":"1","milk":"60 ml","cinnamon":"¼ tsp","maplesyrup":"1 tbsp"},"servings":1,"equipment":"Shallow bowl and good nonstick frying pan","steps":["Whisk eggs (1), milk (60 ml), and cinnamon (¼ tsp) in a shallow bowl for about 20 seconds.","Dip both sides of bread (2 slices) into the mixture for 5–10 seconds per side. Let excess drip back into the bowl.","Cook in a good nonstick pan over medium-low heat for 3–4 minutes per side, until golden and the egg mixture is fully set through the bread.","Drizzle over maple syrup (1 tbsp) and serve hot."],"time":15,"title":"Classic French Toast"},{"id":39,"need":["oats","milk","chia","honey","strawberry"],"amounts":{"oats":"50 g","milk":"150 ml","chia":"1 tbsp, 12 g","honey":"1 tsp","strawberry":"100 g"},"servings":1,"equipment":"Clean jar or lidded bowl","steps":["Stir oats (50 g), milk (150 ml), chia seeds (1 tbsp, 12 g), and honey (1 tsp) together in a clean jar. Scrape around the base so no dry oats remain.","Wait 5 minutes, stir again to break up any chia clumps, then cover and refrigerate for at least 6 hours or overnight.","When ready to eat, stir well and add 1–2 tablespoons water if too thick. Wash and slice strawberries (100 g) and arrange on top."],"time":8,"title":"Overnight Oats","wait":"6 hr chill","waitMinutes":360},{"id":40,"need":["oats","milk","cocoapowder","banana"],"amounts":{"oats":"50 g","milk":"170 ml","cocoapowder":"1 tbsp, 6 g","banana":"1 small, peeled"},"servings":1,"equipment":"Clean jar or lidded bowl","steps":["Mix oats (50 g), milk (170 ml), and cocoa powder (1 tbsp, 6 g) in a clean jar until no dry cocoa remains. Mash half of banana (1 small, peeled) into the mixture.","Cover and refrigerate for at least 6 hours or overnight so the oats become soft.","Stir before eating, adding water 1 tablespoon at a time if needed. Slice the remaining banana and put on top just before serving."],"time":5,"title":"Chocolate Overnight Oats","wait":"6 hr chill","waitMinutes":360},{"id":41,"need":["apple","peanutbutter"],"amounts":{"apple":"1 small","peanutbutter":"2 tsp"},"servings":1,"equipment":"Chopping board and knife","steps":["Wash apple (1 small), cut into quarters, remove the core, and slice into wedges about 1 cm thick.","Spoon peanut butter (2 tsp) into a small dish. Serve beside the apple for dipping, or spread thinly over the slices.","Eat straight away; cut apple will gradually brown if left uncovered."],"time":5,"title":"Apple Peanut Butter Snack"},{"id":42,"need":["almonds","walnuts","raisins","chocolatechips"],"amounts":{"almonds":"15 g","walnuts":"15 g","raisins":"15 g","chocolatechips":"15 g"},"servings":1,"equipment":"Small bowl or lidded container","steps":["Measure almonds (15 g), walnuts (15 g), raisins (15 g), and chocolate chips (15 g). Roughly break large walnut pieces so the mix is easy to eat.","Stir together in a bowl for about 20 seconds.","Serve as one snack portion, or put in a dry lidded container until needed."],"time":3,"title":"Trail Mix"},{"id":43,"need":["cucumber","creamcheese"],"amounts":{"cucumber":"¼ medium, 80 g","creamcheese":"35 g"},"servings":1,"equipment":"Chopping board and knife","steps":["Wash cucumber (¼ medium, 80 g) and cut into 1 cm-thick rounds. Pat the cut surfaces dry with kitchen paper.","Divide cream cheese (35 g) between the rounds, using a teaspoon to spread it.","Arrange on a plate and serve immediately so the cucumber stays crisp."],"time":5,"title":"Cucumber Cream Cheese Bites"},{"id":44,"need":["grapes","watermelon","strawberry","kiwi"],"amounts":{"grapes":"80 g, halved","watermelon":"150 g peeled flesh","strawberry":"100 g","kiwi":"1, peeled"},"servings":1,"equipment":"Chopping board and bowl","steps":["Wash grapes (80 g, halved) and strawberries (100 g). Halve the grapes, remove the strawberry stalks, and quarter the berries.","Cut watermelon (150 g peeled flesh) into 2 cm cubes, removing the rind and any hard seeds. Peel and slice kiwi (1, peeled).","Combine gently in a bowl. Serve immediately, or cover and refrigerate until serving."],"time":10,"title":"Fruit Salad"},{"id":45,"need":["mango","pineapple","banana","milk"],"amounts":{"mango":"75 g","pineapple":"75 g","banana":"½ small","milk":"150 ml"},"servings":1,"equipment":"Blender","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. ","Put milk (150 ml), mango (75 g), pineapple (75 g), banana (½ small) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":8,"title":"Tropical Smoothie"},{"id":46,"need":["spinach","banana","apple","milk"],"amounts":{"spinach":"30 g","banana":"1 small, peeled","apple":"½ small","milk":"200 ml"},"servings":1,"equipment":"Blender","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. Wash the spinach well and remove the apple core; there is no need to peel the apple.","Put milk (200 ml), spinach (30 g), banana (1 small, peeled), apple (½ small) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":8,"title":"Green Smoothie"},{"id":47,"need":["banana","peanutbutter","milk","honey"],"amounts":{"banana":"1 small, peeled","peanutbutter":"1 tbsp, 15 g","milk":"200 ml","honey":"1 tsp"},"servings":1,"equipment":"Blender","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. ","Put milk (200 ml), banana (1 small, peeled), peanut butter (1 tbsp, 15 g), honey (1 tsp) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":5,"title":"Peanut Butter Banana Smoothie"},{"id":48,"need":["raspberries","yogurt","milk","honey"],"amounts":{"raspberries":"100 g","yogurt":"100 g","milk":"120 ml","honey":"1 tsp"},"servings":1,"equipment":"Blender","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. ","Put milk (120 ml), yogurt (100 g), raspberries (100 g), honey (1 tsp) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":5,"title":"Raspberry Yogurt Smoothie"},{"id":49,"need":["greekyogurt","lemon","garlic"],"amounts":{"greekyogurt":"120 g","lemon":"1–2 tsp juice","garlic":"½ small clove"},"servings":1,"equipment":"Small bowl and grater","steps":["Finely grate garlic (½ small clove). Put Greek yogurt (120 g) in a bowl and stir in the garlic.","Add lemon (1–2 tsp juice), starting with the smaller amount, and stir for 20 seconds until smooth. Add 1 teaspoon water if you prefer a thinner dip.","Serve immediately, or cover and refrigerate for 10 minutes for a stronger garlic flavour. Chilling is optional."],"time":5,"title":"Lemon Yogurt Dip"},{"id":50,"need":["avocado","lime","tomato","onion","cilantro"],"amounts":{"avocado":"1 medium","lime":"1 tbsp juice","tomato":"½ small","onion":"¼ small","cilantro":"1 tbsp chopped"},"servings":1,"equipment":"Bowl, fork, and chopping board","steps":["Scoop avocado (1 medium) into a bowl and mash roughly with a fork. Remove the juicy seeds from tomato (½ small), then finely dice the flesh.","Finely chop onion (¼ small) and cilantro (1 tbsp chopped). Stir into the avocado with the diced tomato and lime (1 tbsp juice).","Mix gently until combined, leaving a little texture. Serve straight away to keep the avocado fresh and green."],"time":10,"title":"Guacamole"},{"id":51,"need":["tomato","onion","lime","cilantro"],"amounts":{"tomato":"2 medium, 240 g","onion":"¼ small","lime":"½, about 1 tbsp juice","cilantro":"1 tbsp chopped"},"servings":1,"equipment":"Chopping board and bowl","steps":["Dice tomato (2 medium, 240 g) into 5 mm pieces. Finely chop onion (¼ small) and cilantro (1 tbsp chopped).","Put everything in a bowl and add lime (½, about 1 tbsp juice). Stir gently for about 20 seconds.","Leave for 5 minutes so the juices combine, then serve with a slotted spoon if the tomatoes release a lot of liquid."],"time":12,"title":"Fresh Tomato Salsa"},{"id":52,"need":["potatochips","cheese","salsa","beans"],"amounts":{"potatochips":"60 g","cheese":"40 g","salsa":"3 tbsp","beans":"100 g canned, drained and rinsed"},"servings":1,"equipment":"Oven and small oven-safe tray","steps":["Heat the oven to 200°C (180°C fan). Spread potato chips (60 g) in a single layer on a small oven-safe tray.","Scatter over beans (100 g canned, drained and rinsed) and cheese (40 g), spreading the topping evenly so the chips warm through.","Bake for 5–8 minutes until the beans are hot and the cheese melts; watch closely so the chips do not burn.","Add salsa (3 tbsp) after baking and serve immediately. These use the potato chips listed in your fridge rather than requiring another kind of chip."],"time":12,"title":"Cheesy Nachos"},{"id":53,"need":["chickpeas","lemon","garlic","oliveoil"],"amounts":{"chickpeas":"150 g canned, drained and rinsed","lemon":"1 tbsp juice","garlic":"1 small clove","oliveoil":"2 tsp"},"servings":1,"equipment":"Blender and bowl","steps":["Drain and rinse chickpeas (150 g canned, drained and rinsed). Peel and roughly chop garlic (1 small clove).","Blend the chickpeas with lemon (1 tbsp juice), olive oil (2 tsp), the garlic, and 2 tablespoons cold water for 45–60 seconds.","Scrape down the sides and blend again. Add more water 1 tablespoon at a time until the hummus is smooth enough to scoop.","Spoon into a bowl and serve, or cover and refrigerate until needed."],"time":8,"title":"Hummus"},{"id":54,"need":["tortilla","chickpeas","cucumber","tomato","mayo"],"amounts":{"tortilla":"1 large or 2 small","chickpeas":"150 g canned, drained and rinsed","cucumber":"¼ medium, 80 g","tomato":"½ medium","mayo":"1 tbsp"},"servings":1,"equipment":"Bowl and chopping board","steps":["Roughly mash chickpeas (150 g canned, drained and rinsed) with a fork, leaving some whole pieces. Dice cucumber (¼ medium, 80 g) and tomato (½ medium) into small pieces, discarding excess tomato juice.","Stir the vegetables and mayo (1 tbsp) into the chickpeas until coated.","Spoon the mixture down the middle of tortillas (1 large or 2 small). Fold in the sides, roll tightly, and cut in half. Serve immediately."],"time":10,"title":"Chickpea Salad Wrap"},{"id":55,"need":["bread","tuna","mayo","cheese"],"amounts":{"bread":"2 slices","tuna":"1 small tin, about 100 g drained","mayo":"1 tbsp","cheese":"30 g"},"servings":1,"equipment":"Bowl, toaster, and oven grill","steps":["Drain tuna (1 small tin, about 100 g drained) well and mix with mayo (1 tbsp). Lightly toast bread (2 slices) and place on a grill-safe tray.","Divide the tuna mixture between the slices and sprinkle evenly with cheese (30 g).","Grill for 3–5 minutes until the cheese bubbles and the tuna is hot. Watch closely to prevent the toast edges burning. Serve immediately."],"time":12,"title":"Tuna Melt"},{"id":56,"need":["bread","chicken","pesto","mozzarella"],"amounts":{"bread":"2 slices","chicken":"120 g ready-to-eat cooked chicken, sliced","pesto":"1 tbsp, 20 g","mozzarella":"40 g"},"servings":1,"equipment":"Nonstick frying pan with lid","steps":["Put chicken (120 g ready-to-eat cooked chicken, sliced) in a nonstick pan with 2 tablespoons water. Cover and heat over medium-low heat for 3–4 minutes, stirring, until it reaches 74°C throughout.","Spread pesto (1 tbsp, 20 g) on bread (2 slices). Add the warm chicken and mozzarella (40 g), then close the sandwich.","Wipe the pan dry. Toast the sandwich over low heat for 2–3 minutes per side, covering briefly if needed, until the bread is crisp and the mozzarella melts."],"time":15,"title":"Pesto Chicken Sandwich"},{"id":57,"need":["couscous","cucumber","tomato","feta","lemon"],"amounts":{"couscous":"75 g dry","cucumber":"¼ medium","tomato":"1 small","feta":"50 g","lemon":"½, about 1 tbsp juice"},"servings":1,"equipment":"Heatproof bowl and chopping board","steps":["Put couscous (75 g dry) in a heatproof bowl. Add boiling water in the ratio on its packet (often equal volumes), cover with a plate, and leave for 5–10 minutes or the packet time. Fluff with a fork so the grains separate.","Dice cucumber (¼ medium) and tomato (1 small) into 1 cm pieces. Crumble feta (50 g).","Fold the vegetables and feta through the fluffed couscous. Squeeze over lemon (½, about 1 tbsp juice) and toss gently.","Serve warm, or refrigerate promptly if making it for later."],"time":15,"title":"Mediterranean Couscous"},{"id":58,"need":["quinoa","broccoli","carrot","oliveoil","lemon"],"amounts":{"quinoa":"60 g dry","broccoli":"100 g","carrot":"1 small","oliveoil":"1 tsp, 5 ml","lemon":"½, about 1 tbsp juice"},"servings":1,"equipment":"Saucepan, frying pan with lid, and bowl","steps":["Rinse quinoa (60 g dry) in a fine sieve. Put in a saucepan with the amount of water on its packet, usually about 150 ml for 60 g. Simmer covered for 12–15 minutes until tender, then rest for 5 minutes.","Cut broccoli (100 g) into small florets and carrot (1 small) into thin slices. Put in a frying pan with 3 tablespoons water, cover, and steam for 5–7 minutes until tender.","Uncover and let any remaining water evaporate. Add olive oil (1 tsp, 5 ml) and toss the vegetables for 1 minute.","Spoon the quinoa into a bowl and add the vegetables. Finish with lemon (½, about 1 tbsp juice) and serve."],"time":25,"title":"Quinoa Veggie Bowl"},{"id":59,"need":["chickpeas","spinach","onion","curry","tomatosauce"],"amounts":{"chickpeas":"200 g canned, drained and rinsed","spinach":"80 g","onion":"½ medium, 60 g","curry":"1 tsp mild curry powder","tomatosauce":"150 g"},"servings":1,"equipment":"One saucepan","steps":["Finely chop onion (½ medium, 60 g). Put in a saucepan with 3 tablespoons water, cover, and cook over medium-low heat for 5 minutes until soft.","Stir in curry powder (1 tsp mild curry powder) for 30 seconds, then add tomato sauce (150 g), chickpeas (200 g canned, drained and rinsed), and 80 ml water. Simmer for 8–10 minutes, stirring, until piping hot.","Stir in spinach (80 g) and cook for 2 minutes until wilted. Simmer for another minute if you prefer a thicker sauce, then serve."],"time":22,"title":"Chickpea & Spinach Curry"},{"id":60,"need":["chicken","rice","onion","curry","cream"],"amounts":{"chicken":"150 g raw boneless chicken, cut into 2 cm pieces","rice":"75 g dry","onion":"½ medium, 60 g","curry":"1 tsp mild curry powder","cream":"60 ml"},"servings":1,"equipment":"Saucepan and nonstick frying pan with lid","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Finely dice onion (½ medium, 60 g). Cook in a nonstick pan with 3 tablespoons water over medium heat for 4–5 minutes until soft. Add chicken (150 g raw boneless chicken, cut into 2 cm pieces) and cook for 5 minutes, turning frequently and adding water if needed.","Add curry powder (1 tsp mild curry powder), cream (60 ml), and 60 ml water. Cover and simmer gently for 6–8 minutes, until the thickest chicken piece reaches 74°C. Avoid a hard boil so the cream stays smooth.","Spoon over the rice and serve piping hot."],"time":30,"title":"Chicken Curry Rice"},{"id":61,"need":["beef","bellpepper","onion","soyauce","rice"],"amounts":{"beef":"150 g raw lean beef strips","bellpepper":"½ large","onion":"½ small","soyauce":"2 tsp","rice":"75 g dry"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Thinly slice bell pepper (½ large) and onion (½ small). Put in a good nonstick pan over medium-high heat with 3 tablespoons water. Cook for 4–5 minutes until tender-crisp. Transfer to a plate.","Add beef (150 g raw lean beef strips) to the hot pan in a single layer. Cook for about 3–5 minutes, turning, until browned and the thickest strip reaches 63°C; rest off the heat for 3 minutes. Cook in batches if needed.","Return the vegetables, add soy sauce (2 tsp) and 2 tablespoons water, and toss briefly until hot. Serve over the rice."],"time":25,"title":"Beef & Pepper Stir Fry"},{"id":62,"need":["shrimp","pasta","garlic","butter","lemon"],"amounts":{"shrimp":"150 g raw peeled shrimp, thawed if frozen","pasta":"90 g dry","garlic":"1 small clove","butter":"10 g","lemon":"½, about 1 tbsp juice"},"servings":1,"equipment":"Saucepan and frying pan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Peel and finely chop garlic (1 small clove). Pat shrimp (150 g raw peeled shrimp, thawed if frozen) dry. Melt butter (10 g) over medium heat and cook the garlic for 30 seconds without browning.","Add the shrimp in a single layer and cook for about 2–3 minutes per side, until pearly and opaque throughout. Larger shrimp may take longer.","Add the drained pasta and lemon (½, about 1 tbsp juice). Toss for 1 minute, adding 1–2 tablespoons reserved pasta water if needed to coat the pasta. Serve hot."],"time":20,"title":"Garlic Shrimp Pasta"},{"id":63,"need":["salmon","rice","cucumber","avocado"],"amounts":{"salmon":"150 g raw boneless salmon fillet","rice":"75 g dry","cucumber":"¼ medium","avocado":"½ small"},"servings":1,"equipment":"Saucepan, oven, and tray","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Heat the oven to 200°C (180°C fan). Put salmon (150 g raw boneless salmon fillet) on a baking-paper-lined tray. Bake for about 12–18 minutes, depending on thickness, until the centre reaches 63°C and the flesh flakes easily. Remove any skin and check for bones before serving.","Dice cucumber (¼ medium) and slice avocado (½ small). Check the cooked salmon for bones and flake into large pieces.","Spoon the rice into a bowl and arrange the salmon, cucumber, and avocado on top. Serve immediately."],"time":25,"title":"Salmon Rice Bowl"},{"id":64,"need":["salmon","broccoli","lemon","oliveoil"],"amounts":{"salmon":"150 g raw boneless salmon fillet","broccoli":"200 g","lemon":"½, about 1 tbsp juice","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Oven and baking tray","steps":["Heat the oven to 200°C (180°C fan). Cut broccoli (200 g) into small florets and toss on a lined tray with half of olive oil (1 tsp, 5 ml).","Place salmon (150 g raw boneless salmon fillet) beside the broccoli. Rub with the remaining oil and squeeze over half of lemon (½, about 1 tbsp juice).","Bake for about 12–18 minutes, until the salmon reaches 63°C in the thickest part and flakes easily. If the broccoli needs longer, remove the fish and roast the broccoli for another 3–5 minutes.","Serve with the remaining lemon juice, checking the salmon for bones."],"time":25,"title":"Sheet-Pan Salmon & Broccoli"},{"id":65,"need":["pasta","broccoli","cheese","milk"],"amounts":{"pasta":"90 g dry","broccoli":"150 g","cheese":"40 g","milk":"80 ml"},"servings":1,"equipment":"One saucepan","steps":["Cut broccoli (150 g) into small florets. Bring about 1 litre water to a boil and add pasta (90 g dry). Cook for its packet time, adding the broccoli for the last 4–5 minutes.","Reserve 100 ml cooking water and drain well. Return to the pan over low heat.","Add milk (80 ml) and cheese (40 g), then stir for 1–2 minutes until melted and creamy. Add cooking water a tablespoon at a time if the sauce is too thick. Serve immediately."],"time":18,"title":"Cheesy Broccoli Pasta"},{"id":66,"need":["pasta","spinach","cream","garlic"],"amounts":{"pasta":"90 g dry","spinach":"100 g","cream":"60 ml","garlic":"1 small clove"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Finely chop garlic (1 small clove). Put in a nonstick pan with 2 tablespoons water and simmer gently for 1 minute.","Add spinach (100 g) and stir for 1–2 minutes until wilted. Add cream (60 ml) and warm over low heat for 2 minutes without boiling.","Fold in the drained pasta and toss for 1 minute. Add reserved cooking water as needed for a smooth sauce, then serve."],"time":18,"title":"Creamy Spinach Pasta"},{"id":67,"need":["noodles","tomatosauce","garlic","hotauce"],"amounts":{"noodles":"75 g dry","tomatosauce":"150 g","garlic":"1 small clove","hotauce":"1 tsp, or less to taste"},"servings":1,"equipment":"Saucepan and small saucepan","steps":["Cook noodles (75 g dry) in boiling water for their packet time, usually 3–6 minutes. Reserve 60 ml cooking water, then drain.","Finely chop garlic (1 small clove). Simmer in a small pan with 2 tablespoons water for 1 minute, then add tomato sauce (150 g) and hot sauce (1 tsp, or less to taste).","Simmer the sauce for 4–5 minutes, stirring occasionally. Add the noodles and toss for 1 minute, loosening with the reserved water as needed."],"time":15,"title":"Spicy Tomato Noodles"},{"id":68,"need":["noodles","carrot","broccoli","soyauce","sesameoil"],"amounts":{"noodles":"75 g dry","carrot":"1 small","broccoli":"100 g","soyauce":"2 tsp","sesameoil":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Cook noodles (75 g dry) according to the packet. Reserve 60 ml cooking water, then drain. Cut carrot (1 small) into thin matchsticks and broccoli (100 g) into small florets.","Heat sesame oil (1 tsp) in a nonstick pan over medium heat. Add the carrot, broccoli, and 2 tablespoons water. Cover and cook for 4–5 minutes until tender-crisp.","Uncover, add the noodles and soy sauce (2 tsp), and toss for 1–2 minutes until hot throughout. Add reserved water if the noodles stick together."],"time":20,"title":"Veggie Noodle Stir Fry"},{"id":69,"need":["tofu","rice","soyauce","broccoli"],"amounts":{"tofu":"180 g firm","rice":"75 g dry","soyauce":"2 tsp","broccoli":"150 g"},"servings":1,"equipment":"Saucepan and nonstick frying pan with lid","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Cut tofu (180 g firm) into 2 cm cubes and broccoli (150 g) into small florets. Put the broccoli in a nonstick pan with 3 tablespoons water, cover, and steam for 4–5 minutes until tender.","Add the tofu, soy sauce (2 tsp), and 2 tablespoons water. Cover and simmer for 4–5 minutes until the tofu is hot throughout. Use more water if the pan dries out.","Serve the tofu and broccoli over the rice, spooning the pan juices over the top."],"time":25,"title":"Tofu Rice Bowl"},{"id":70,"need":["tortilla","blackbeans","salsa","lettuce","cheese"],"amounts":{"tortilla":"1 large or 2 small","blackbeans":"150 g canned, drained and rinsed","salsa":"3 tbsp","lettuce":"2 large leaves, washed","cheese":"30 g"},"servings":1,"equipment":"Small saucepan and nonstick frying pan","steps":["Put black beans (150 g canned, drained and rinsed) and salsa (3 tbsp) in a small saucepan. Heat gently for 4–5 minutes, stirring until piping hot. Roughly mash a few beans to thicken.","Shred lettuce (2 large leaves, washed) and set out cheese (30 g). Warm tortillas (1 large or 2 small) in a dry pan for about 20 seconds per side.","Divide the bean filling between the tortillas. Add lettuce and cheese, fold, and serve while warm."],"time":12,"title":"Black Bean Tacos"},{"id":71,"need":["chicken","tortilla","bellpepper","onion","paprika"],"amounts":{"chicken":"150 g raw chicken, thinly sliced","tortilla":"1 large or 2 small","bellpepper":"1 small","onion":"½ small","paprika":"½ tsp"},"servings":1,"equipment":"Nonstick frying pan with lid","steps":["Cut bell pepper (1 small) and onion (½ small) into thin strips. Put in a nonstick pan with 3 tablespoons water and cook covered over medium heat for 4–5 minutes.","Add chicken (150 g raw chicken, thinly sliced) and paprika (½ tsp). Stir, cover, and cook for about 7–10 minutes, adding small splashes of water to prevent sticking, until the thickest chicken piece reaches 74°C.","Remove the lid and stir for 1–2 minutes to reduce the juices. Warm tortillas (1 large or 2 small) briefly in a separate dry pan or as directed on the packet.","Fill with the hot chicken and peppers, fold, and serve immediately."],"time":22,"title":"Chicken Fajitas"},{"id":72,"need":["beef","tortilla","tomato","lettuce","salsa"],"amounts":{"beef":"150 g raw lean beef strips","tortilla":"1 large or 2 small","tomato":"1 medium, 120 g","lettuce":"2 large leaves, washed","salsa":"3 tbsp"},"servings":1,"equipment":"Nonstick frying pan and chopping board","steps":["Dice tomato (1 medium, 120 g) and shred lettuce (2 large leaves, washed). Warm tortillas (1 large or 2 small) in a dry nonstick pan for 20 seconds per side, then keep on a plate.","Cook beef (150 g raw lean beef strips) in the same good nonstick pan over medium-high heat for about 3–5 minutes, turning, until browned and the thickest strip reaches 63°C. Add 1 tablespoon water if it sticks; rest the beef off the heat for 3 minutes.","Divide the beef between the tortillas, add tomato, lettuce, and salsa (3 tbsp), then fold and serve."],"time":18,"title":"Beef Tacos"},{"id":73,"need":["pita","spinach","feta","tomato"],"amounts":{"pita":"1 large","spinach":"80 g","feta":"50 g","tomato":"½ medium"},"servings":1,"equipment":"Nonstick frying pan with lid","steps":["Roughly chop spinach (80 g). Put in the pan with 1 tablespoon water and cook for 1–2 minutes until wilted; let excess moisture evaporate.","Dice tomato (½ medium) and crumble feta (50 g). Warm pita bread (1 large) briefly until flexible, then carefully open the pocket.","Fill the pita with spinach, tomato, and feta. Place in a dry pan over low-medium heat for 2–3 minutes per side until crisp outside and warm through."],"time":12,"title":"Cheese & Spinach Stuffed Pita"},{"id":74,"need":["sweetpotato","blackbeans","avocado","lime"],"amounts":{"sweetpotato":"1 medium-large, 250–300 g","blackbeans":"150 g canned, drained and rinsed","avocado":"½ medium","lime":"½, about 1 tbsp juice"},"servings":1,"equipment":"Microwave, plate, and small saucepan","steps":["Scrub sweet potato (1 medium-large, 250–300 g), prick several times, and microwave on a microwave-safe plate for 5 minutes. Turn and cook for another 3–5 minutes, then in 1-minute bursts until soft throughout.","Meanwhile, heat black beans (150 g canned, drained and rinsed) in a saucepan with 2 tablespoons water for 3–4 minutes until piping hot. Slice avocado (½ medium).","Split the sweet potato, fluff the flesh with a fork, and top with the beans and avocado. Squeeze over lime (½, about 1 tbsp juice) and serve."],"time":20,"title":"Sweet Potato & Black Bean Bowl"},{"id":75,"need":["broccoli","carrot","zucchini","oliveoil","paprika"],"amounts":{"broccoli":"100 g","carrot":"1 small","zucchini":"½ medium","oliveoil":"1 tsp, 5 ml","paprika":"½ tsp"},"servings":1,"equipment":"Oven and baking tray","steps":["Heat the oven to 200°C (180°C fan). Cut broccoli (100 g) into small florets, carrot (1 small) into thin half-moons, and zucchini (½ medium) into 1 cm pieces.","Toss the vegetables on a lined tray with olive oil (1 tsp, 5 ml) and paprika (½ tsp). Spread into one uncrowded layer.","Roast for 20–25 minutes, turning after 12 minutes, until the carrot is tender and the edges are golden. Serve warm."],"time":32,"title":"Roasted Veggie Tray"},{"id":76,"need":["zucchini","tomato","pasta","garlic","oliveoil"],"amounts":{"zucchini":"1 small, 150 g","tomato":"2 medium, 240 g","pasta":"90 g dry","garlic":"1 small clove","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Saucepan and frying pan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Cut zucchini (1 small, 150 g) into thin half-moons, dice tomato (2 medium, 240 g), and finely chop garlic (1 small clove).","Heat olive oil (1 tsp, 5 ml) over medium heat. Cook the zucchini for 4–5 minutes until softened. Add the garlic for 30 seconds, then the tomatoes.","Simmer for 6–8 minutes until the tomatoes become saucy. Add the pasta and toss for 1 minute, loosening with reserved cooking water as needed."],"time":25,"title":"Zucchini Tomato Pasta"},{"id":77,"need":["eggplant","tomato","mozzarella","oliveoil"],"amounts":{"eggplant":"1 small, 200 g","tomato":"2 medium, 240 g","mozzarella":"70 g","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Oven, tray, and small baking dish","steps":["Heat the oven to 200°C (180°C fan). Cut eggplant (1 small, 200 g) into 1 cm slices and brush both sides with olive oil (1 tsp, 5 ml).","Arrange on a lined tray and roast for 15–20 minutes, turning halfway, until softened. Slice tomato (2 medium, 240 g) and tear mozzarella (70 g) into pieces.","Layer the softened eggplant and tomato in a small baking dish. Top with the mozzarella.","Bake for 15–20 minutes more, until bubbling, the eggplant is completely tender, and the cheese is golden. Rest for 3 minutes before serving."],"time":45,"title":"Eggplant Tomato Bake"},{"id":78,"need":["sweetpotato","blackbeans","cheese","greekyogurt"],"amounts":{"sweetpotato":"1 medium-large, 250–300 g","blackbeans":"150 g canned, drained and rinsed","cheese":"35 g, grated","greekyogurt":"170 g plain"},"servings":1,"equipment":"Microwave, plate, and small saucepan","steps":["Scrub sweet potato (1 medium-large, 250–300 g), prick with a fork, and microwave for 5 minutes on a microwave-safe plate. Turn and cook for 3–5 minutes more, then in 1-minute bursts until soft throughout.","Heat black beans (150 g canned, drained and rinsed) with 2 tablespoons water in a small pan for 3–4 minutes until piping hot.","Split the potato and fluff the flesh. Add the beans and cheese (35 g, grated); microwave for 20–30 seconds if needed to melt the cheese.","Stand for 1 minute, then add Greek yogurt (170 g plain) and serve."],"time":20,"title":"Loaded Sweet Potato"},{"id":79,"need":["broccoli","cheese","milk","onion"],"amounts":{"broccoli":"200 g","cheese":"40 g","milk":"150 ml","onion":"½ medium, 60 g"},"servings":1,"equipment":"Saucepan and stick blender","steps":["Finely chop onion (½ medium, 60 g) and cut broccoli (200 g) into small florets. Put the onion in a saucepan with 3 tablespoons water, cover, and cook over medium-low heat for 4–5 minutes.","Add the broccoli and 300 ml water. Simmer for 8–10 minutes until the broccoli is very tender.","Remove from the heat and blend carefully, following your blender’s instructions for hot liquids. Stir in milk (150 ml) and cheese (40 g).","Warm gently for 2–3 minutes, stirring until the cheese melts; do not boil. Add water if you prefer a thinner soup."],"time":25,"title":"Broccoli Cheddar Soup"},{"id":80,"need":["lentils","tomatosauce","carrot","onion"],"amounts":{"lentils":"180 g canned cooked lentils, drained and rinsed","tomatosauce":"200 g","carrot":"1 medium, 80 g","onion":"½ medium, 60 g"},"servings":1,"equipment":"One saucepan","steps":["Finely dice onion (½ medium, 60 g) and carrot (1 medium, 80 g). Put in a saucepan with 4 tablespoons water, cover, and cook over medium-low heat for 5–6 minutes until beginning to soften.","Add lentils (180 g canned cooked lentils, drained and rinsed), tomato sauce (200 g), and 250 ml water. Simmer uncovered for 12–15 minutes, stirring occasionally, until the carrot is tender.","Mash a few lentils against the side to thicken the soup, or leave chunky. Add water as needed and serve piping hot."],"time":25,"title":"Lentil Tomato Soup"},{"id":81,"need":["blackbeans","beans","tomatosauce","onion","cumin"],"amounts":{"blackbeans":"120 g canned, drained and rinsed","beans":"120 g canned, drained and rinsed","tomatosauce":"200 g","onion":"½ medium, 60 g","cumin":"½ tsp"},"servings":1,"equipment":"One saucepan","steps":["Finely chop onion (½ medium, 60 g). Cook in a saucepan with 3 tablespoons water over medium-low heat for 5 minutes until softened.","Stir in cumin (½ tsp) for 30 seconds. Add black beans (120 g canned, drained and rinsed), beans (120 g canned, drained and rinsed), tomato sauce (200 g), and 100 ml water.","Simmer gently for 10–12 minutes, stirring occasionally, until the beans are piping hot and the sauce is thick. Mash a few beans to thicken further, or add water if needed."],"time":22,"title":"Quick Bean Chili"},{"id":82,"need":["cauliflower","chickpeas","curry","tomatosauce"],"amounts":{"cauliflower":"200 g, small florets","chickpeas":"150 g canned, drained and rinsed","curry":"1 tsp mild curry powder","tomatosauce":"150 g"},"servings":1,"equipment":"One saucepan with lid","steps":["Cut cauliflower (200 g, small florets) into small 2–3 cm florets. Put in a saucepan with tomato sauce (150 g), curry powder (1 tsp mild curry powder), and 180 ml water.","Bring to a gentle simmer, cover, and cook for 10–12 minutes, stirring occasionally, until the cauliflower is almost tender.","Add chickpeas (150 g canned, drained and rinsed) and simmer uncovered for another 5 minutes until piping hot and the cauliflower is easily pierced with a fork. Add water if the sauce is too thick."],"time":22,"title":"Cauliflower Curry"},{"id":83,"need":["bagel","bacon","eggs","cheese"],"amounts":{"bagel":"1","bacon":"2 rashers, about 50 g","eggs":"1","cheese":"25 g"},"servings":1,"equipment":"Nonstick frying pan and toaster","steps":["Cook bacon (2 rashers, about 50 g) in a dry nonstick pan over medium heat for 4–6 minutes, turning until browned and cooked through according to its packet. Transfer to a plate.","Lower the heat, leaving a thin film of bacon fat in the pan. Crack in eggs (1), cover, and cook for 3–4 minutes until the white and yolk are set.","Split and toast bagels (1). Layer with the bacon, egg, and cheese (25 g); close for 1 minute so the cheese softens in the warmth, then serve."],"time":15,"title":"Bacon & Egg Breakfast Bagel"},{"id":84,"need":["ham","spinach","eggs","butter"],"amounts":{"ham":"50 g ready-to-eat ham, chopped","spinach":"60 g","eggs":"2","butter":"10 g"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Chop ham (50 g ready-to-eat ham, chopped) into small pieces and roughly chop spinach (60 g). Beat eggs (2) in a bowl until combined.","Melt butter (10 g) in a nonstick pan over medium-low heat. Add the ham and spinach and stir for 1–2 minutes until the spinach wilts.","Pour in the eggs. Stir gently with a spatula for 2–3 minutes, scraping the base, until the eggs are fully set but still soft. Serve immediately."],"time":10,"title":"Ham & Spinach Scramble"},{"id":85,"need":["banana","flour","eggs","sugar","chocolatechips","bakingpowder"],"amounts":{"banana":"1 large very ripe","flour":"80 g","eggs":"1","sugar":"1 tbsp","chocolatechips":"20 g","bakingpowder":"½ tsp"},"servings":2,"equipment":"Oven, mixing bowl, and 4 paper-lined muffin cups","steps":["Heat the oven to 180°C (160°C fan). Line 4 muffin cups with paper cases. Mash banana (1 large very ripe) until mostly smooth.","Beat in eggs (1) and sugar (1 tbsp). Mix flour (80 g) and baking powder (½ tsp) separately, then fold into the banana mixture just until no dry flour remains.","Fold in chocolate chips (20 g). Divide between the 4 cases, filling each about three-quarters full.","Bake for 18–22 minutes until risen and a skewer inserted in the centre comes out without wet batter. Cool in the tin for 5 minutes, then transfer to a rack. Makes 4 small muffins, 2 per serving."],"time":35,"title":"Banana Chocolate Muffins"},{"id":86,"need":["flour","milk","eggs","bakingpowder","chocolatechips"],"amounts":{"flour":"75 g plain flour","milk":"100 ml","eggs":"1","bakingpowder":"½ tsp","chocolatechips":"15 g"},"servings":1,"equipment":"Bowl and good nonstick frying pan","steps":["Mix flour (75 g plain flour), baking powder (½ tsp), and chocolate chips (15 g). Beat eggs (1) with milk (100 ml), then stir into the dry ingredients just until combined.","Let the batter rest for 3 minutes. Warm a good nonstick pan over medium-low heat.","Use 2 tablespoons batter per pancake. Cook for 2–3 minutes until bubbles appear and the edges set, then flip.","Cook for another 1–2 minutes until golden and fully cooked in the middle. Repeat with the remaining batter and serve warm."],"time":20,"title":"Chocolate Chip Pancakes"},{"id":87,"need":["peanutbutter","sugar","eggs"],"amounts":{"peanutbutter":"80 g smooth","sugar":"50 g","eggs":"1 small"},"servings":2,"equipment":"Oven, bowl, and lined baking tray","steps":["Heat the oven to 180°C (160°C fan). Line a baking tray with baking paper.","Beat peanut butter (80 g smooth), sugar (50 g), and eggs (1 small) into a thick, even mixture. Rest for 5 minutes to firm slightly.","Divide into 6 small mounds on the tray, leaving 5 cm between them. Flatten gently with a fork.","Bake for 10–12 minutes until the edges are set and lightly golden. Leave on the tray for 10 minutes to firm before moving. Makes 6 cookies, 3 per serving."],"time":30,"title":"Peanut Butter Cookies"},{"id":88,"need":["apple","cinnamon","honey","butter"],"amounts":{"apple":"1 large","cinnamon":"¼ tsp","honey":"1 tsp","butter":"5 g"},"servings":1,"equipment":"Oven and small oven-safe dish","steps":["Heat the oven to 180°C (160°C fan). Halve apple (1 large) and remove the core, leaving the skin on.","Put cut-side up in a small baking dish. Divide butter (5 g) between the hollows, drizzle with honey (1 tsp), and sprinkle with cinnamon (¼ tsp).","Add 2 tablespoons water to the bottom of the dish. Bake for 25–35 minutes until the apple is tender when pierced with a knife.","Rest for 3 minutes before eating; spoon the warm juices from the dish over the apple."],"time":40,"title":"Baked Apples with Cinnamon"},{"id":89,"need":["chia","milk","frozenberries","maplesyrup"],"amounts":{"chia":"2 tbsp, 24 g","milk":"150 ml","frozenberries":"100 g","maplesyrup":"1 tbsp"},"servings":1,"equipment":"Clean jar or lidded bowl and small saucepan if needed","steps":["Mix chia seeds (2 tbsp, 24 g), milk (150 ml), and maple syrup (1 tbsp) in a clean jar. Leave for 5 minutes, then stir thoroughly again to break up clumps.","Cover and refrigerate for at least 4 hours or overnight, until thick enough to hold a spoon trail.","Prepare frozen berries (100 g) according to the packet, including any required heating. Cool completely and refrigerate until serving.","Stir the pudding, loosen with a spoonful of water if desired, and top with the prepared berries."],"time":8,"title":"Berry Chia Pudding","wait":"4 hr chill","waitMinutes":240},{"id":90,"need":["mango","coconut","greekyogurt"],"amounts":{"mango":"150 g","coconut":"1 tbsp, 8 g desiccated coconut","greekyogurt":"170 g plain"},"servings":1,"equipment":"Bowl and chopping board","steps":["Peel and stone mango (150 g). Cut the flesh into 1 cm cubes.","Spoon Greek yogurt (170 g plain) into a bowl. Add the mango and sprinkle with coconut (1 tbsp, 8 g desiccated coconut).","Serve immediately, or cover and refrigerate until serving."],"time":5,"title":"Mango Coconut Bowl"},{"id":91,"need":["pineapple","yogurt","honey"],"amounts":{"pineapple":"150 g","yogurt":"150 g","honey":"1 tsp"},"servings":2,"equipment":"Blender and 2 large ice-lolly moulds or freezer-safe cups","steps":["Peel and core pineapple (150 g), then cut into 2 cm pieces. Put in a blender with yogurt (150 g) and honey (1 tsp).","Blend for 30–60 seconds until smooth. Divide between 2 large ice-lolly moulds, leaving 1 cm space at the top for expansion.","Insert the sticks, cover, and freeze for at least 6 hours until solid. If using cups, freeze and serve as a scoopable frozen yogurt instead.","To unmould, hold the outside under cool running water for a few seconds and pull gently. Makes 2 large pops, 1 per serving."],"time":8,"title":"Pineapple Yogurt Pops","wait":"6 hr freeze","waitMinutes":360},{"id":92,"need":["icecream","strawberry","blueberries","chocolatechips"],"amounts":{"icecream":"2 small scoops, about 100 g","strawberry":"100 g","blueberries":"60 g","chocolatechips":"15 g"},"servings":1,"equipment":"Dessert bowl and chopping board","steps":["Wash, hull, and slice strawberries (100 g). Wash and drain blueberries (60 g).","Scoop ice cream (2 small scoops, about 100 g) into a chilled bowl. Add the fruit and scatter over chocolate chips (15 g).","Serve immediately before the ice cream melts."],"time":5,"title":"Ice Cream Berry Sundae"},{"id":93,"need":["frozenmango","yogurt","milk"],"amounts":{"frozenmango":"150 g","yogurt":"100 g","milk":"100 ml"},"servings":1,"equipment":"Blender","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. Prepare the frozen mango as its packet directs; if heating is required, cool it completely before blending.","Put milk (100 ml), yogurt (100 g), frozen mango (150 g) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":5,"title":"Frozen Mango Smoothie"},{"id":94,"need":["frozendumplings","soyauce","springonion"],"amounts":{"frozendumplings":"6–8 frozen dumplings suitable for steaming","soyauce":"2 tsp","springonion":"1, trimmed"},"servings":1,"equipment":"Saucepan or steamer with lid","steps":["Cook frozen dumplings (6–8 frozen dumplings suitable for steaming) from frozen using the steaming instructions on their packet. Keep the lid on and replenish water as needed so the pan does not boil dry.","Follow the full packet cooking time, usually 8–15 minutes depending on size, and check the filling is fully cooked and piping hot; meat-filled dumplings should reach 74°C.","Thinly slice green onions (1, trimmed). Put the cooked dumplings in a bowl, drizzle with soy sauce (2 tsp), and scatter the green onion over the top."],"time":20,"title":"Frozen Dumpling Bowl"},{"id":95,"need":["frozenpizza","lettuce","tomato","cucumber"],"amounts":{"frozenpizza":"1 small frozen pizza, about 250 g","lettuce":"2 large leaves, washed","tomato":"1 medium, 120 g","cucumber":"¼ medium, 80 g"},"servings":1,"equipment":"Oven, tray, and salad bowl","steps":["Heat the oven to the temperature stated on frozen pizza (1 small frozen pizza, about 250 g). Cook from frozen for the full packet time, usually 12–20 minutes, until the base is crisp and the centre is piping hot.","While it cooks, wash and dry lettuce (2 large leaves, washed). Cut tomato (1 medium, 120 g) and cucumber (¼ medium, 80 g) into bite-size pieces.","Toss the vegetables together without dressing. Cut the hot pizza into slices and serve with the side salad."],"time":25,"title":"Pizza & Side Salad"},{"id":96,"need":["frozenfries","cheese","bacon","sourcream"],"amounts":{"frozenfries":"200 g","cheese":"35 g","bacon":"2 rashers, about 50 g","sourcream":"2 tbsp"},"servings":1,"equipment":"Oven, baking tray, and nonstick frying pan","steps":["Heat the oven to the temperature on frozen fries (200 g). Spread the fries on a tray in one layer and bake for the packet time, usually 20–25 minutes, turning halfway.","Meanwhile, cook bacon (2 rashers, about 50 g) in a dry nonstick pan over medium heat for 4–6 minutes, turning until cooked through according to its packet. Drain briefly on kitchen paper and chop.","When the fries are crisp, scatter with the bacon and cheese (35 g). Return to the oven for 2–3 minutes until the cheese melts.","Add sour cream (2 tbsp) after baking and serve immediately."],"time":30,"title":"Loaded Fries"},{"id":97,"need":["tortilla","turkey","avocado","lettuce","mayo"],"amounts":{"tortilla":"1 large or 2 small","turkey":"80 g ready-to-eat cooked turkey slices","avocado":"½ medium","lettuce":"2 large leaves, washed","mayo":"1 tbsp"},"servings":1,"equipment":"Chopping board and knife","steps":["Wash and dry lettuce (2 large leaves, washed). Slice avocado (½ medium) and separate turkey (80 g ready-to-eat cooked turkey slices) into bite-size pieces if needed.","Spread mayo (1 tbsp) over tortillas (1 large or 2 small), leaving a 2 cm border. Lay on the lettuce, turkey, and avocado.","Fold in the sides and roll tightly from the nearest edge. Cut in half and serve cold, using ready-to-eat turkey stored according to its packet."],"time":8,"title":"Turkey & Avocado Wrap"},{"id":98,"need":["bread","turkey","cheese","mustard"],"amounts":{"bread":"2 slices","turkey":"80 g ready-to-eat cooked turkey slices","cheese":"35 g, grated","mustard":"1 tsp"},"servings":1,"equipment":"Chopping board and knife","steps":["Lay out bread (2 slices). Spread mustard (1 tsp) thinly over one slice.","Layer with turkey (80 g ready-to-eat cooked turkey slices) and cheese (35 g, grated). Close with the other slice and press gently.","Cut in half and serve immediately, or wrap and refrigerate until needed."],"time":5,"title":"Turkey Cheese Sandwich"},{"id":99,"need":["tuna","chickpeas","tomato","cucumber","oliveoil"],"amounts":{"tuna":"1 small tin, about 100 g drained","chickpeas":"150 g canned, drained and rinsed","tomato":"1 medium, 120 g","cucumber":"¼ medium, 80 g","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Bowl and chopping board","steps":["Drain tuna (1 small tin, about 100 g drained). Drain and rinse chickpeas (150 g canned, drained and rinsed). Dice tomato (1 medium, 120 g) and cucumber (¼ medium, 80 g) into 1 cm pieces.","Put the tuna, chickpeas, and vegetables in a bowl. Add olive oil (1 tsp, 5 ml) and fold gently so the tuna stays in flakes.","Serve straight away, or cover and refrigerate until serving."],"time":10,"title":"Mediterranean Tuna Bowl"},{"id":100,"need":["corn","blackbeans","tomato","lime","cilantro"],"amounts":{"corn":"100 g canned, drained","blackbeans":"150 g canned, drained and rinsed","tomato":"1 medium, 120 g","lime":"½, about 1 tbsp juice","cilantro":"1 tbsp chopped"},"servings":1,"equipment":"Bowl and chopping board","steps":["Drain corn (100 g canned, drained). Drain and rinse black beans (150 g canned, drained and rinsed). Dice tomato (1 medium, 120 g) and roughly chop cilantro (1 tbsp chopped).","Combine everything in a bowl. Add lime (½, about 1 tbsp juice) and toss gently for about 20 seconds.","Leave for 5 minutes for the juices to combine, then serve. Refrigerate if preparing ahead."],"time":12,"title":"Corn & Black Bean Salad"},{"id":101,"need":["pita","tomatosauce","mozzarella","basil"],"amounts":{"pita":"1 large","tomatosauce":"2 tbsp","mozzarella":"60 g","basil":"5–6 leaves"},"servings":1,"equipment":"Oven and baking tray","steps":["Heat the oven to 200°C (180°C fan). Put pita bread (1 large) on a baking tray and spread with tomato sauce (2 tbsp), leaving a 1 cm border.","Tear mozzarella (60 g) over the top. Bake for 8–10 minutes until the pita is crisp underneath and the cheese is bubbling.","Tear basil (5–6 leaves) over the cooked pizza. Rest for 1 minute, then cut into wedges."],"time":15,"title":"Pita Pizza"},{"id":102,"need":["greekyogurt","cereal","honey","blueberries"],"amounts":{"greekyogurt":"170 g plain","cereal":"40 g","honey":"1 tsp","blueberries":"80 g"},"servings":1,"equipment":"One bowl","steps":["Spoon Greek yogurt (170 g plain) into a bowl. Wash and drain blueberries (80 g).","Top the yogurt with cereal (40 g) and the blueberries, then drizzle with honey (1 tsp).","Eat immediately so the cereal stays crunchy. If packing ahead, keep the cereal separate until eating."],"time":5,"title":"Breakfast Yogurt Crunch"},{"id":103,"need":["couscous","cucumber","tomato","lemon","oliveoil"],"amounts":{"couscous":"75 g dry","cucumber":"¼ medium, 80 g","tomato":"1 medium, 120 g","lemon":"½, about 1 tbsp juice","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Heatproof bowl and chopping board","steps":["Put couscous (75 g dry) in a heatproof bowl. Add boiling water in the ratio on its packet (often equal volumes), cover with a plate, and leave for 5–10 minutes or the packet time. Fluff with a fork so the grains separate.","Dice cucumber (¼ medium, 80 g) and tomato (1 medium, 120 g) into small pieces. Let the couscous cool for 3–5 minutes so it is warm rather than steaming.","Fold in the vegetables, olive oil (1 tsp, 5 ml), and lemon (½, about 1 tbsp juice). Toss gently and serve, or refrigerate promptly for later."],"time":15,"title":"Cucumber Tomato Couscous"},{"id":104,"need":["bread","tomato","basil","garlic","oliveoil"],"amounts":{"bread":"2 slices","tomato":"1 large","basil":"6 leaves","garlic":"1 small clove","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Toaster and chopping board","steps":["Dice tomato (1 large), discarding excess watery seeds if very juicy. Tear basil (6 leaves) into small pieces and mix with the tomato and olive oil (1 tsp, 5 ml).","Toast bread (2 slices) for 2–3 minutes until crisp. Peel garlic (1 small clove), cut it in half, and rub the cut surface lightly over the warm toast.","Spoon the tomato mixture over the toast just before eating so it does not become soggy."],"time":10,"title":"Basil Tomato Bruschetta"},{"id":105,"need":["tortilla","spinach","feta","mozzarella"],"amounts":{"tortilla":"1 large or 2 small","spinach":"60 g","feta":"40 g","mozzarella":"30 g"},"servings":1,"equipment":"Nonstick frying pan","steps":["Wash and roughly chop spinach (60 g). Put in a nonstick pan with 1 tablespoon water and cook for 1–2 minutes until wilted. Let the moisture evaporate and transfer to a plate.","Fill half of tortillas (1 large or 2 small) with the spinach, crumbled feta (40 g), and torn mozzarella (30 g). Fold closed.","Cook in the dry pan over medium-low heat for 2–3 minutes per side until golden and the mozzarella melts. Rest for 1 minute before cutting."],"time":12,"title":"Spinach Feta Quesadilla"},{"id":106,"need":["shrimp","rice","garlic","lemon","butter"],"amounts":{"shrimp":"150 g raw peeled shrimp, thawed if frozen","rice":"75 g dry","garlic":"1 small clove","lemon":"½, about 1 tbsp juice","butter":"10 g"},"servings":1,"equipment":"Saucepan and frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Finely chop garlic (1 small clove) and pat shrimp (150 g raw peeled shrimp, thawed if frozen) dry. Melt butter (10 g) in a frying pan over medium heat and stir in the garlic for 30 seconds.","Add the shrimp and cook for about 2–3 minutes per side, until pearly and opaque throughout. Larger shrimp may need longer.","Stir in lemon (½, about 1 tbsp juice) and 1 tablespoon water to loosen the pan juices. Serve the shrimp and juices over the rice."],"time":25,"title":"Lemon Garlic Shrimp Rice"},{"id":107,"need":["chickpeas","carrot","broccoli","oliveoil","paprika"],"amounts":{"chickpeas":"150 g canned, drained and rinsed","carrot":"1 medium, 80 g","broccoli":"150 g","oliveoil":"1 tsp, 5 ml","paprika":"½ tsp"},"servings":1,"equipment":"Oven, tray, and bowl","steps":["Heat the oven to 200°C (180°C fan). Drain and pat chickpeas (150 g canned, drained and rinsed) dry. Cut carrot (1 medium, 80 g) into thin half-moons and broccoli (150 g) into small florets.","Toss the chickpeas and vegetables on a lined tray with olive oil (1 tsp, 5 ml) and paprika (½ tsp). Spread out in a single layer.","Roast for 20–25 minutes, turning after 12 minutes, until the carrot is tender, the broccoli has golden edges, and the chickpeas are hot.","Spoon into a bowl and serve immediately."],"time":32,"title":"Roasted Chickpea Bowl"},{"id":108,"need":["bread","mushroom","cream","garlic"],"amounts":{"bread":"2 slices","mushroom":"150 g","cream":"3 tbsp","garlic":"1 small clove"},"servings":1,"equipment":"Nonstick frying pan and toaster","steps":["Wipe and thinly slice mushroom (150 g). Finely chop garlic (1 small clove).","Put the mushrooms in a nonstick pan with 2 tablespoons water. Cook over medium heat for 6–8 minutes until soft and most moisture has evaporated. Add the garlic for the final minute.","Lower the heat, add cream (3 tbsp), and simmer gently for 2 minutes until slightly thickened. Do not boil hard.","Toast bread (2 slices) until golden. Spoon over the hot mushrooms and sauce and serve immediately."],"time":15,"title":"Creamy Mushroom Toast"},{"id":109,"need":["bread","cucumber","avocado","creamcheese"],"amounts":{"bread":"2 slices","cucumber":"¼ medium, 80 g","avocado":"½ medium","creamcheese":"35 g"},"servings":1,"equipment":"Chopping board and fork","steps":["Wash and thinly slice cucumber (¼ medium, 80 g). Scoop avocado (½ medium) into a bowl and mash roughly with a fork.","Spread cream cheese (35 g) on one slice of bread (2 slices) and the avocado on the other. Layer the cucumber over the cream cheese.","Close, press gently, and cut in half. Serve straight away so the avocado stays fresh."],"time":8,"title":"Cucumber Avocado Sandwich"},{"id":110,"need":["coconut","frozenberries","milk","honey"],"amounts":{"coconut":"1 tbsp","frozenberries":"100 g","milk":"200 ml","honey":"1 tsp"},"servings":1,"equipment":"Blender and small saucepan if the berry packet requires heating","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. Prepare the frozen berries according to their packet, including any required heating, then cool completely before blending.","Put milk (200 ml), frozen berries (100 g), coconut (1 tbsp), honey (1 tsp) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":8,"title":"Coconut Berry Smoothie"},{"id":111,"need":["cottagecheese","strawberry","blueberries","honey"],"amounts":{"cottagecheese":"170 g","strawberry":"60 g","blueberries":"60 g","honey":"1 tsp"},"servings":1,"equipment":"Bowl and chopping board","steps":["Wash strawberries (60 g) and blueberries (60 g). Remove the strawberry stalks and slice the berries.","Spoon cottage cheese (170 g) into a bowl, arrange the fruit on top, and drizzle with honey (1 tsp).","Serve chilled straight away, or cover and refrigerate until needed."],"time":5,"title":"Cottage Cheese Berry Bowl"},{"id":112,"need":["bread","cottagecheese","tomato","cucumber","pepper"],"amounts":{"bread":"2 slices","cottagecheese":"120 g","tomato":"½ medium","cucumber":"¼ medium","pepper":"1 small pinch, about ⅛ tsp"},"servings":1,"equipment":"Toaster and chopping board","steps":["Toast bread (2 slices) for 2–3 minutes until golden and crisp. Thinly slice tomato (½ medium) and cucumber (¼ medium).","Divide cottage cheese (120 g) between the toast slices and spread gently, keeping the curds intact.","Arrange the tomato and cucumber over the cheese, sprinkle with black pepper (1 small pinch, about ⅛ tsp), and serve immediately."],"time":8,"title":"Savory Cottage Cheese Toast"},{"id":113,"need":["cottagecheese","banana","eggs","oats","bakingpowder"],"amounts":{"cottagecheese":"80 g","banana":"½ small","eggs":"1","oats":"35 g","bakingpowder":"¼ tsp"},"servings":1,"equipment":"Blender and good nonstick frying pan","steps":["Blend cottage cheese (80 g), banana (½ small), eggs (1), oats (35 g), and baking powder (¼ tsp) for 30–45 seconds until mostly smooth.","Let the batter stand for 5 minutes so the oats thicken it. Warm a good nonstick pan over medium-low heat.","Spoon in small 2-tablespoon pancakes, leaving space to turn them. Cook for 2–3 minutes until the edges set.","Flip carefully and cook for another 2 minutes until golden and fully set in the middle. Repeat with the remaining batter and serve warm."],"time":20,"title":"Cottage Cheese Banana Pancakes"},{"id":114,"need":["cottagecheese","pasta","tomatosauce","garlic","oliveoil"],"amounts":{"cottagecheese":"100 g","pasta":"90 g dry","tomatosauce":"150 g","garlic":"1 small clove","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Saucepan, frying pan, and blender","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Finely chop garlic (1 small clove). Heat olive oil (1 tsp, 5 ml) in a pan over low-medium heat. Cook the garlic for 30 seconds, then add tomato sauce (150 g) and simmer gently for 5 minutes.","Remove from the heat. Add cottage cheese (100 g) and blend carefully until smooth, following your blender’s directions for warm liquids.","Return the sauce and pasta to the pan over low heat. Toss for 1–2 minutes, adding reserved pasta water 1 tablespoon at a time until creamy. Warm gently without boiling."],"time":22,"title":"Cottage Cheese Tomato Pasta"},{"id":115,"need":["eggs","cottagecheese","spinach","oliveoil","pepper"],"amounts":{"eggs":"2","cottagecheese":"60 g","spinach":"60 g","oliveoil":"1 tsp, 5 ml","pepper":"1 small pinch, about ⅛ tsp"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Wash and chop spinach (60 g). Beat eggs (2) with black pepper (1 small pinch, about ⅛ tsp) in a bowl.","Heat olive oil (1 tsp, 5 ml) in a nonstick pan over medium-low heat. Add the spinach and cook for 1–2 minutes until wilted.","Pour in the eggs and cook gently for 2–3 minutes, drawing the set edges in with a spatula.","Spoon cottage cheese (60 g) over one half and fold the omelette. Cook gently for another 1–2 minutes until the egg is fully set and the filling is warm."],"time":12,"title":"Cottage Cheese & Spinach Omelette"},{"id":116,"need":["bread","ricotta","lemon","honey"],"amounts":{"bread":"2 slices","ricotta":"80 g","lemon":"¼, zest and 1 tsp juice","honey":"1 tsp"},"servings":1,"equipment":"Toaster, small bowl, and grater","steps":["Wash lemon (¼, zest and 1 tsp juice). Finely grate a little zest, avoiding the bitter white pith, and squeeze out 1 teaspoon juice.","Stir the zest and juice into ricotta (80 g) for about 20 seconds until combined.","Toast bread (2 slices) for 2–3 minutes until crisp. Spread with the lemon ricotta, drizzle with honey (1 tsp), and serve."],"time":8,"title":"Lemon Ricotta Toast"},{"id":117,"need":["ricotta","spinach","pasta","garlic","parmesan","oliveoil"],"amounts":{"ricotta":"80 g","spinach":"60 g","pasta":"90 g dry","garlic":"1 small clove","parmesan":"15 g","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Saucepan and frying pan","steps":["Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Finely chop garlic (1 small clove) and wash spinach (60 g). Heat olive oil (1 tsp, 5 ml) over medium-low heat; cook the garlic for 30 seconds, then add the spinach and stir for 1–2 minutes until wilted.","Turn the heat low. Stir in ricotta (80 g), most of parmesan (15 g), and 2 tablespoons reserved pasta water until creamy.","Add the pasta and toss for 1 minute. Loosen with more cooking water if needed and finish with the remaining measured parmesan."],"time":20,"title":"Ricotta & Spinach Pasta"},{"id":118,"need":["halloumi","bellpepper","tortilla","lettuce","oliveoil"],"amounts":{"halloumi":"100 g","bellpepper":"½ large","tortilla":"1 large or 2 small","lettuce":"2 large leaves, washed","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Nonstick frying pan and chopping board","steps":["Cut halloumi (100 g) into 1 cm slices and bell pepper (½ large) into thin strips. Wash and shred lettuce (2 large leaves, washed).","Heat olive oil (1 tsp, 5 ml) over medium heat. Cook the pepper for 5–6 minutes until softened and lightly browned; transfer to a plate.","Cook the halloumi in the same pan for 1–2 minutes per side until golden. Warm tortillas (1 large or 2 small) for about 20 seconds per side in the dry part of the pan or as directed on its packet.","Fill with lettuce, pepper, and halloumi. Fold in the sides, roll tightly, and serve while the cheese is warm."],"time":18,"title":"Halloumi & Pepper Wrap"},{"id":119,"need":["halloumi","couscous","cucumber","tomato","lemon","oliveoil"],"amounts":{"halloumi":"80 g","couscous":"60 g dry","cucumber":"¼ medium, 80 g","tomato":"1 medium, 120 g","lemon":"½, about 1 tbsp juice","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Heatproof bowl and nonstick frying pan","steps":["Put couscous (60 g dry) in a heatproof bowl. Add boiling water in the ratio on its packet (often equal volumes), cover with a plate, and leave for 5–10 minutes or the packet time. Fluff with a fork so the grains separate.","Dice cucumber (¼ medium, 80 g) and tomato (1 medium, 120 g). Toss in a bowl with lemon (½, about 1 tbsp juice) and half of olive oil (1 tsp, 5 ml).","Slice halloumi (80 g) 1 cm thick. Heat the remaining oil in a nonstick pan over medium heat and cook the halloumi for 1–2 minutes per side until golden.","Spoon the couscous into a bowl and add the dressed vegetables and warm halloumi. Serve immediately."],"time":18,"title":"Halloumi Couscous Bowl"},{"id":120,"need":["kefir","strawberry","banana"],"amounts":{"kefir":"200 ml plain","strawberry":"100 g","banana":"½ small"},"servings":1,"equipment":"Blender","steps":["Prepare the fruit: wash fresh fruit, remove any inedible skins, stalks, stones, or cores, and chop into 2–3 cm pieces. ","Put kefir (200 ml plain), strawberries (100 g), banana (½ small) in a blender, adding the liquid first so the blades can turn easily.","Blend for 30–60 seconds until smooth. Stop and scrape down the sides if needed; add water 1 tablespoon at a time if too thick. Pour into a glass and serve straight away."],"time":5,"title":"Strawberry Kefir Smoothie"},{"id":121,"need":["beetroot","feta","arugula","walnuts","oliveoil","vinegar"],"amounts":{"beetroot":"180 g raw, peeled","feta":"40 g","arugula":"1 large handful, 30 g, washed","walnuts":"15 g","oliveoil":"2 tsp","vinegar":"1 tsp"},"servings":1,"equipment":"Oven, tray, and bowl","steps":["Heat the oven to 200°C (180°C fan). Peel beetroot (180 g raw, peeled) and cut into 1–1.5 cm cubes. Toss with 1 teaspoon of olive oil (2 tsp).","Spread on a lined tray and roast for 25–35 minutes, turning halfway, until easily pierced with a fork. Let cool for 5 minutes.","Arrange arugula (1 large handful, 30 g, washed) in a bowl. Add the warm beetroot, crumbled feta (40 g), and roughly chopped walnuts (15 g).","Drizzle with the remaining measured oil and vinegar (1 tsp). Toss gently and serve."],"time":45,"title":"Roasted Beetroot & Feta Salad"},{"id":122,"need":["radish","cucumber","greekyogurt","lemon","garlic"],"amounts":{"radish":"4 small, 50 g","cucumber":"¼ medium","greekyogurt":"150 g","lemon":"1 tsp juice","garlic":"½ small clove"},"servings":1,"equipment":"Grater, clean cloth, and bowl","steps":["Coarsely grate cucumber (¼ medium). Put in a clean cloth or fine sieve and squeeze firmly to remove excess water.","Wash and finely chop radishes (4 small, 50 g). Finely grate garlic (½ small clove).","Stir the cucumber, radish, and garlic into Greek yogurt (150 g). Add lemon (1 tsp juice) and stir for 20 seconds.","Serve immediately, or cover and chill for 10 minutes for a stronger flavour. Chilling is optional."],"time":10,"title":"Radish & Cucumber Yogurt Dip"},{"id":123,"need":["leek","potato","onion","milk","butter"],"amounts":{"leek":"1 small, 100 g","potato":"200 g","onion":"½ small","milk":"100 ml","butter":"10 g"},"servings":1,"equipment":"Saucepan and stick blender","steps":["Trim leek (1 small, 100 g), slice thinly, and rinse between the layers to remove grit. Finely dice onion (½ small); peel potato (200 g) and cut into 1.5 cm cubes.","Melt butter (10 g) in a saucepan over medium-low heat. Add the leek and onion and cook for 6–8 minutes, stirring, until soft but not browned.","Add the potato and 300 ml water, enough to just cover. Simmer for 15–20 minutes until the potato crushes easily with a fork.","Remove from the heat and blend carefully, following your blender’s instructions for hot liquids. Stir in milk (100 ml), warm gently for 2 minutes, and add water if too thick."],"time":35,"title":"Creamy Leek & Potato Soup"},{"id":124,"need":["pumpkin","chickpeas","spinach","oliveoil","paprika"],"amounts":{"pumpkin":"200 g","chickpeas":"150 g canned, drained and rinsed","spinach":"60 g","oliveoil":"1 tsp, 5 ml","paprika":"½ tsp"},"servings":1,"equipment":"Oven and baking tray","steps":["Heat the oven to 200°C (180°C fan). Cut pumpkin (200 g) into 1.5 cm cubes and pat chickpeas (150 g canned, drained and rinsed) dry.","Toss both with olive oil (1 tsp, 5 ml) and paprika (½ tsp). Spread in one layer on a lined baking tray.","Roast for 25–30 minutes, turning halfway, until the pumpkin is tender and the chickpeas are hot and lightly golden.","Put washed spinach (60 g) in a bowl and spoon the hot pumpkin and chickpeas over it. Toss briefly so the leaves soften and serve."],"time":38,"title":"Roasted Pumpkin & Chickpea Bowl"},{"id":125,"need":["pumpkin","redlentils","onion","cumin","oliveoil"],"amounts":{"pumpkin":"200 g","redlentils":"60 g dry, rinsed","onion":"½ small","cumin":"½ tsp","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Saucepan and stick blender","steps":["Peel pumpkin (200 g) and cut into 1.5 cm cubes. Finely dice onion (½ small) and rinse red lentils (60 g dry, rinsed).","Heat olive oil (1 tsp, 5 ml) over medium-low heat. Cook the onion for 4–5 minutes until soft, then stir in cumin (½ tsp) for 30 seconds.","Add the pumpkin, lentils, and 500 ml water. Simmer gently for 20–25 minutes, stirring occasionally, until the lentils are soft and the pumpkin breaks apart with a fork. Add water if needed.","Remove from the heat and blend carefully to your preferred texture, following your blender’s instructions for hot liquids. Return to low heat briefly if needed and serve."],"time":35,"title":"Pumpkin & Red Lentil Soup"},{"id":126,"need":["edamame","rice","eggs","carrot","soyauce","sesameoil"],"amounts":{"edamame":"100 g shelled frozen","rice":"75 g dry","eggs":"1","carrot":"1 small","soyauce":"2 tsp","sesameoil":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Cook edamame (100 g shelled frozen) for the full time on its packet; drain. Peel and finely dice carrot (1 small). Beat eggs (1) in a bowl.","Heat sesame oil (1 tsp) over medium heat. Add the carrot and 1 tablespoon water; stir-fry for 4–5 minutes until tender.","Push the carrot aside and add the egg. Stir for 1–2 minutes until fully set, then fold in the rice, edamame, and soy sauce (2 tsp).","Toss over the heat for 2–3 minutes until steaming hot throughout. Serve immediately."],"time":30,"title":"Edamame Fried Rice"},{"id":127,"need":["bulgur","tomato","cucumber","parsley","lemon","oliveoil"],"amounts":{"bulgur":"60 g dry","tomato":"1 medium, 120 g","cucumber":"¼ medium, 80 g","parsley":"1 tbsp chopped","lemon":"½, about 1 tbsp juice","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"Saucepan, bowl, and chopping board","steps":["Cook bulgur (60 g dry) in water according to its packet, usually a gentle simmer for 10–15 minutes. Drain if needed, fluff with a fork, and let steam escape for 5 minutes.","Finely dice tomato (1 medium, 120 g) and cucumber (¼ medium, 80 g). Wash and chop parsley (1 tbsp chopped).","Fold the vegetables and parsley into the warm bulgur. Add lemon (½, about 1 tbsp juice) and olive oil (1 tsp, 5 ml) and toss gently.","Serve warm, or cover and refrigerate promptly for a cold salad later."],"time":25,"title":"Lemon Herb Bulgur Salad"},{"id":128,"need":["redlentils","tomatosauce","onion","garlic","curry","oliveoil"],"amounts":{"redlentils":"75 g dry","tomatosauce":"150 g","onion":"½ small","garlic":"1 small clove","curry":"1 tsp mild curry powder","oliveoil":"1 tsp, 5 ml"},"servings":1,"equipment":"One saucepan","steps":["Rinse red lentils (75 g dry). Finely chop onion (½ small) and garlic (1 small clove).","Heat olive oil (1 tsp, 5 ml) over medium-low heat. Cook the onion for 5 minutes, adding a spoonful of water if it sticks. Stir in the garlic and curry powder (1 tsp mild curry powder) for 30 seconds.","Add the lentils and 300 ml water. Simmer gently for 12–15 minutes, stirring often, until the lentils begin to soften.","Add tomato sauce (150 g) and simmer for another 10–15 minutes, until the lentils are completely tender and the dahl is thick and creamy. Add water in small splashes as needed; older lentils may take longer."],"time":35,"title":"Red Lentil Tomato Dahl"},{"id":129,"need":["tahini","chickpeas","lemon","garlic","oliveoil"],"amounts":{"tahini":"1 tbsp, 15 g","chickpeas":"180 g canned, drained and rinsed","lemon":"½, about 1 tbsp juice","garlic":"1 small clove","oliveoil":"2 tsp"},"servings":1,"equipment":"Blender and bowl","steps":["Drain and rinse chickpeas (180 g canned, drained and rinsed), reserving a teaspoon of them for the top. Peel garlic (1 small clove).","Blend the chickpeas, tahini (1 tbsp, 15 g), lemon (½, about 1 tbsp juice), garlic, and 1½ teaspoons of olive oil (2 tsp) with 2 tablespoons cold water for 45–60 seconds.","Scrape down the sides and blend again, adding water 1 tablespoon at a time until smooth and creamy.","Spoon into a bowl, swirl with the back of a spoon, and add the reserved chickpeas and remaining ½ teaspoon oil."],"time":10,"title":"Tahini Lemon Hummus"},{"id":130,"need":["bread","tahini","banana","maplesyrup","cinnamon"],"amounts":{"bread":"2 slices","tahini":"1 tbsp","banana":"½ small","maplesyrup":"1 tbsp","cinnamon":"¼ tsp"},"servings":1,"equipment":"Toaster and chopping board","steps":["Toast bread (2 slices) for 2–3 minutes until golden. Stir tahini (1 tbsp) in its jar before measuring, then spread the measured amount over the toast.","Peel and slice banana (½ small) and arrange on top.","Drizzle with maple syrup (1 tbsp), dust with cinnamon (¼ tsp), and serve immediately."],"time":5,"title":"Maple Tahini Banana Toast"},{"id":131,"need":["ricecakes","cottagecheese","strawberry","honey"],"amounts":{"ricecakes":"3","cottagecheese":"100 g","strawberry":"60 g","honey":"1 tsp"},"servings":1,"equipment":"Plate and chopping board","steps":["Wash and hull strawberries (60 g), then slice thinly. Set out rice cakes (3).","Divide cottage cheese (100 g) between the rice cakes, spreading it gently to the edges.","Top with strawberry slices and drizzle with honey (1 tsp). Eat immediately while the rice cakes are crisp."],"time":5,"title":"Cottage Cheese Berry Rice Cakes"},{"id":132,"need":["ricecakes","peanutbutter","banana","cinnamon"],"amounts":{"ricecakes":"3","peanutbutter":"1 tbsp","banana":"½ small","cinnamon":"¼ tsp"},"servings":1,"equipment":"Plate and chopping board","steps":["Peel and thinly slice banana (½ small). Set out rice cakes (3).","Spread peanut butter (1 tbsp) evenly over the rice cakes, then arrange the banana slices on top.","Dust lightly with cinnamon (¼ tsp) and eat straight away."],"time":5,"title":"Peanut Butter Banana Rice Cakes"},{"id":133,"need":["dates","peanutbutter","chocolatechips"],"amounts":{"dates":"4 large soft dates","peanutbutter":"2 tsp","chocolatechips":"10 g"},"servings":1,"equipment":"Chopping board and teaspoon","steps":["Slice dates (4 large soft dates) lengthwise without cutting all the way through. Remove and discard the stones if present.","Divide peanut butter (2 tsp) between the opened dates, using the tip of a teaspoon.","Press chocolate chips (10 g) into the fillings, dividing evenly. Close the dates slightly and serve as a snack."],"time":8,"title":"Peanut Butter Stuffed Dates"},{"id":134,"need":["dates","banana","milk","cinnamon"],"amounts":{"dates":"3 small pitted dates","banana":"1 small, peeled","milk":"200 ml","cinnamon":"¼ tsp"},"servings":1,"equipment":"Blender and small bowl","steps":["Check dates (3 small pitted dates) for stones and remove any. If the dates are firm, soak in warm water for 10 minutes, then drain; soft dates can be used straight away.","Peel banana (1 small, peeled). Put milk (200 ml), the dates, banana, and cinnamon (¼ tsp) in a blender.","Blend for 45–60 seconds until completely smooth, stopping to scrape down any date pieces. Add water 1 tablespoon at a time if too thick and serve immediately."],"time":8,"title":"Banana Date Smoothie"},{"id":135,"need":["sweetpotato","groundbeef","cottagecheese","avocado","hothoney","oliveoil","paprika","cumin"],"amounts":{"sweetpotato":"1 medium-large, 250–300 g","groundbeef":"125 g raw lean","cottagecheese":"70 g","avocado":"½ small","hothoney":"1 tsp","oliveoil":"2 tsp, divided","paprika":"½ tsp","cumin":"¼ tsp"},"servings":1,"equipment":"Oven, baking tray, and nonstick frying pan","steps":["Heat the oven to 200°C (180°C fan). Scrub sweet potato (1 medium-large, 250–300 g), dry it, and prick several times. Rub with 1 teaspoon of olive oil (2 tsp, divided).","Bake on a lined tray for 45–60 minutes, until a knife slides easily through the centre; a larger potato may need longer.","Meanwhile, heat the remaining 1 teaspoon oil over medium heat. Add ground beef (125 g raw lean) and break into small crumbles. Stir in paprika (½ tsp) and cumin (¼ tsp). Cook for about 7–10 minutes, stirring often, until the meat reaches 71°C in the centre, checked with a food thermometer.","Slice avocado (½ small). Split the hot potato and fluff the flesh with a fork, taking care as steam escapes.","Spoon in the cooked meat, add cottage cheese (70 g) and the avocado, then drizzle with hot honey (1 tsp). Serve immediately."],"time":70,"title":"Hot Honey Beef Loaded Sweet Potato"},{"id":136,"need":["sweetpotato","groundchicken","cottagecheese","avocado","hothoney","oliveoil","paprika","cumin"],"amounts":{"sweetpotato":"1 medium-large, 250–300 g","groundchicken":"125 g raw","cottagecheese":"70 g","avocado":"½ small","hothoney":"1 tsp","oliveoil":"2 tsp, divided","paprika":"½ tsp","cumin":"¼ tsp"},"servings":1,"equipment":"Oven, baking tray, and nonstick frying pan","steps":["Heat the oven to 200°C (180°C fan). Scrub sweet potato (1 medium-large, 250–300 g), dry it, and prick several times. Rub with 1 teaspoon of olive oil (2 tsp, divided).","Bake on a lined tray for 45–60 minutes, until a knife slides easily through the centre; a larger potato may need longer.","Meanwhile, heat the remaining 1 teaspoon oil over medium heat. Add ground chicken (125 g raw) and break into small crumbles. Stir in paprika (½ tsp) and cumin (¼ tsp). Cook for about 7–10 minutes, stirring often, until the meat reaches 74°C in the centre, checked with a food thermometer.","Slice avocado (½ small). Split the hot potato and fluff the flesh with a fork, taking care as steam escapes.","Spoon in the cooked meat, add cottage cheese (70 g) and the avocado, then drizzle with hot honey (1 tsp). Serve immediately."],"time":70,"title":"Hot Honey Chicken Loaded Sweet Potato"},{"id":137,"need":["groundbeef","tortilla","cheese","lettuce","pickles","mayo","mustard","oliveoil"],"amounts":{"groundbeef":"125 g","tortilla":"2 small","cheese":"30 g","lettuce":"1 leaf","pickles":"2 small, sliced","mayo":"1 tbsp","mustard":"½ tsp","oliveoil":"½ tsp"},"servings":1,"equipment":"Bowl, chopping board, and nonstick frying pan","steps":["Mix mayo (1 tbsp) with mustard (½ tsp). Shred lettuce (1 leaf) and slice pickles (2 small, sliced). Set out cheese (30 g).","Divide ground beef (125 g) between tortillas (2 small). Press onto one side of each tortilla in a very thin, even layer, reaching almost to the edges.","Heat olive oil (½ tsp) in a nonstick pan over medium-high heat. Place one tortilla beef-side down and press with a spatula. Cook for about 3–4 minutes until browned.","Flip, add half the cheese, and cook over medium-low heat for 1–2 minutes until the tortilla is crisp and the beef reaches 71°C. Check with a thermometer inserted sideways into the meat and cook longer if needed. Repeat for the second taco.","Add lettuce, pickles, and the mayo-mustard sauce. Fold and serve hot."],"time":25,"title":"Smash Burger Tacos"},{"id":138,"need":["cottagecheese","eggs","turkey","lettuce","tomato","pepper","oliveoil"],"amounts":{"cottagecheese":"200 g","eggs":"2","turkey":"60 g ready-to-eat cooked slices","lettuce":"2 large leaves, washed","tomato":"½ small","pepper":"1 small pinch, about ⅛ tsp","oliveoil":"½ tsp"},"servings":1,"equipment":"Oven, lined tray, and blender","steps":["Heat the oven to 180°C (160°C fan). Line a tray with baking paper and brush the paper with olive oil (½ tsp).","Blend cottage cheese (200 g), eggs (2), and black pepper (1 small pinch, about ⅛ tsp) for 20–30 seconds until smooth. Pour into a thin rectangle about 20 × 25 cm on the prepared tray.","Bake for 30–40 minutes until the centre is fully set and the edges are lightly golden. Let cool on the tray for 10 minutes so it releases without tearing.","Wash and shred lettuce (2 large leaves, washed), and slice tomato (½ small). Peel the flatbread gently from the paper and top with turkey (60 g ready-to-eat cooked slices), lettuce, and tomato.","Roll carefully, cut in half, and serve. Use ready-to-eat cooked turkey stored as directed on its packet."],"time":55,"title":"Cottage Cheese Flatbread Wrap"},{"id":139,"need":["rice","edamame","cucumber","avocado","lime","soyauce","sesameoil"],"amounts":{"rice":"60 g dry","edamame":"100 g shelled frozen","cucumber":"¼ medium, 80 g","avocado":"½ medium","lime":"½, about 1 tbsp juice","soyauce":"2 tsp, divided","sesameoil":"2 tsp, divided"},"servings":1,"equipment":"Saucepan, oven, tray, and bowl","steps":["Heat the oven to 200°C (180°C fan). Cook rice (60 g dry) according to its packet. Spread on a plate for 5 minutes so excess steam escapes.","Toss the freshly cooked rice with 1 teaspoon of sesame oil (2 tsp, divided) and 1 teaspoon of soy sauce (2 tsp, divided). Spread thinly over a lined baking tray.","Bake for 20–25 minutes, stirring halfway, until lightly golden and crisp. Stop before the grains become hard and let cool for 5 minutes.","Cook edamame (100 g shelled frozen) according to its packet; drain. Dice cucumber (¼ medium, 80 g) and avocado (½ medium).","Mix lime (½, about 1 tbsp juice) with the remaining measured soy sauce and sesame oil. Toss with the vegetables and add the crispy rice just before serving. Serve promptly."],"time":50,"title":"Crispy Rice & Edamame Salad"},{"id":140,"need":["potato","cucumber","greekyogurt","mustard","lemon","springonion","oliveoil"],"amounts":{"potato":"250 g small potatoes","cucumber":"¼ medium, 80 g","greekyogurt":"80 g","mustard":"1 tsp","lemon":"1 tsp juice","springonion":"1, trimmed","oliveoil":"2 tsp"},"servings":1,"equipment":"Saucepan, oven, tray, and bowl","steps":["Heat the oven to 220°C (200°C fan). Put potato (250 g small potatoes) in a saucepan, cover with water, and boil gently for 15–20 minutes until completely tender. Drain and let steam dry for 5 minutes.","Put the potatoes on a lined tray and gently flatten each to about 1 cm thick with the base of a glass. Brush with olive oil (2 tsp).","Roast for 25–30 minutes, turning if needed, until the edges are deeply golden and crisp. Let cool for 5 minutes.","Mix Greek yogurt (80 g), mustard (1 tsp), and lemon (1 tsp juice). Dice cucumber (¼ medium, 80 g), thinly slice green onions (1, trimmed), and stir both into the dressing.","Fold the still-warm potatoes through the dressing just before serving to preserve some crunch."],"time":60,"title":"Crispy Smashed Potato Salad"},{"id":141,"need":["groundchicken","rice","cottagecheese","cucumber","avocado","hothoney","oliveoil","paprika"],"amounts":{"groundchicken":"125 g raw","rice":"75 g dry","cottagecheese":"70 g","cucumber":"¼ medium","avocado":"½ small","hothoney":"1 tsp","oliveoil":"1 tsp, 5 ml","paprika":"½ tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Heat olive oil (1 tsp, 5 ml) over medium heat. Add ground chicken (125 g raw), break into small crumbles, and stir in paprika (½ tsp). Cook for about 7–10 minutes, stirring often, until the chicken reaches 74°C throughout.","Dice cucumber (¼ medium) and slice avocado (½ small). Spoon the rice into a bowl and arrange the chicken, cottage cheese (70 g), cucumber, and avocado on top.","Drizzle with hot honey (1 tsp) and serve immediately."],"time":25,"title":"Hot Honey Chicken Rice Bowl"},{"id":142,"need":["pasta","feta","tomato","garlic","basil","oliveoil","pepper"],"amounts":{"pasta":"90 g dry","feta":"80 g","tomato":"200 g cherry tomatoes or chopped tomatoes","garlic":"1 clove","basil":"5–6 leaves","oliveoil":"2 tsp","pepper":"1 small pinch, about ⅛ tsp"},"servings":1,"equipment":"Oven, baking dish, and saucepan","steps":["Heat the oven to 200°C (180°C fan). Put tomato (200 g cherry tomatoes or chopped tomatoes) and peeled garlic (1 clove) in a small baking dish. Toss with olive oil (2 tsp) and black pepper (1 small pinch, about ⅛ tsp).","Place feta (80 g) in the middle and turn once to coat lightly in the oil. Bake for 25–30 minutes until the tomatoes are very soft and the feta is warmed through and golden at the edges.","Bring about 1 litre water to a boil in a saucepan. Add pasta (90 g dry) and simmer for the packet time, usually 8–12 minutes, stirring once or twice. Reserve 100 ml cooking water, then drain when tender with a slight bite.","Mash the baked feta, garlic, and tomatoes with a fork. Add the pasta and torn basil (5–6 leaves), then toss, adding reserved cooking water 1 tablespoon at a time until saucy. Serve hot."],"time":40,"title":"Baked Feta & Tomato Pasta"},{"id":143,"need":["pasta","tomatosauce","cheese"],"amounts":{"pasta":"100 g","tomatosauce":"150 g","cheese":"30 g grated"},"servings":1,"equipment":"One saucepan","steps":["Put the dry pasta (100 g), tomato sauce (150 g), and about 250 ml water in a small saucepan. Add a little more water if needed to just cover the pasta.","Bring to a gentle simmer over medium heat, then reduce to medium-low. Cook uncovered for the pasta packet time, usually 8–12 minutes, stirring every minute so it does not stick. Add hot water 1 tablespoon at a time if the pan dries out before the pasta is tender.","Check the pasta by tasting one piece: it should be tender with a slight bite. The sauce should coat the pasta rather than sit as a watery layer; simmer for 1 more minute if needed.","Take off the heat and stir in the cheese (30 g grated) for 30–60 seconds until melted. Let stand for 1 minute so the sauce settles, then serve."],"time":18,"title":"3-Ingredient Cheesy Tomato Pasta"},{"id":144,"need":["tortilla","tuna","cheese","tomato"],"amounts":{"tortilla":"1 large","tuna":"1 small tin, drained","cheese":"30 g grated","tomato":"1 small, thinly sliced"},"servings":1,"equipment":"One nonstick frying pan","steps":["Drain the tuna (1 small tin, drained) well. Thinly slice the tomato (1 small, thinly sliced) and blot away excess juice. Lay the tortilla (1 large) flat and arrange the tuna, tomato, and cheese (30 g grated) over one half, leaving a 1 cm border.","Fold the empty half over the filling.","Cook in a dry nonstick frying pan over medium-low heat for 2–3 minutes on each side, until crisp and the cheese has melted.","Rest on a board for 1 minute so the filling settles, then cut into wedges and serve warm."],"time":10,"title":"Crispy Tuna Melt Tortilla"},{"id":145,"need":["potato","bakedbeans","cheese"],"amounts":{"potato":"1 large baking potato, 250–300 g","bakedbeans":"½ a 400 g tin","cheese":"30 g grated"},"servings":1,"equipment":"Microwave, plate, and bowl","steps":["Scrub the potato (1 large baking potato, 250–300 g) and prick it several times with a fork. Put it on a microwave-safe plate.","Microwave on high for 5 minutes, turn it over, then cook for another 3–5 minutes. Continue in 1-minute bursts until it is soft all the way through; timing depends on the potato and microwave.","Put the baked beans (½ a 400 g tin) in a microwave-safe bowl, cover loosely, and heat in 1-minute bursts, stirring until piping hot.","Split the potato and fluff the inside with a fork. Add the beans and cheese (30 g grated).","If needed, microwave for another 20–30 seconds to melt the cheese. Let stand for 1 minute before serving, taking care as steam escapes from the potato."],"time":20,"title":"Microwave Beans & Cheese Potato"},{"id":146,"need":["rice","eggs","butter","soyauce"],"amounts":{"rice":"75 g dry","eggs":"2","butter":"10 g","soyauce":"1–2 tsp"},"servings":1,"equipment":"One saucepan and frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Melt the butter (10 g) in a nonstick frying pan over medium-low heat.","Crack in the eggs (2), cover, and cook over medium-low heat for about 3–5 minutes, until both the whites and yolks are fully set. Turn gently if needed to finish the top.","Spoon the hot rice into a bowl, add the eggs, and drizzle with soy sauce (1–2 tsp) and the buttery pan juices."],"time":20,"title":"Buttery Soy Egg Rice"},{"id":147,"need":["noodles","peanutbutter","frozenpeas","soyauce","lime"],"amounts":{"noodles":"90 g dry","peanutbutter":"1½ tbsp","frozenpeas":"100 g","soyauce":"1 tbsp","lime":"½"},"servings":1,"equipment":"One saucepan","steps":["Bring about 1 litre water to a boil. Add the noodles (90 g dry) and frozen peas (100 g) at the appropriate times so each gets its full packet cooking time; noodles often take 3–8 minutes, and peas usually 3–5 minutes.","Before draining, reserve 100 ml of cooking water. Drain the noodles and peas well, then return to the warm pan off the heat.","Return them to the warm pan with the peanut butter (1½ tbsp), soy sauce (1 tbsp), and lime juice (½).","Stir for 30–60 seconds, adding reserved cooking water 1 tablespoon at a time, until the peanut butter melts into a smooth sauce that coats the noodles. Serve straight away."],"time":15,"title":"Peanut Butter Pea Noodles"},{"id":148,"need":["chickpeas","cannedtomatoes","greekyogurt","bread","garlic"],"amounts":{"chickpeas":"½ a 400 g tin, drained","cannedtomatoes":"200 g","greekyogurt":"2 tbsp","bread":"2 thick slices","garlic":"1 small clove, finely chopped"},"servings":1,"equipment":"One saucepan and toaster","steps":["Peel and finely chop the garlic (1 small clove, finely chopped). Put in a small saucepan with the canned tomatoes (200 g) and 2 tablespoons water. Simmer over medium-low heat for 5 minutes, stirring occasionally.","Add the drained chickpeas (½ a 400 g tin, drained) and cook for another 4–5 minutes, until hot and the sauce has thickened.","Toast the bread (2 thick slices) for 2–3 minutes until golden and crisp, timing it to finish with the chickpeas.","Take the pan off the heat, stir in the yogurt (2 tbsp), and spoon everything over the toast."],"time":15,"title":"Creamy Tomato Chickpeas on Toast"},{"id":149,"need":["rice","broccoli","milk","cheese"],"amounts":{"rice":"75 g dry","broccoli":"150 g, cut into small florets","milk":"75 ml","cheese":"35 g grated"},"servings":1,"equipment":"One saucepan with a lid","steps":["Put the rice (75 g dry) in a lidded saucepan and add the amount of water stated on its packet, usually about 150 ml for 75 g white rice. Bring to a boil, cover, and cook on low heat for the packet time, usually 10–15 minutes.","Add the small broccoli (150 g, cut into small florets) florets for the final 5–7 minutes, replacing the lid so they steam until tender. Add a splash of water if the pan becomes dry.","When the rice is fully cooked and the water has been absorbed, stir in the milk (75 ml) and cheese (35 g grated).","Warm over low heat for 1–2 minutes, stirring until the cheese melts and the rice is creamy. Add water 1 tablespoon at a time if too thick, then serve."],"time":25,"title":"One-Pot Broccoli Cheese Rice"},{"id":150,"need":["bread","eggs","cheese","butter"],"amounts":{"bread":"2 slices","eggs":"2","cheese":"25 g grated","butter":"10 g"},"servings":1,"equipment":"One nonstick frying pan","steps":["Beat the eggs (2) in a bowl for 20 seconds. Measure butter (10 g); melt 5 g of it in a nonstick pan over medium-low heat, reserving the other 5 g. Add the eggs and stir gently for 2–3 minutes until fully set, then transfer to a plate.","Put the eggs and cheese (25 g grated) between the bread slices (2 slices).","Melt the remaining butter in the same pan and add the sandwich.","Toast over medium-low heat for 2–3 minutes on each side, pressing gently, until golden and the cheese has melted."],"time":12,"title":"Cheesy Egg Toastie"},{"id":151,"need":["potato","eggs","onion","oliveoil"],"amounts":{"potato":"250 g, cut into 1 cm cubes","eggs":"2","onion":"½ small, finely chopped","oliveoil":"1 tbsp"},"servings":1,"equipment":"One nonstick frying pan with a lid","steps":["Peel and cut the potato (250 g, cut into 1 cm cubes) into small, even 1 cm cubes. Finely chop the onion (½ small, finely chopped). Heat the olive oil (1 tbsp) in a nonstick pan over medium heat and add the potato, onion, and 2 tablespoons water.","Cover and cook over medium heat for 10–12 minutes, stirring a few times, until the potatoes are nearly tender. Add a little water if they catch.","Remove the lid and cook for another 4–5 minutes until the potatoes are tender and golden.","Make two spaces in the tender potatoes and crack in the eggs (2). Cover and cook on low heat for about 4–6 minutes, until the whites and yolks are fully set. Serve hot."],"time":30,"title":"One-Pan Egg & Potato Hash"},{"id":152,"need":["rice","beans","cannedtomatoes","cumin"],"amounts":{"rice":"75 g dry","beans":"½ a 400 g tin of cooked beans, drained","cannedtomatoes":"200 g","cumin":"½ tsp"},"servings":1,"equipment":"One saucepan with a lid","steps":["Finely chop any large pieces of canned tomato. Put the rice (75 g dry), canned tomatoes (200 g), cumin (½ tsp), and 150 ml water in a small saucepan. Keep extra hot water ready.","Bring to a gentle simmer, cover, and cook over low heat for the rice packet time, usually 10–15 minutes for white rice. Stir every few minutes so the tomatoes do not catch.","Add more water in small splashes if needed. Stir in the cooked beans (½ a 400 g tin of cooked beans, drained) for the final 5 minutes.","When the rice is tender and the beans are hot, let stand covered for 2 minutes, then fluff and serve."],"time":25,"title":"One-Pot Tomato Bean Rice"},{"id":153,"need":["pita","chickpeas","greekyogurt","paprika","oliveoil"],"amounts":{"pita":"1 large","chickpeas":"½ a 400 g tin, drained and patted dry","greekyogurt":"3 tbsp","paprika":"½ tsp","oliveoil":"2 tsp"},"servings":1,"equipment":"One frying pan","steps":["Drain and rinse the chickpeas (½ a 400 g tin, drained and patted dry), then pat dry well so they crisp instead of steaming. Heat the olive oil (2 tsp) over medium heat in a frying pan. Add the chickpeas and cook for 8–10 minutes, shaking regularly, until lightly crisp and hot.","Stir in the paprika (½ tsp) for the final 30 seconds, then move the chickpeas to a plate.","Warm the pita (1 large) in the same pan for about 30 seconds per side until flexible. Carefully cut open the pocket.","Spread yogurt (3 tbsp) inside the pita, add the chickpeas, and serve straight away."],"time":15,"title":"Crispy Chickpea Pita"},{"id":154,"need":["pasta","redlentils","cannedtomatoes","onion"],"amounts":{"pasta":"75 g dry","redlentils":"40 g dry, rinsed","cannedtomatoes":"200 g","onion":"½ small, finely chopped"},"servings":1,"equipment":"One saucepan","steps":["Rinse the red lentils (40 g dry, rinsed) and finely chop the onion (½ small, finely chopped). Put in a saucepan with the canned tomatoes (200 g) and 300 ml water.","Simmer gently for 10 minutes, stirring regularly.","Add the pasta (75 g dry) and enough extra hot water to just cover it, starting with 100 ml. Simmer for the pasta packet time, usually 8–12 minutes, stirring often and topping up with water if needed.","Continue until both the pasta and lentils are tender and the sauce is thick; some lentils may need a few extra minutes. Serve hot."],"time":30,"title":"One-Pot Lentil Tomato Pasta"},{"id":155,"need":["tortilla","corn","cheese"],"amounts":{"tortilla":"1 large","corn":"100 g canned sweetcorn, drained","cheese":"40 g grated"},"servings":1,"equipment":"One nonstick frying pan","steps":["Drain the sweetcorn (100 g canned sweetcorn, drained) well. Scatter it and the cheese (40 g grated) over half of the tortilla (1 large), leaving a 1 cm border.","Fold the empty half over.","Cook in a dry nonstick pan over medium-low heat for 2–3 minutes on each side, until golden and the cheese is melted.","Rest on a board for 1 minute before cutting so the cheese settles. Cut into wedges and serve warm."],"time":10,"title":"3-Ingredient Sweetcorn Quesadilla"},{"id":156,"need":["banana","oats","eggs"],"amounts":{"banana":"1 large ripe","oats":"40 g","eggs":"2"},"servings":1,"equipment":"Blender or fork, plus a good nonstick pan","steps":["Peel the banana (1 large ripe). Blend it with the oats (40 g) and eggs (2) for 30–45 seconds to make a thick batter. Alternatively, mash the banana thoroughly and mix with the eggs and very finely crushed oats.","Let stand for 3 minutes so the oats can soften.","Warm a good nonstick pan over medium-low heat. Spoon in 2 tablespoons batter for each pancake, leaving space for turning.","Cook for 2–3 minutes per side, turning gently, until golden and fully set in the middle. Serve warm."],"time":15,"title":"3-Ingredient Banana Pancakes"},{"id":157,"need":["oats","milk","banana","peanutbutter"],"amounts":{"oats":"50 g","milk":"200–250 ml","banana":"1","peanutbutter":"1 tbsp"},"servings":1,"equipment":"Microwave and a large deep bowl","steps":["Put the oats (50 g) and milk (200–250 ml) in a large, deep microwave-safe bowl, no more than half-filling it so the porridge has room to bubble.","Microwave on high in 1-minute bursts, stirring between bursts, until thick and the oats are soft, usually 2–4 minutes depending on your microwave.","Stir in half the banana (1), mashed, and leave to stand for 1 minute.","Top with the remaining banana slices and swirl in the peanut butter (1 tbsp)."],"time":7,"title":"Peanut Butter Banana Porridge"},{"id":158,"need":["bread","cottagecheese","cucumber","oliveoil"],"amounts":{"bread":"2 thick slices","cottagecheese":"150 g","cucumber":"⅓, thinly sliced","oliveoil":"1 tsp"},"servings":1,"equipment":"Toaster","steps":["Toast the bread (2 thick slices) for 2–3 minutes until golden and crisp. Wash the cucumber (⅓, thinly sliced) and slice it thinly.","Divide the cottage cheese (150 g) between the warm toast slices and spread gently with the back of a spoon.","Arrange the cucumber slices on top.","Drizzle lightly with olive oil (1 tsp) and eat straight away."],"time":5,"title":"Cottage Cheese Cucumber Toast"},{"id":159,"need":["tuna","beans","tomato","oliveoil","lemon"],"amounts":{"tuna":"1 small tin, drained","beans":"½ a 400 g tin of cooked beans, drained and rinsed","tomato":"1 large, diced","oliveoil":"2 tsp","lemon":"½"},"servings":1,"equipment":"One bowl","steps":["Drain the tuna (1 small tin, drained) thoroughly. Drain and rinse the cooked canned beans (½ a 400 g tin of cooked beans, drained and rinsed). Wash and dice the tomato (1 large, diced) into 1 cm pieces.","Put them in a bowl with the diced tomato.","Add the olive oil (2 tsp) and lemon juice (½) and fold gently for about 20 seconds, leaving the tuna in flakes.","Serve immediately, or chill until ready to eat."],"time":10,"title":"Tuna & Bean Lunch Bowl"},{"id":160,"need":["tortilla","eggs","beans","cheese","butter"],"amounts":{"tortilla":"1 large","eggs":"2","beans":"100 g cooked canned beans, drained","cheese":"25 g grated","butter":"5 g"},"servings":1,"equipment":"One nonstick frying pan","steps":["Drain and rinse the beans (100 g cooked canned beans, drained). Warm them in a microwave-safe bowl with 1 tablespoon water for 1–2 minutes, stirring halfway, until piping hot. Beat the eggs (2) and melt the butter (5 g) in a nonstick pan over medium-low heat.","Add the beaten eggs and stir gently for 2–3 minutes. Fold in the hot beans and continue until the eggs are fully set and everything is hot.","Spoon onto the tortilla (1 large) and scatter over the cheese (25 g grated).","Fold in the sides and roll up. Place seam-side down in the same pan for a minute, then turn briefly to warm the other side.","Cut in half and serve."],"time":12,"title":"Egg & Bean Breakfast Wrap"},{"id":161,"need":["bread","eggs","pesto"],"amounts":{"bread":"2 slices","eggs":"2","pesto":"1 tbsp"},"servings":1,"equipment":"Nonstick frying pan and toaster","steps":["Toast the bread (2 slices) for 2–3 minutes until crisp. Warm the pesto (1 tbsp) in a nonstick pan over medium-low heat for 20–30 seconds; do not let it burn.","Crack the eggs (2) into the pesto. Cover and cook gently for about 3–5 minutes until both whites and yolks are set. Lower the heat if the pesto starts browning.","Lift the eggs and pesto onto the toast and eat warm."],"time":8,"title":"Pesto Eggs on Toast"},{"id":162,"need":["flour","greekyogurt","bakingpowder"],"amounts":{"flour":"100 g, plus a little for dusting","greekyogurt":"150 g, divided","bakingpowder":"½ tsp"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Mix the flour (100 g, plus a little for dusting) and baking powder (½ tsp) in a bowl. Set out Greek yogurt (150 g, divided), using 100 g in the dough and reserving 50 g for dipping. Stir the 100 g portion into the flour to make a soft dough, adding water 1 teaspoon at a time only if dry.","Knead on a lightly floured surface for about 30 seconds, then divide into two equal pieces. Roll each into a round about 5 mm thick.","Cook in a dry nonstick pan over medium heat for 3–4 minutes per side, until golden in spots and cooked through. Lower the heat if they brown too quickly.","Serve warm with the remaining 50 g yogurt for dipping."],"time":25,"title":"3-Ingredient Yogurt Flatbreads"},{"id":163,"need":["noodles","eggs","frozenpeas","soyauce"],"amounts":{"noodles":"75 g dried","eggs":"2, beaten","frozenpeas":"100 g","soyauce":"1–2 tsp"},"servings":1,"equipment":"One saucepan","steps":["Beat the eggs (2, beaten) in a cup. Bring 500 ml water to a gentle simmer in a saucepan. Add the noodles (75 g dried) and cook for the time on their packet, usually 3–8 minutes.","Add the frozen peas (100 g) early enough to receive their full packet cooking time, usually 3–5 minutes, and check they are piping hot before adding the egg.","Lower to a gentle simmer. Slowly pour in the beaten eggs while stirring, then simmer for 1–2 minutes until the egg is fully cooked.","Stir in the soy sauce (1–2 tsp), starting with 1 teaspoon, and serve."],"time":15,"title":"Pea & Egg Drop Noodle Soup"},{"id":164,"need":["potato","tomatosauce","mozzarella"],"amounts":{"potato":"1 large, 250–300 g","tomatosauce":"3 tbsp","mozzarella":"60 g, torn"},"servings":1,"equipment":"Microwave, oven grill, and oven-safe dish","steps":["Scrub the potato (1 large, 250–300 g), prick it with a fork, and microwave on a microwave-safe plate for 5 minutes. Turn and cook for 3–5 minutes more, then in short bursts until soft throughout.","Split the potato, fluff the middle, and spoon in the tomato sauce (3 tbsp). Top with mozzarella (60 g, torn).","Heat the oven grill to medium-high. Transfer the filled potato to an oven-safe dish and grill for 3–5 minutes, watching closely, until the mozzarella bubbles and the sauce is hot. Rest for 1 minute before eating."],"time":20,"title":"3-Ingredient Pizza Potato"},{"id":165,"need":["bread","chickpeas","mayo","pickles"],"amounts":{"bread":"2 large slices","chickpeas":"150 g canned, drained and rinsed","mayo":"1 tbsp","pickles":"2 small, chopped"},"servings":1,"equipment":"Bowl and fork","steps":["Drain and rinse the chickpeas (150 g canned, drained and rinsed), then pat dry briefly. Mash in a bowl with a fork for 1–2 minutes, leaving a few chunky pieces.","Finely chop the pickles (2 small, chopped) and stir into the chickpeas with the mayo (1 tbsp) until evenly coated.","Pile the filling onto one bread (2 large slices) slice and close with the other. Cut in half and serve. If you prefer crunch, toast the bread for 2–3 minutes before filling."],"time":10,"title":"Chickpea Pickle Crunch Sandwich"},{"id":166,"need":["couscous","frozenpeas","feta","lemon"],"amounts":{"couscous":"75 g dry, preferably wholewheat","frozenpeas":"100 g","feta":"50 g, crumbled","lemon":"½, juiced"},"servings":1,"equipment":"Saucepan and heatproof bowl","steps":["Cook the frozen peas (100 g) in boiling water for their full packet time, usually 3–5 minutes, until piping hot. Drain.","Put the couscous (75 g dry, preferably wholewheat) in a heatproof bowl. Add boiling water in the ratio stated on the packet, often equal volumes. Cover with a plate for 5–10 minutes or the packet time.","Fluff the couscous with a fork, then fold in the peas, crumbled feta (50 g, crumbled), and lemon juice (½, juiced). Serve warm or refrigerate promptly for later."],"time":12,"title":"Lemon, Pea & Feta Couscous"},{"id":167,"need":["cabbage","eggs","flour","soyauce","oliveoil"],"amounts":{"cabbage":"150 g, very finely shredded","eggs":"2","flour":"2 tbsp","soyauce":"1 tsp","oliveoil":"1 tsp"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Very finely shred the cabbage (150 g, very finely shredded), removing the hard central core. Beat the eggs (2) with the flour (2 tbsp) and soy sauce (1 tsp) until no flour lumps remain, then fold in the cabbage.","Heat the oil (1 tsp) in a small nonstick pan over medium-low heat. Add the mixture and press it into an even pancake about 1 cm thick.","Cover and cook for 5–6 minutes until the bottom is golden. Slide onto a plate, invert into the pan, and cook another 4–5 minutes until set throughout.","Cut into wedges and serve hot."],"time":18,"title":"Crispy Cabbage Egg Pancake"},{"id":168,"need":["tofu","rice","soyauce","honey","oliveoil"],"amounts":{"tofu":"180 g firm, patted dry and cubed","rice":"75 g dry","soyauce":"2 tsp","honey":"2 tsp","oliveoil":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Pat the tofu (180 g firm, patted dry and cubed) dry and cut into 2 cm cubes. Heat the olive oil (1 tsp) in a nonstick pan over medium heat. Cook the tofu for 8–10 minutes, turning every 2 minutes, until golden on several sides.","Mix the soy sauce (2 tsp) and honey (2 tsp) with 1 tablespoon water. Pour over the tofu and stir for 1–2 minutes until glossy.","Serve over the hot rice."],"time":25,"title":"Sticky Honey-Soy Tofu Rice"},{"id":169,"need":["beans","cannedtomatoes","butter","garlic"],"amounts":{"beans":"1 small tin white beans, about 240 g drained, rinsed","cannedtomatoes":"200 g","butter":"10 g","garlic":"1 clove, finely chopped"},"servings":1,"equipment":"One saucepan","steps":["Peel and finely chop the garlic (1 clove, finely chopped). Melt the butter (10 g) over medium-low heat, then stir in the garlic for 30 seconds without letting it brown.","Add the tomatoes (200 g) and simmer for 5 minutes, stirring occasionally.","Add the beans (1 small tin white beans, about 240 g drained, rinsed) and simmer another 5 minutes until piping hot.","Mash about a quarter of the beans against the side of the pan to thicken the sauce. Simmer for 1 more minute, then serve in a bowl."],"time":15,"title":"Garlicky Tomato Butter Beans"},{"id":170,"need":["bread","apple","cheese"],"amounts":{"bread":"2 slices, preferably wholegrain","apple":"1 small, thinly sliced","cheese":"50 g cheddar, grated"},"servings":1,"equipment":"Toaster and oven grill","steps":["Wash the apple (1 small, thinly sliced), remove its core, and slice about 2–3 mm thick. Lightly toast the bread (2 slices, preferably wholegrain) for 1–2 minutes and put on a grill-safe tray.","Layer on the apple and cheese (50 g cheddar, grated).","Grill under medium-high heat for 3–5 minutes, watching closely, until the cheese is melted and golden. Let cool for 1 minute before eating."],"time":10,"title":"Apple & Cheddar Toasts"},{"id":171,"need":["bellpepper","eggs","cannedtomatoes","oliveoil"],"amounts":{"bellpepper":"1, thinly sliced","eggs":"2","cannedtomatoes":"200 g","oliveoil":"1 tsp"},"servings":1,"equipment":"Small frying pan with lid","steps":["Remove the pepper (1, thinly sliced) stalk and seeds and cut into thin strips. Heat the olive oil (1 tsp) over medium heat, add the pepper, and cook for 5–6 minutes until softened.","Add the tomatoes (200 g) and simmer for 5 minutes, adding a splash of water if very thick.","Make two wells and crack in the eggs (2). Cover and cook gently for 5–7 minutes, until both whites and yolks are set."],"time":20,"title":"Sweet Pepper & Tomato Eggs"},{"id":172,"need":["beans","cheese","milk","butter"],"amounts":{"beans":"1 small tin white beans, about 240 g drained, rinsed","cheese":"35 g, grated","milk":"3 tbsp","butter":"1 tsp"},"servings":1,"equipment":"Saucepan and fork or potato masher","steps":["Put the beans (1 small tin white beans, about 240 g drained, rinsed), milk (3 tbsp), and butter (1 tsp) in a saucepan over low-medium heat.","Warm for 4–5 minutes, stirring, until piping hot.","Mash the beans roughly with a fork or potato masher, leaving some whole beans. Stir in the cheese (35 g, grated) for 30–60 seconds until melted. Add water a tablespoon at a time if needed for a softer mash."],"time":10,"title":"Creamy Cheesy White Bean Mash"},{"id":173,"need":["oats","eggs","cheese","frozenpeas"],"amounts":{"oats":"60 g","eggs":"1","cheese":"25 g, grated","frozenpeas":"80 g"},"servings":1,"equipment":"One saucepan","steps":["Put the oats (60 g) and peas (80 g) in a saucepan with 250 ml water. Simmer for 5–7 minutes, stirring often, until the peas are piping hot and the oats are creamy.","Beat the egg (1) in a cup. Reduce the heat to low and stir it steadily into the hot oats so it mixes in rather than forming large lumps.","Cook for another 2–3 minutes, stirring until the egg is fully cooked. Add water if needed, then stir in the cheese (25 g, grated)."],"time":12,"title":"Cheesy Pea & Egg Savory Oats"},{"id":174,"need":["bread","eggs","milk","peanutbutter","jam"],"amounts":{"bread":"2 slices","eggs":"1","milk":"2 tbsp","peanutbutter":"1 tbsp","jam":"1 tbsp"},"servings":1,"equipment":"Shallow bowl and nonstick frying pan","steps":["Spread one bread (2 slices) slice with peanut butter (1 tbsp) and the other with jam (1 tbsp). Press together into a sandwich.","Beat the egg (1) and milk (2 tbsp) in a shallow bowl for 20 seconds. Dip both sides of the sandwich for 5–10 seconds per side, letting excess mixture drip off.","Cook in a good nonstick pan over medium-low heat for 3–4 minutes per side, until golden and the egg coating is fully cooked.","Rest for a minute, then cut in half."],"time":15,"title":"Peanut Butter & Jam French Toast"},{"id":175,"need":["banana","oats"],"amounts":{"banana":"1 large very ripe","oats":"60 g"},"servings":1,"equipment":"Bowl, fork, and baking tray","steps":["Heat the oven to 180°C (160°C fan) and line a small tray with baking paper.","Mash the banana (1 large very ripe) thoroughly, then stir in the oats (60 g). Leave for 5 minutes to thicken.","Divide the mixture into four equal portions and flatten on the lined tray to about 1 cm thick. Leave 2 cm between them; these soft cookies will not spread much.","Bake for 15–18 minutes until firm and lightly golden at the edges. Cool on the tray for 5 minutes before eating."],"time":30,"title":"2-Ingredient Banana Oat Cookies"},{"id":176,"need":["banana","cocoapowder"],"amounts":{"banana":"2 ripe, peeled and sliced","cocoapowder":"1 tbsp unsweetened"},"servings":1,"equipment":"Food processor or strong blender","steps":["Peel and slice the bananas (2 ripe, peeled and sliced). Spread in one layer on a lined freezer-safe tray and freeze for at least 4 hours until solid. The 10-minute time is hands-on preparation.","Let the frozen banana stand at room temperature for 5 minutes. Put in a food processor or strong blender with the cocoa (1 tbsp unsweetened).","Blend in short bursts for 1–2 minutes, stopping to scrape down the sides, until thick and creamy. Add water 1 teaspoon at a time only if the blades need help; too much will make it runny.","Serve immediately for a soft-serve texture."],"time":10,"title":"2-Ingredient Chocolate Banana Soft Serve","wait":"4 hr freeze","waitMinutes":240},{"id":177,"need":["lentils","spinach","cannedtomatoes","greekyogurt"],"amounts":{"lentils":"1 small tin cooked lentils, about 240 g drained, rinsed","spinach":"80 g","cannedtomatoes":"200 g","greekyogurt":"3 tbsp"},"servings":1,"equipment":"One saucepan","steps":["Drain and rinse the cooked canned lentils (1 small tin cooked lentils, about 240 g drained, rinsed). Put in a saucepan with the canned tomatoes (200 g) and 2 tablespoons water. Simmer over medium-low heat for 7–8 minutes, stirring occasionally.","Stir in the spinach (80 g) and cook for 2–3 minutes until wilted and everything is piping hot.","Take off the heat and leave for 1 minute so the yogurt (3 tbsp) is less likely to split. Swirl in the yogurt and serve; do not boil after adding it."],"time":15,"title":"Creamy Spinach & Lentil Bowl"},{"id":178,"need":["sweetpotato","blackbeans","salsa","greekyogurt"],"amounts":{"sweetpotato":"1 medium-large, 250–300 g","blackbeans":"150 g canned, drained and rinsed","salsa":"3 tbsp","greekyogurt":"3 tbsp"},"servings":1,"equipment":"Microwave, plate, and bowl","steps":["Scrub the sweet potato (1 medium-large, 250–300 g) and prick it several times with a fork. Microwave on a microwave-safe plate for 5 minutes, turn, then cook for 3–5 minutes more and in 1-minute bursts until soft throughout.","Mix the beans (150 g canned, drained and rinsed) and salsa (3 tbsp) in a microwave-safe bowl. Cover loosely and microwave in 1-minute bursts, stirring until piping hot.","Split the potato, fluff the inside, and fill with the bean mixture.","Spoon the yogurt (3 tbsp) on top and serve."],"time":20,"title":"Black Bean & Salsa Sweet Potato"},{"id":179,"need":["lentils","carrot","feta","oliveoil","lemon"],"amounts":{"lentils":"1 small tin cooked lentils, about 240 g drained, rinsed","carrot":"2 medium, thinly sliced","feta":"40 g, crumbled","oliveoil":"1 tsp","lemon":"½, juiced"},"servings":1,"equipment":"One frying pan with lid","steps":["Peel and slice the carrots (2 medium, thinly sliced) into thin 3–5 mm rounds. Heat the olive oil (1 tsp) over medium heat, add the carrots and 2 tablespoons water, then cover and cook for 7–9 minutes until tender. Add water if the pan dries out.","Remove the lid and stir in the lentils (1 small tin cooked lentils, about 240 g drained, rinsed). Heat for 3–4 minutes until piping hot.","Take off the heat and toss with lemon juice (½, juiced). Top with feta (40 g, crumbled) and eat warm."],"time":20,"title":"Warm Carrot, Lentil & Feta Salad"},{"id":180,"need":["noodles","tofu","edamame","soyauce","sesameoil"],"amounts":{"noodles":"75 g dry, preferably wholewheat","tofu":"150 g firm, cubed","edamame":"100 g shelled frozen","soyauce":"2 tsp","sesameoil":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Bring about 1 litre water to a boil. Add the noodles (75 g dry, preferably wholewheat) and shelled frozen edamame (100 g shelled frozen) at the right times for each to get its full packet cooking time. Reserve 60 ml cooking water, then drain.","Meanwhile, pat the tofu (150 g firm, cubed) dry and cut into 2 cm cubes. Heat the sesame oil (1 tsp) over medium heat in a nonstick pan. Cook the tofu for 6–8 minutes, turning regularly, until lightly golden.","Add the drained noodles, edamame, soy sauce (2 tsp), and 2 tablespoons water.","Toss over the heat for 1–2 minutes until hot throughout."],"time":18,"title":"Sesame Tofu & Edamame Noodles"},{"id":181,"need":["rice","eggs","mixedveg","soyauce"],"amounts":{"rice":"75 g dry","eggs":"2, beaten","mixedveg":"150 g frozen","soyauce":"1–2 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Put the rice (75 g dry) in a saucepan with water according to its packet and simmer for the packet time, usually 10–15 minutes for white rice. Cook the frozen mixed vegetables (150 g frozen) in the same pan for their full packet time, adding them early enough to finish with the rice. Drain any excess water.","Beat the eggs (2, beaten) in a cup. Tip the freshly cooked rice and vegetables into a good nonstick pan with 2 tablespoons water over medium heat. Push to one side and pour the eggs into the clear part.","Stir the eggs for 1–2 minutes until fully set, then mix everything together. Stir in the soy sauce (1–2 tsp) and toss for 1 minute until steaming hot. Serve immediately."],"time":25,"title":"Freezer Veg Egg Rice"},{"id":182,"need":["instantnoodles","eggs","mixedveg"],"amounts":{"instantnoodles":"1 single-serving packet with seasoning","eggs":"2, beaten","mixedveg":"150 g frozen"},"servings":1,"equipment":"One saucepan","steps":["Bring 450 ml water to a simmer. Add the frozen vegetables (150 g frozen) and cook for the time on their packet.","Add the instant noodle block (1 single-serving packet with seasoning) early enough to receive its full packet cooking time, usually 3–5 minutes. Stir in half the included seasoning sachet, breaking up the noodles gently as they soften.","Pour in the beaten eggs (2, beaten) slowly while stirring. Simmer for 1–2 minutes until the egg is fully cooked. Add water if needed, then serve."],"time":10,"title":"Easy Egg & Veg Noodle Bowl"},{"id":183,"need":["couscous","chickpeas","mixedveg","stockcubes"],"amounts":{"couscous":"75 g dry, preferably wholewheat","chickpeas":"150 g canned, drained and rinsed","mixedveg":"150 g frozen","stockcubes":"¼ reduced-salt cube"},"servings":1,"equipment":"Saucepan and heatproof bowl","steps":["Cook the vegetables (150 g frozen) in boiling water according to the packet. Add the chickpeas (150 g canned, drained and rinsed) for the last 3 minutes to heat through, then drain.","Put the couscous (75 g dry, preferably wholewheat) in a heatproof bowl. Dissolve the quarter stock cube (¼ reduced-salt cube) in the amount of boiling water specified on the couscous packet, often equal volumes. Pour over, cover, and leave for 5–10 minutes or the packet time.","Fluff with a fork and fold in the hot chickpeas and vegetables."],"time":15,"title":"Chickpea & Veg Couscous"},{"id":184,"need":["rice","frozenpeas","stockcubes","parmesan"],"amounts":{"rice":"75 g dry white rice","frozenpeas":"120 g","stockcubes":"¼ reduced-salt cube","parmesan":"25 g, finely grated"},"servings":1,"equipment":"One saucepan with lid","steps":["Dissolve the quarter stock cube (¼ reduced-salt cube) in the water specified for the rice (75 g dry white rice) on its packet, usually about 150 ml for 75 g dry white rice. Keep a little extra hot water ready.","Add the rice, bring to a gentle boil, cover, and cook on low heat for the packet time, usually 10–15 minutes. Add the peas (120 g) early enough for their full packet cooking time, topping up with a splash of water if needed.","When the rice is tender and peas are piping hot, take off the heat. Stir in the parmesan (25 g, finely grated) and a splash of hot water for a creamy finish."],"time":25,"title":"One-Pot Cheesy Pea Rice"},{"id":185,"need":["cannedtomatoes","beans","pasta","stockcubes"],"amounts":{"cannedtomatoes":"200 g","beans":"150 g canned, drained and rinsed","pasta":"60 g dry, small shapes","stockcubes":"¼ reduced-salt cube"},"servings":1,"equipment":"One saucepan","steps":["Put the tomatoes (200 g), 350 ml water, and stock cube (¼ reduced-salt cube) in a saucepan and bring to a simmer.","Add the dry pasta (60 g dry, small shapes) and simmer for its packet cooking time, usually 8–12 minutes, stirring every few minutes so it does not stick. Add hot water in small splashes if the soup becomes too thick.","Stir in the beans (150 g canned, drained and rinsed) for the final 4–5 minutes and cook until piping hot. Serve when the pasta is tender."],"time":25,"title":"Tomato Bean & Pasta Soup"},{"id":186,"need":["noodles","tomatopaste","eggs","oliveoil"],"amounts":{"noodles":"75 g dry","tomatopaste":"1 tbsp","eggs":"2, beaten","oliveoil":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Cook the noodles (75 g dry) in boiling water for their packet time, usually 3–8 minutes. Reserve 60 ml cooking water, then drain.","Heat the oil (1 tsp) over medium-low heat. Stir in the tomato paste (1 tbsp) for 1 minute, then add 3 tablespoons cooking water.","Beat the eggs (2, beaten) in a cup. Push the sauce aside, pour the eggs into the clear part of the pan, and stir over medium-low heat for 1–2 minutes until fully set.","Add the noodles and toss for 1 minute until hot and coated. Add reserved cooking water 1 tablespoon at a time if needed."],"time":15,"title":"Tomato & Egg Noodles"},{"id":187,"need":["tortilla","fishfingers","lettuce","mayo"],"amounts":{"tortilla":"1 large","fishfingers":"4 frozen","lettuce":"2 large leaves, shredded","mayo":"1 tbsp"},"servings":1,"equipment":"Oven and baking tray","steps":["Heat the oven to the temperature on the fish finger packet. Bake the fish fingers (4 frozen) from frozen for their full packet time, often 12–18 minutes, until piping hot and crisp. Let cool for 1 minute before filling the wrap.","Wash, dry, and shred the lettuce (2 large leaves, shredded). Warm the tortilla (1 large) in a dry pan for 15–20 seconds per side, or as its packet directs, until flexible.","Spread on the mayo (1 tbsp), add the lettuce and cooked fish fingers, fold in the sides, and roll up. Cut in half."],"time":25,"title":"Crispy Fish Finger Wrap"},{"id":188,"need":["fishfingers","potato","oliveoil","frozenpeas"],"amounts":{"fishfingers":"4 frozen","potato":"200 g, cut into slim wedges","oliveoil":"1 tsp","frozenpeas":"120 g"},"servings":1,"equipment":"Oven, baking tray, and saucepan","steps":["Heat the oven to the fish finger packet temperature. Scrub the potato (200 g, cut into slim wedges) and cut into slim, even wedges about 1 cm thick at the widest edge. Toss with the olive oil (1 tsp) and spread on a tray in one layer.","Roast the wedges for 30–35 minutes, turning halfway, until tender and golden. Adjust timing for the oven temperature.","Add the fish fingers (4 frozen) on a separate part of the tray for their full packet cooking time, ensuring they are piping hot throughout.","Cook the peas (120 g) according to their packet and serve everything together."],"time":40,"title":"Fish Fingers, Wedges & Peas"},{"id":189,"need":["greenbeans","potato","eggs","greekyogurt","mustard"],"amounts":{"greenbeans":"120 g, trimmed","potato":"200 g, cut into small cubes","eggs":"2","greekyogurt":"3 tbsp","mustard":"1 tsp"},"servings":1,"equipment":"Two saucepans and a bowl","steps":["Scrub and cut the potato (200 g, cut into small cubes) into 1.5 cm cubes. Trim and halve the green beans (120 g, trimmed). Cover the potato with water, bring to a gentle boil, and cook for 10–12 minutes until tender. Add the beans for the last 5–6 minutes. Drain well.","Meanwhile, cook the eggs (2) in gently boiling water for 10–12 minutes until hard-boiled. Cool under cold water, peel, and quarter.","Mix the yogurt (3 tbsp) and mustard (1 tsp) with a teaspoon of water. Toss with the warm potatoes and beans, then add the eggs."],"time":25,"title":"Green Bean, Potato & Egg Salad"},{"id":190,"need":["rice","chicken","greenbeans","soyauce","oliveoil"],"amounts":{"rice":"75 g dry","chicken":"120 g already-cooked chicken, sliced","greenbeans":"150 g, trimmed and halved","soyauce":"2 tsp","oliveoil":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan with lid","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Heat the oil (1 tsp) over medium heat. Add the green beans (150 g, trimmed and halved) and 3 tablespoons water. Cover and cook for 5–6 minutes until tender.","Add the ready-cooked chicken (120 g already-cooked chicken, sliced), soy sauce (2 tsp), and 2 tablespoons water. Cover and heat over medium-low heat for about 3–5 minutes, stirring occasionally, until the chicken reaches 74°C throughout. Add more water if needed.","Serve over the rice immediately."],"time":25,"title":"Chicken & Green Bean Rice"},{"id":191,"need":["bread","tomatopaste","cheese"],"amounts":{"bread":"2 slices","tomatopaste":"1 tbsp","cheese":"50 g, grated"},"servings":1,"equipment":"Toaster and oven grill","steps":["Lightly toast the bread (2 slices) for 1–2 minutes, then place it on a grill-safe tray.","Mix the tomato paste (1 tbsp) with 1 tablespoon water. Spread over the toast and top with cheese (50 g, grated).","Grill over medium-high heat for 3–5 minutes, watching closely, until the cheese bubbles and turns golden. Stand for 1 minute before eating."],"time":12,"title":"3-Ingredient Pizza Toasts"},{"id":192,"need":["bread","tuna","saladmix","mayo"],"amounts":{"bread":"2 large slices, preferably wholegrain","tuna":"1 small tin, drained","saladmix":"1 large handful, washed if needed","mayo":"1 tbsp"},"servings":1,"equipment":"One bowl","steps":["Drain the tuna (1 small tin, drained) thoroughly. Wash and dry the salad leaves (1 large handful, washed if needed) if the packet requires it. Mix the tuna and mayo (1 tbsp) in a bowl for about 20 seconds until coated.","Pile the tuna and salad leaves onto one bread (2 large slices, preferably wholegrain) slice, then close with the other.","Cut in half and serve."],"time":7,"title":"Tuna & Crunchy Salad Sandwich"},{"id":193,"need":["saladmix","eggs","potato","greekyogurt","mustard"],"amounts":{"saladmix":"2 large handfuls, washed if needed","eggs":"2","potato":"200 g, cut into small cubes","greekyogurt":"3 tbsp","mustard":"1 tsp"},"servings":1,"equipment":"Two saucepans and a bowl","steps":["Scrub and cut the potato (200 g, cut into small cubes) into 1.5 cm cubes. Cover with water, bring to a gentle boil, and cook for 10–12 minutes until tender. Drain and let steam dry for 2 minutes.","Meanwhile, hard-boil the eggs (2) for 10–12 minutes, then cool under cold water, peel, and quarter.","Mix the yogurt (3 tbsp) and mustard (1 tsp) with a teaspoon of water. Toss with the potatoes.","Wash and dry the salad leaves (2 large handfuls, washed if needed) if needed. Arrange in a bowl with the dressed potatoes and quartered eggs. Serve while the potatoes are warm, or refrigerate promptly for later."],"time":25,"title":"Easy Egg & Potato Salad Bowl"},{"id":194,"need":["oats","milk","cannedpeaches","cinnamon"],"amounts":{"oats":"50 g","milk":"200 ml","cannedpeaches":"120 g, drained, packed in juice","cinnamon":"¼ tsp"},"servings":1,"equipment":"One saucepan","steps":["Drain the canned peaches (120 g, drained, packed in juice) and cut into bite-size pieces. Put the oats (50 g), milk (200 ml), and cinnamon (¼ tsp) in a saucepan over medium-low heat.","Simmer gently for 5–6 minutes, stirring often, until creamy. Add a splash of water if needed.","Chop the peach slices and stir half into the oats. Spoon the rest on top and serve."],"time":8,"title":"Peach & Cinnamon Porridge"},{"id":195,"need":["greekyogurt","cannedpeaches","oats"],"amounts":{"greekyogurt":"170 g plain unsweetened","cannedpeaches":"120 g, drained, packed in juice","oats":"35 g"},"servings":1,"equipment":"One bowl","steps":["Spoon the yogurt (170 g plain unsweetened) into a bowl and stir in the oats (35 g) for about 20 seconds until evenly mixed.","Chop or slice the peaches (120 g, drained, packed in juice) and arrange on top.","Leave for 3–5 minutes if you prefer softer oats, or eat straight away for more texture."],"time":5,"title":"3-Ingredient Peach Yogurt Bowl"},{"id":196,"need":["rice","mixedveg","beans","stockcubes"],"amounts":{"rice":"50 g dry","mixedveg":"150 g frozen","beans":"150 g canned, drained and rinsed","stockcubes":"¼ reduced-salt cube"},"servings":1,"equipment":"One saucepan","steps":["Put the rice (50 g dry), stock cube (¼ reduced-salt cube), and 500 ml water in a saucepan. Bring to a gentle simmer.","Simmer over low heat for the rice packet time, usually 10–15 minutes for white rice. Add the frozen vegetables (150 g frozen) early enough to receive their full packet cooking time, usually 4–7 minutes; follow their packet if longer.","Add the beans (150 g canned, drained and rinsed) for the final 4–5 minutes and simmer until piping hot. Add water if you prefer more broth.","Serve when the rice and vegetables are tender."],"time":25,"title":"Simple Vegetable Rice Soup"},{"id":197,"need":["frozendumplings","mixedveg","cream","soyauce"],"amounts":{"frozendumplings":"6–8 frozen vegetable dumplings suitable for steaming","mixedveg":"120 g frozen","cream":"3 tbsp","soyauce":"1 tsp"},"servings":1,"equipment":"One nonstick frying pan with lid","steps":["Put the frozen vegetables (120 g frozen) in the pan with 3 tablespoons water. Cover and cook over medium heat for their full packet time, usually 4–7 minutes, until piping hot; use the packet time if longer. Transfer to a bowl.","Steam the vegetable dumplings (6–8 frozen vegetable dumplings suitable for steaming) in the same pan with the lid on, using the amount of water and full steaming time on their packet, often 8–15 minutes. Replenish water as needed so the pan does not boil dry; check the filling is piping hot.","When the dumplings are fully cooked, return the vegetables. Add the cream (3 tbsp), soy sauce (1 tsp), and 2 tablespoons water.","Simmer gently for 1–2 minutes until hot throughout and the sauce lightly coats the dumplings."],"time":25,"title":"Creamy Dumpling Skillet"},{"id":198,"need":["rice","groundbeef","cheese","pickles","ketchup"],"amounts":{"rice":"75 g dry","groundbeef":"125 g lean","cheese":"25 g, grated","pickles":"2 small, sliced","ketchup":"1 tbsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Cook the lean ground beef (125 g lean) in a good nonstick pan over medium heat, breaking it into small crumbles. Cook for about 7–10 minutes until it reaches 71°C in the centre, checked with a food thermometer. Add a splash of water if it sticks.","Spoon the rice into a bowl and top with the hot beef and cheese (25 g, grated).","Add the pickles (2 small, sliced) and ketchup (1 tbsp)."],"time":25,"title":"Cheeseburger Rice Bowl"},{"id":199,"need":["tortilla","chicken","cottagecheese","mozzarella","hothoney"],"amounts":{"tortilla":"1 large","chicken":"100 g already-cooked, finely shredded","cottagecheese":"60 g","mozzarella":"40 g, torn","hothoney":"1 tsp"},"servings":1,"equipment":"Oven and baking tray","steps":["Heat the oven to 200°C (180°C fan). Put the tortilla (1 large) on a baking tray and bake for 2 minutes to firm the base.","Mash or blend the cottage cheese (60 g) for about 30 seconds, then spread thinly over the partly baked tortilla, leaving a 1 cm border. Add the already-cooked chicken (100 g already-cooked, finely shredded) and torn mozzarella (40 g, torn).","Bake for 8–10 minutes until the edges are crisp and the cheese bubbles. Check the chicken reaches 74°C throughout, allowing more time if needed without burning the base.","Drizzle with hot honey (1 tsp) and cut into wedges."],"time":20,"title":"Hot Honey Chicken Tortilla Pizza"},{"id":200,"need":["cottagecheese","tomatosauce","mozzarella","bread"],"amounts":{"cottagecheese":"150 g","tomatosauce":"3 tbsp","mozzarella":"40 g, torn","bread":"2 slices"},"servings":1,"equipment":"Oven, small oven-safe dish, and toaster","steps":["Heat the oven to 200°C (180°C fan). Mash the cottage cheese (150 g) until smoother and spoon into a small oven-safe dish.","Spread the tomato sauce (3 tbsp) over the cottage cheese and add the mozzarella (40 g, torn).","Bake for 10–12 minutes until bubbling and hot throughout.","Toast the bread (2 slices) for 2–3 minutes, then cut into fingers. Let the dip stand for 1 minute and serve with the toast for scooping."],"time":20,"title":"Cottage Cheese Pizza Dip & Toast"},{"id":201,"need":["chickpeas","tortilla","cheese","salsa","oliveoil"],"amounts":{"chickpeas":"150 g canned, drained and rinsed","tortilla":"2 small","cheese":"35 g, grated","salsa":"3 tbsp","oliveoil":"1 tsp"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Drain, rinse, and pat the chickpeas (150 g canned, drained and rinsed) dry. Set out salsa (3 tbsp); mash 1 tablespoon into the chickpeas and reserve the other 2 tablespoons for serving. Add water 1 teaspoon at a time only if the filling is too dry.","Divide the filling between the tortillas (2 small), sprinkle on the cheese (35 g, grated), and fold in half.","Heat the oil (1 tsp) over medium-low heat. Cook the folded tacos for 2–3 minutes per side until crisp, with hot filling and melted cheese.","Serve with the remaining salsa."],"time":15,"title":"Smashed Chickpea Tacos"},{"id":202,"need":["bagel","tomatosauce","cottagecheese","cheese"],"amounts":{"bagel":"1, split","tomatosauce":"2 tbsp","cottagecheese":"80 g","cheese":"30 g, grated"},"servings":1,"equipment":"Toaster and oven grill","steps":["Split the bagel (1, split) and lightly toast the halves for 1–2 minutes. Put cut-side up on a grill-safe tray.","Spread with tomato sauce (2 tbsp), then spoon over the cottage cheese (80 g) and grated cheese (30 g, grated).","Grill over medium-high heat for 3–5 minutes, watching closely, until bubbling, golden, and hot throughout. Let stand for 1 minute before eating."],"time":12,"title":"Cottage Cheese Pizza Bagel"},{"id":203,"need":["tortilla","eggs","spinach","cheese","oliveoil"],"amounts":{"tortilla":"1 large","eggs":"2, beaten","spinach":"1 large handful, roughly chopped","cheese":"30 g, grated","oliveoil":"1 tsp"},"servings":1,"equipment":"One nonstick frying pan","steps":["Wash and roughly chop the spinach (1 large handful, roughly chopped). Beat the eggs (2, beaten) in a bowl. Heat the olive oil (1 tsp) over medium-low heat and stir in the spinach for 1–2 minutes until wilted.","Pour in the eggs and spread evenly. Lay the tortilla (1 large) over the top, press gently, and cook for 2–3 minutes until the egg is set underneath. Lower the heat if it browns too fast.","Carefully flip so the tortilla is underneath. Add the cheese (30 g, grated) to one half and fold over.","Cook gently for 1–2 minutes per side until the egg is fully set and cheese melted."],"time":12,"title":"Cheesy Spinach Egg Fold"},{"id":204,"need":["oats","milk","greekyogurt","peanutbutter","jam"],"amounts":{"oats":"50 g","milk":"100 ml","greekyogurt":"80 g plain","peanutbutter":"1 tbsp","jam":"2 tsp"},"servings":1,"equipment":"Jar or lidded bowl","steps":["Measure the oats (50 g), milk (100 ml), and yogurt (80 g plain) into a clean jar or lidded bowl. Stir for 20–30 seconds, scraping the base so no dry oats remain.","Swirl in the peanut butter (1 tbsp) and jam (2 tsp).","Cover and refrigerate for at least 6 hours or overnight. The 5-minute time is hands-on preparation.","Stir in the morning, adding a splash of water if too thick."],"time":5,"title":"PB & Jam Overnight Oats","wait":"6 hr chill","waitMinutes":360},{"id":205,"need":["oats","milk","carrot","greekyogurt","cinnamon"],"amounts":{"oats":"50 g","milk":"120 ml","carrot":"½ medium, finely grated","greekyogurt":"80 g plain","cinnamon":"¼ tsp"},"servings":1,"equipment":"Jar, lid, and grater","steps":["Peel and finely grate the carrot (½ medium, finely grated). Measure Greek yogurt (80 g plain); stir 40 g into a clean jar with the oats (50 g), milk (120 ml), carrot, and cinnamon (¼ tsp), and reserve 40 g in the fridge for topping. Stir for 20–30 seconds, scraping the base.","Cover and refrigerate overnight, at least 6 hours. The 8-minute time is hands-on preparation.","In the morning, stir the oats, adding water 1 tablespoon at a time if too thick. Top with the reserved 40 g yogurt and serve."],"time":8,"title":"Carrot Cake Overnight Oats","wait":"6 hr chill","waitMinutes":360},{"id":206,"need":["rice","tuna","cucumber","mayo","soyauce"],"amounts":{"rice":"75 g dry","tuna":"1 small tin, drained","cucumber":"¼, diced","mayo":"1 tbsp","soyauce":"1 tsp"},"servings":1,"equipment":"Saucepan and bowl","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Drain the tuna (1 small tin, drained) well and mix with the mayo (1 tbsp) and soy sauce (1 tsp) for about 20 seconds. Wash the cucumber (¼, diced) and dice into 1 cm pieces.","Top the rice with the tuna mixture and diced cucumber. Serve straight away."],"time":20,"title":"Tuna Sushi-Style Rice Bowl"},{"id":207,"need":["pasta","onion","butter","stockcubes","cheese"],"amounts":{"pasta":"90 g dry","onion":"1 medium, thinly sliced","butter":"10 g","stockcubes":"¼ reduced-salt cube","cheese":"35 g, grated"},"servings":1,"equipment":"One saucepan with lid","steps":["Peel and thinly slice the onion (1 medium, thinly sliced). Melt the butter (10 g) in a saucepan over medium-low heat. Cook the onion for 12–15 minutes, stirring every few minutes, until soft and golden; add a splash of water if it sticks.","Add the pasta (90 g dry), stock cube (¼ reduced-salt cube), and 300 ml water. Bring to a gentle simmer.","Simmer gently for the pasta packet time, usually 8–12 minutes, stirring every minute so it does not stick. Add hot water 1 tablespoon at a time until the pasta is tender and the sauce coats it.","Take off the heat and stir in the cheese (35 g, grated)."],"time":35,"title":"One-Pot Onion & Cheese Pasta"},{"id":208,"need":["halloumi","rice","cucumber","hothoney"],"amounts":{"halloumi":"100 g, sliced","rice":"75 g dry","cucumber":"¼, diced","hothoney":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Pat the halloumi (100 g, sliced) dry and cut into 1 cm slices. Cook in a good dry nonstick pan over medium heat for 1–2 minutes per side until golden. Wash and dice the cucumber (¼, diced) while the cheese cooks.","Spoon the rice into a bowl and add the halloumi and cucumber.","Drizzle with hot honey (1 tsp) and serve warm."],"time":25,"title":"Hot Honey Halloumi Rice Bowl"},{"id":209,"need":["cottagecheese","cocoapowder","honey"],"amounts":{"cottagecheese":"150 g","cocoapowder":"1 tbsp unsweetened","honey":"2 tsp"},"servings":1,"equipment":"Blender and small bowl","steps":["Put the cottage cheese (150 g), cocoa (1 tbsp unsweetened), and honey (2 tsp) in a blender. Blend for 45–60 seconds, scrape down the sides, then blend again until completely smooth with no visible curds.","Add water a teaspoon at a time only if the blender needs help.","Spoon into a bowl and eat immediately, or cover and refrigerate for 30 minutes for a firmer texture. The 5-minute time excludes optional chilling."],"time":5,"title":"3-Ingredient Chocolate Cottage Mousse"},{"id":210,"need":["greekyogurt","strawberry","chocolatechips"],"amounts":{"greekyogurt":"170 g plain","strawberry":"80 g, thinly sliced","chocolatechips":"15 g"},"servings":1,"equipment":"Small freezer-safe tray and baking paper","steps":["Wash and hull the strawberries (80 g, thinly sliced), then slice about 3 mm thick. Line a small freezer-safe tray with baking paper and spread the yogurt (170 g plain) about 1 cm thick.","Press on the strawberry slices and scatter over the chocolate chips (15 g).","Freeze for at least 4 hours until solid. The 10-minute time is hands-on preparation.","Break into pieces and let stand for 2 minutes before eating. Keep any remaining pieces in the freezer."],"time":10,"title":"Strawberry Chocolate Yogurt Bark","wait":"4 hr freeze","waitMinutes":240},{"id":211,"need":["banana","eggs","oats","bakingpowder","cinnamon"],"amounts":{"banana":"1 small very ripe","eggs":"1","oats":"35 g, finely blended or crushed","bakingpowder":"¼ tsp","cinnamon":"¼ tsp"},"servings":1,"equipment":"Large microwave-safe mug and fork","steps":["Use a microwave-safe mug of at least 350 ml capacity so the mixture has room to rise. Peel and thoroughly mash the banana (1 small very ripe) in the mug until mostly smooth.","Beat in the egg (1) with a fork, then stir in the finely ground oats (35 g, finely blended or crushed), baking powder (¼ tsp), and cinnamon (¼ tsp). Scrape the bottom corners so no dry mixture remains.","Microwave on high for 90 seconds, then in 15–20 second bursts until risen and fully set in the centre with no wet egg mixture. Timing varies by microwave.","Let stand for 2 minutes before eating; the mug will be hot."],"time":8,"title":"Banana Bread Breakfast Mug"},{"id":212,"need":["bread","greekyogurt","eggs","strawberry","honey"],"amounts":{"bread":"2 thick slices","greekyogurt":"3 tbsp plain","eggs":"1","strawberry":"60 g, sliced","honey":"1 tsp"},"servings":1,"equipment":"Oven, tray, and bowl","steps":["Heat the oven to 180°C (160°C fan) and line a tray with baking paper.","Press the centre of each bread (2 thick slices) slice down with a spoon to make a shallow well, leaving the crust intact.","Beat the yogurt (3 tbsp plain), egg (1), and honey (1 tsp) for 30 seconds until smooth. Divide between the bread wells, keeping it inside the crusts, and add thinly sliced washed strawberries (60 g, sliced).","Bake for 12–16 minutes until the custard is fully set with no wet egg mixture. Let cool slightly before eating."],"time":25,"title":"Berry Yogurt Custard Toast"},{"id":213,"need":["tortellini","frozenspinach","creamcheese"],"amounts":{"tortellini":"200 g chilled cheese tortellini","frozenspinach":"100 g","creamcheese":"40 g"},"servings":1,"equipment":"One saucepan","steps":["Put the frozen spinach (100 g) in a saucepan with 3 tablespoons water. Cover and cook over medium-low heat for its full packet time, usually 4–7 minutes, until piping hot; follow the packet if longer.","Add about 700 ml boiling water, or enough to cover the tortellini (200 g chilled cheese tortellini). Bring back to a gentle simmer, add the pasta, and cook for its packet time, usually 2–5 minutes for chilled tortellini.","Reserve 60 ml cooking water, then drain through a fine colander so you keep the spinach. Return to the pan off the heat and stir in the cream cheese (40 g). Add reserved water 1 tablespoon at a time until creamy."],"time":15,"title":"3-Ingredient Creamy Spinach Tortellini"},{"id":214,"need":["tortellini","kidneybeans","cannedtomatoes","spinach"],"amounts":{"tortellini":"150 g chilled cheese tortellini","kidneybeans":"120 g canned, drained and rinsed","cannedtomatoes":"200 g","spinach":"60 g"},"servings":1,"equipment":"One saucepan","steps":["Simmer the tomatoes (200 g) and 100 ml water in a saucepan for 5 minutes.","Drain and rinse the kidney beans (120 g canned, drained and rinsed). Add them and the chilled tortellini (150 g chilled cheese tortellini) to the simmering sauce. Cook for the full tortellini packet time, usually 2–5 minutes, stirring gently and adding water if the sauce is too thick.","Stir in the spinach (60 g) and cook for another 2 minutes until wilted and everything is piping hot."],"time":18,"title":"Tomato & Bean Tortellini Pot"},{"id":215,"need":["rice","kidneybeans","cannedtomatoes","paprika"],"amounts":{"rice":"75 g dry","kidneybeans":"150 g canned, drained and rinsed","cannedtomatoes":"200 g","paprika":"½ tsp smoked or sweet"},"servings":1,"equipment":"One saucepan with lid","steps":["Put the rice (75 g dry), tomatoes (200 g), paprika (½ tsp smoked or sweet), and 200 ml water in a saucepan. Bring to a gentle simmer.","Cover and simmer over low heat for the rice packet time, usually 10–15 minutes for white rice. Stir every few minutes and add hot water 1 tablespoon at a time if it begins to stick.","Add the kidney beans (150 g canned, drained and rinsed) for the final 5 minutes. Serve when the rice is tender and beans are piping hot."],"time":25,"title":"Smoky Kidney Bean Rice"},{"id":216,"need":["tortilla","kidneybeans","corn","cheese"],"amounts":{"tortilla":"1 large","kidneybeans":"120 g canned, drained and rinsed","corn":"60 g canned, drained","cheese":"35 g, grated"},"servings":1,"equipment":"Bowl and nonstick frying pan","steps":["Drain and rinse the kidney beans (120 g canned, drained and rinsed). Drain the sweetcorn (60 g canned, drained). Mash the beans roughly with a fork and 1 tablespoon water, leaving a little texture.","Spread over half the tortilla (1 large). Add the corn and cheese (35 g, grated), then fold closed.","Cook in a dry nonstick pan over medium-low heat for 3–4 minutes per side, until crisp and the filling is piping hot."],"time":12,"title":"Kidney Bean & Corn Quesadilla"},{"id":217,"need":["noodles","chicken","mixedveg","sweetchili"],"amounts":{"noodles":"75 g dry","chicken":"100 g already-cooked, sliced","mixedveg":"150 g frozen","sweetchili":"1 tbsp"},"servings":1,"equipment":"One saucepan","steps":["Bring about 1 litre water to a boil. Cook the frozen vegetables (150 g frozen) and noodles (75 g dry), adding them at the correct times so each receives its full packet cooking time. Reserve 60 ml water, then drain.","Return to the pan with the cooked chicken (100 g already-cooked, sliced), sweet chili sauce (1 tbsp), and 3 tablespoons water.","Cover and heat over medium-low heat for about 3–5 minutes, stirring, until the chicken reaches 74°C throughout. Add reserved water 1 tablespoon at a time if needed."],"time":20,"title":"Sweet Chili Chicken Noodles"},{"id":218,"need":["rice","tofu","broccoli","sweetchili","oliveoil"],"amounts":{"rice":"75 g dry","tofu":"150 g firm, patted dry and cubed","broccoli":"120 g, small florets","sweetchili":"1 tbsp","oliveoil":"1 tsp"},"servings":1,"equipment":"Saucepan and nonstick frying pan with lid","steps":["Put rice (75 g dry) in a small saucepan. Add the amount of water stated on its packet (usually about 150 ml for 75 g white rice). Bring to the boil, cover, and cook on low heat for the packet time, usually 10–15 minutes, until tender. Rest covered for 5 minutes.","Pat the tofu (150 g firm, patted dry and cubed) dry and cut into 2 cm cubes. Heat the olive oil (1 tsp) in a nonstick frying pan over medium heat. Cook the tofu for 6–8 minutes, turning regularly, until golden, then transfer to a plate.","Add the broccoli (120 g, small florets) and 3 tablespoons water to the pan. Cover and cook for 4–6 minutes until tender.","Return the tofu, add the sweet chili sauce (1 tbsp) and 1 tablespoon water, and toss until hot. Serve over the rice."],"time":25,"title":"Sticky Sweet Chili Tofu Rice"},{"id":219,"need":["selfraisingflour","greekyogurt","tomatosauce","cheese"],"amounts":{"selfraisingflour":"100 g, plus a little for dusting","greekyogurt":"90 g","tomatosauce":"2 tbsp","cheese":"50 g, grated"},"servings":1,"equipment":"Bowl, oven, and baking tray","steps":["Heat the oven to 220°C (200°C fan). Mix the flour (100 g, plus a little for dusting) and yogurt (90 g) into a soft dough, adding a teaspoon of water if dry.","Knead on a lightly floured surface for 30–60 seconds until cohesive. Roll into a thin 18–20 cm round, about 5 mm thick, and put on a lined baking tray.","Bake the plain base for 5 minutes. Spread with tomato sauce (2 tbsp) and add the cheese (50 g, grated).","Bake for another 10–12 minutes until the base is cooked underneath and the cheese is golden."],"time":30,"title":"Easy Yogurt-Dough Pizza"},{"id":220,"need":["selfraisingflour","greekyogurt","frozenspinach","cheese"],"amounts":{"selfraisingflour":"100 g, plus a little for dusting","greekyogurt":"90 g","frozenspinach":"80 g","cheese":"40 g, grated"},"servings":1,"equipment":"Saucepan, bowl, oven, and tray","steps":["Heat the oven to 200°C (180°C fan). Cook the frozen spinach (80 g) according to its packet until piping hot, then let cool for 2–3 minutes. Squeeze firmly in a fine sieve or clean cloth to remove excess water.","Mix the flour (100 g, plus a little for dusting) and yogurt (90 g) into a soft dough. Knead for 30–60 seconds on a floured surface, then roll into a rectangle about 15 × 25 cm and 5 mm thick.","Spread the squeezed spinach over the dough and scatter on the cheese (40 g, grated). Roll tightly from the long side and cut into four equal rounds with a sharp knife.","Put cut-side up on a lined tray and bake for 18–22 minutes, until golden and cooked through."],"time":40,"title":"Cheesy Spinach Pinwheels"},{"id":221,"need":["breadrolls","eggs","mayo","cucumber"],"amounts":{"breadrolls":"1 large","eggs":"2","mayo":"1 tbsp","cucumber":"¼, thinly sliced"},"servings":1,"equipment":"Saucepan and bowl","steps":["Put the eggs (2) in a saucepan and cover with water. Bring to a gentle boil and cook for 10–12 minutes for firm whites and yolks. Cool under cold water, peel, and chop.","Mix the eggs with the mayo (1 tbsp).","Wash and thinly slice the cucumber (¼, thinly sliced). Split the bread roll (1 large), arrange the cucumber inside, and spoon in the egg mixture. Serve immediately."],"time":20,"title":"Classic Egg Mayo Roll"},{"id":222,"need":["breadrolls","chicken","saladmix","greekyogurt","sweetchili"],"amounts":{"breadrolls":"1 large, preferably wholegrain","chicken":"100 g ready-to-eat cooked chicken, chilled","saladmix":"1 large handful, washed if needed","greekyogurt":"2 tbsp","sweetchili":"2 tsp"},"servings":1,"equipment":"One bowl","steps":["Mix the yogurt (2 tbsp) and sweet chili sauce (2 tsp) in a bowl for about 20 seconds until smooth, then fold in the ready-to-eat cooked chicken (100 g ready-to-eat cooked chicken, chilled).","Wash and dry the salad leaves (1 large handful, washed if needed) if needed. Split the bread roll (1 large, preferably wholegrain), add the leaves, and spoon in the dressed chicken.","Serve immediately, using cooked chicken that has been stored according to its pack instructions."],"time":8,"title":"Sweet Chili Chicken Salad Roll"},{"id":223,"need":["digestives","creamcheese","greekyogurt","jam"],"amounts":{"digestives":"2 biscuits","creamcheese":"40 g","greekyogurt":"80 g plain","jam":"2 tsp berry jam"},"servings":1,"equipment":"Small glass, bowl, and spoon","steps":["Crush the biscuits (2 biscuits) with a rolling pin in a bag, or with the base of a glass in a bowl. Reserve a teaspoon of crumbs for the top and put the rest in a small serving glass.","Beat the cream cheese (40 g) and yogurt (80 g plain) for 30–60 seconds until smooth. Set out jam (2 tsp berry jam); swirl 1 teaspoon into the mixture and reserve 1 teaspoon for the top.","Spoon over the crumbs. Add the remaining jam and biscuit crumbs on top.","Eat straight away, or cover and chill for 30 minutes for a firmer texture."],"time":10,"title":"No-Bake Berry Cheesecake Cup"},{"id":224,"need":["digestives","greekyogurt","banana","peanutbutter"],"amounts":{"digestives":"2 biscuits, roughly crushed","greekyogurt":"170 g plain","banana":"1 small, sliced","peanutbutter":"1 tbsp"},"servings":1,"equipment":"One glass or bowl","steps":["Peel and slice the banana (1 small, sliced). Crush the biscuits (2 biscuits, roughly crushed) roughly with the back of a spoon. Measure Greek yogurt (170 g plain); spoon 85 g into a glass or bowl, reserving 85 g for the second layer.","Add half the banana slices and biscuit crumbs, then the remaining 85 g yogurt. Top with the rest of the banana and biscuit crumbs.","Swirl the peanut butter (1 tbsp) over the top and eat straight away."],"time":5,"title":"Banana Biscuit Yogurt Pot"},{"id":225,"need":["oats","milk","greekyogurt","vanilla","frozenberries"],"amounts":{"oats":"50 g","milk":"100 ml","greekyogurt":"80 g plain","vanilla":"¼ tsp","frozenberries":"100 g, prepared according to the packet"},"servings":1,"equipment":"Jar or lidded bowl","steps":["Put the oats (50 g), milk (100 ml), yogurt (80 g plain), and vanilla (¼ tsp) in a clean jar. Stir for 20–30 seconds, scraping the bottom so no dry oats remain. Cover and refrigerate for at least 6 hours or overnight.","Prepare the berries (100 g, prepared according to the packet) according to the packet, including any required heating, then cool and refrigerate separately.","In the morning, stir the oats, loosen with a splash of water if needed, and top with the berries."],"time":10,"title":"Vanilla Berry Overnight Oats","wait":"6 hr chill","waitMinutes":360},{"id":226,"need":["selfraisingflour","milk","sugar","oliveoil","vanilla"],"amounts":{"selfraisingflour":"4 level tbsp, about 35 g","milk":"3 tbsp","sugar":"1 tbsp","oliveoil":"1 tbsp mild-flavoured","vanilla":"¼ tsp"},"servings":1,"equipment":"Large microwave-safe mug and spoon","steps":["Use a microwave-safe mug of at least 350 ml capacity. Stir the flour (4 level tbsp, about 35 g) and sugar (1 tbsp) together, breaking up any flour lumps, and leave plenty of room for the cake to rise.","Mix in the milk (3 tbsp), oil (1 tbsp mild-flavoured), and vanilla (¼ tsp) until smooth, scraping the bottom corners.","Microwave on high for 60 seconds, then in 10–15 second bursts until the top is set and a skewer comes out without wet batter. Timing varies by microwave.","Leave for 2 minutes before eating; the mug will be hot."],"time":7,"title":"Vanilla Mug Sponge"},{"id":227,"need":["frozenspinach","kidneybeans","eggs","cannedtomatoes"],"amounts":{"frozenspinach":"100 g","kidneybeans":"120 g canned, drained and rinsed","eggs":"2","cannedtomatoes":"200 g"},"servings":1,"equipment":"One frying pan with lid","steps":["Put the frozen spinach (100 g) in the pan with 3 tablespoons water. Cover and cook over medium-low heat for its full packet time, usually 4–7 minutes, until piping hot; follow the packet if longer.","Drain and rinse the kidney beans (120 g canned, drained and rinsed). Add to the spinach with the canned tomatoes (200 g) and simmer gently for 5 minutes, adding 1–2 tablespoons water if needed.","Make two wells and crack in the eggs (2). Cover and cook gently until both whites and yolks are fully set, about 5–7 minutes."],"time":20,"title":"Spinach & Bean Skillet Eggs"},{"id":228,"need":["noodles","tofu","peanutbutter","sweetchili","cucumber"],"amounts":{"noodles":"75 g dry","tofu":"150 g firm, cubed","peanutbutter":"1 tbsp","sweetchili":"1 tbsp","cucumber":"¼, cut into sticks"},"servings":1,"equipment":"One saucepan and bowl","steps":["Bring about 1 litre water to a boil and cook the noodles (75 g dry) for their packet time, usually 3–8 minutes. Cut the tofu (150 g firm, cubed) into 2 cm cubes and add for the last 4 minutes, or longer if its packet requires it. Reserve 60 ml cooking water before draining.","Mix the peanut butter (1 tbsp) and sweet chili sauce (1 tbsp) in a bowl with 2 tablespoons hot cooking water.","Drain the noodles and tofu, reserving a little water. Toss with the sauce, loosening as needed.","Wash the cucumber (¼, cut into sticks) and cut into thin sticks. Divide over the hot noodles and tofu and serve straight away."],"time":15,"title":"Sweet Chili Peanut Tofu Noodles"}];
for(const patch of detailedRecipeMethods){const recipe=recipes.find(r=>r.id===patch.id);if(recipe)Object.assign(recipe,patch)}
// END DETAILED RECIPE METHODS











const categoryOrder=['All','Fridge basics','Produce','Protein','Pantry staples','Sauces & extras','Frozen'];
const byId=Object.fromEntries(pantryItems.map(x=>[x.id,x]));
const validZones=new Set(['freezer','top','middle','bottom','drawer','door1','door2','door3']);
const storageKey='fill-my-fridge-v3';
const $=id=>document.getElementById(id);
let recipesRevealed=false,hasSearched=false;
let selected=new Set(),positions={},favorites=new Set(),category='All',foodQuery='',recipeQuery='',filter='all',meal='all',stockedOnly=false,visibleRecipes=12,activeRecipe=null,lastFocus=null,undoState=null,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');selected=new Set((Array.isArray(saved.selected)?saved.selected:[]).filter(id=>Object.hasOwn(byId,id)));favorites=new Set((Array.isArray(saved.favorites)?saved.favorites:[]).filter(id=>recipes.some(r=>r.id===id)));for(const id of selected)positions[id]=validZones.has(saved.positions?.[id])?saved.positions[id]:byId[id].zone}catch(e){}
function save(){try{localStorage.setItem(storageKey,JSON.stringify({selected:[...selected],positions,favorites:[...favorites]}))}catch(e){notify('Your browser could not save these changes. Keep this tab open.')}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notify(message,undo=false){clearTimeout(toastTimer);$('toastText').textContent=message;$('undoClear').hidden=!undo;$('toast').hidden=false;toastTimer=setTimeout(()=>{$('toast').hidden=true},undo?12000:4000)}
function add(id,zone){if(!Object.hasOwn(byId,id))return;const removing=selected.has(id)&&!zone;if(removing){selected.delete(id);delete positions[id]}else{selected.add(id);positions[id]=validZones.has(zone)?zone:(positions[id]||byId[id].zone)}save();render();notify(byId[id].name+(removing?' removed.':' added to your fridge.'))}
function renderBaskets(){const focused=document.activeElement?.dataset;const focusFood=focused?.food,focusCat=focused?.category;const gridScroll=$('basketGrid').scrollTop;$('categories').innerHTML=categoryOrder.map(c=>`<button class="cat ${category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${category===c}">${esc(c)}</button>`).join('');const items=pantryItems.filter(x=>(category==='All'||x.category===category)&&(!stockedOnly||selected.has(x.id))&&(`${x.name} ${x.category}`).toLowerCase().includes(foodQuery));$('ingredientResults').textContent=items.length+' ingredients';$('basketGrid').innerHTML=items.length?items.map(x=>`<button class="food-option ${selected.has(x.id)?'picked':''}" draggable="true" data-food="${x.id}" aria-pressed="${selected.has(x.id)}" aria-label="${esc(x.name)}" title="${selected.has(x.id)?'Remove':'Add'} ${esc(x.name)}"><span class="check" aria-hidden="true">${selected.has(x.id)?'✓':'+'}</span><span class="food-emoji">${doodle(x)}</span><span class="food-label">${esc(x.name)}</span></button>`).join(''):'<div class="no-result">No ingredients found. Try a different search or category.</div>';$('basketGrid').scrollTop=gridScroll;if(focusFood)document.querySelector(`[data-food="${focusFood}"]`)?.focus({preventScroll:true});if(focusCat)[...document.querySelectorAll('[data-category]')].find(b=>b.dataset.category===focusCat)?.focus({preventScroll:true})}
function placed(x){return `<button class="placed" draggable="true" data-placed="${x.id}" aria-label="Remove ${esc(x.name)}" title="Remove ${esc(x.name)} (or drag to move)"><span class="emoji">${doodle(x)}</span><span class="name">${esc(x.name)}</span></button>`}
function renderFridgeNotes(){$('fridgeEmptyNote').hidden=selected.size>0}
function renderFridge(){renderFridgeNotes();const focusId=document.activeElement?.dataset.placed;const zones=Object.fromEntries([...validZones].map(z=>[z,[]]));for(const id of selected)zones[positions[id]||byId[id].zone].push(byId[id]);for(const z of validZones)$('z-'+z).innerHTML=zones[z].length?zones[z].map(placed).join(''):'<div class="zone-empty" aria-hidden="true">＋</div>';$('tray').innerHTML=selected.size?[...selected].map(id=>placed(byId[id])).join(''):'<div class="zone-empty">A fresh start. Choose your first ingredient.</div>';$('basketCount').textContent=selected.size+' selected';$('foodTotal').textContent=selected.size;$('scoreFoods').textContent=selected.size;$('scoreReady').textContent=recipes.filter(r=>r.need.every(id=>selected.has(id))).length;if(focusId){const next=document.querySelector(`[data-placed="${focusId}"]`);(next||$('clear')).focus({preventScroll:true})}}
function rank(){return recipes.map(r=>({...r,have:r.need.filter(i=>selected.has(i)).length,missing:r.need.filter(i=>!selected.has(i))})).filter(r=>r.have>=2&&(meal==='all'||r.type===meal)&&(filter!=='ready'||!r.missing.length)&&(filter!=='almost'||r.missing.length===1)&&(filter!=='quick'||(r.time+(r.waitMinutes||0))<=20)&&(filter!=='student'||r.student===true)&&(filter!=='balanced'||r.balanced===true)&&(filter!=='favorites'||favorites.has(r.id))&&(`${r.title} ${r.need.map(id=>byId[id].name).join(' ')}`).toLowerCase().includes(recipeQuery)).sort((a,b)=>b.have/b.need.length-a.have/a.need.length||a.missing.length-b.missing.length||a.time-b.time)}
function renderRecipes(){$('studentHint').hidden=filter!=='student';if(!recipesRevealed){$('recipeGrid').innerHTML='';return;}const focusedFav=document.activeElement?.dataset.fav;const list=rank();$('recipeCount').textContent=list.length+' recipes';$('recipeSummary').textContent=`Showing ${Math.min(visibleRecipes,list.length)} of ${list.length} recipes · ${selected.size?'Each recipe uses at least 2 ingredients you have':'Stock your fridge to see your best matches'}`;$('recipeGrid').innerHTML=list.length?list.slice(0,visibleRecipes).map(r=>`<article class="recipe-card"><div class="recipe-image"><span>${doodle(r,true)}</span><button class="heart ${favorites.has(r.id)?'saved':''}" data-fav="${r.id}" aria-label="${favorites.has(r.id)?'Unsave':'Save'} ${esc(r.title)}" aria-pressed="${favorites.has(r.id)}">${favorites.has(r.id)?'♥':'♡'}</button></div><div class="recipe-info"><small>${esc(r.type)} · ${r.time} min${r.wait?' prep + '+esc(r.wait):''} · ${r.need.length} ingredients</small><h3>${esc(r.title)}</h3><p>${esc(r.about)}</p><div class="meter" aria-hidden="true"><i style="width:${r.have/r.need.length*100}%"></i></div><div class="match ${r.missing.length?'':'ready'}">${r.missing.length?`${r.have}/${r.need.length} ingredients · ${r.missing.length===1?'just 1 away':r.missing.length+' missing'}`:'✓ Ready to make!'}</div><button class="view" data-recipe="${r.id}" aria-label="See recipe: ${esc(r.title)}">See recipe →</button></div></article>`).join(''):`<div class="no-result">${filter==='favorites'?'Saved recipes using at least two ingredients from your fridge will appear here.':filter==='ready'?'No recipes ready yet. Try “Almost there” to find a meal just one ingredient away.':'No recipes match at least two ingredients from your fridge. Add more ingredients or try another search, meal, or filter.'}</div>`;$('loadMore').hidden=list.length<=visibleRecipes;if(focusedFav){const b=document.querySelector(`[data-fav="${focusedFav}"]`);(b||document.querySelector('[data-filter="favorites"]')).focus({preventScroll:true})}}
function updateFindButton(){const count=selected.size;$('findRecipes').disabled=count<2;$('findRecipes').innerHTML='Find recipes'+' <span aria-hidden="true">→</span>';$('findRecipesHint').textContent=count<2?(count===1?'Add one more ingredient to find recipes.':'Choose at least two ingredients above, then let’s find something delicious.'):count?`${count} ingredient${count===1?'':'s'} stocked. ${hasSearched&&!recipesRevealed?'Your fridge has changed. Press the button for fresh matches.':'Ready to see what you can make?'}`:'Choose your ingredients above, then let’s find something delicious.'}
function render(){recipesRevealed=false;$('recipes').hidden=true;$('findRecipes').setAttribute('aria-expanded','false');renderBaskets();renderFridge();renderRecipes();updateFindButton()}
$('findRecipes').addEventListener('click',()=>{if(selected.size<2)return;recipesRevealed=true;hasSearched=true;visibleRecipes=12;$('recipes').hidden=false;$('findRecipes').setAttribute('aria-expanded','true');renderRecipes();updateFindButton();$('recipesTitle').focus({preventScroll:true});$('recipes').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});
function updateRecipeContents(){const r=recipes.find(r=>r.id===activeRecipe);if(!r)return;$('modalTitle').textContent=r.title;$('modalMeta').textContent=r.type+' · '+r.time+' minutes'+(r.wait?' prep + '+r.wait:'')+(r.servings?' · Serves '+r.servings:'')+(r.equipment?' · '+r.equipment:'');$('modalArt').innerHTML=doodle(r,true);$('modalAbout').textContent=r.about;$('modalTags').innerHTML=r.need.map(i=>`<span class="ingredient-tag ${selected.has(i)?'':'missing'}">${selected.has(i)?'✓ Have':'Missing'} · ${esc(byId[i].name)}${r.amounts?.[i]?' — '+esc(r.amounts[i]):''}</span>`).join('');$('modalSteps').innerHTML=r.steps.map(x=>'<li>'+esc(x)+'</li>').join('');$('downloadList').hidden=r.need.every(id=>selected.has(id));$('modalSource').hidden=!r.source;$('modalSource').innerHTML=r.source?'<a href="'+esc(r.source.url)+'" target="_blank" rel="noopener noreferrer">'+esc(r.source.name)+' ↗</a>':''}
function openRecipe(id){if(!recipes.some(r=>r.id===id))return;lastFocus=document.activeElement;activeRecipe=id;updateRecipeContents();$('modalBack').classList.add('open');document.querySelector('.app').inert=true;document.body.style.overflow='hidden';$('closeModal').focus();document.querySelector('.modal').scrollTop=0}
function closeRecipe(){if(activeRecipe===null)return;$('modalBack').classList.remove('open');document.querySelector('.app').inert=false;document.body.style.overflow='';activeRecipe=null;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true})}

// Touch users can drag stocked food between shelves; a normal tap still removes it.
let touchFoodDrag=null,suppressFoodClickUntil=0;
function clearTouchFoodDrag(){const state=touchFoodDrag;if(!state)return;state.ghost?.remove();state.source?.classList.remove('touch-drag-source');document.querySelectorAll('.drop-target').forEach(z=>z.classList.remove('over'));try{if(state.source?.hasPointerCapture?.(state.pointerId))state.source.releasePointerCapture(state.pointerId)}catch(e){}touchFoodDrag=null}
document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'&&e.pointerType!=='pen')return;const source=e.target.closest('.personality-fridge .placed');if(!source||!selected.has(source.dataset.placed))return;clearTouchFoodDrag();touchFoodDrag={id:source.dataset.placed,pointerId:e.pointerId,source,x:e.clientX,y:e.clientY,started:false,zone:null,ghost:null};source.setPointerCapture?.(e.pointerId)});
document.addEventListener('pointermove',e=>{const state=touchFoodDrag;if(!state||state.pointerId!==e.pointerId)return;if(!state.started&&Math.hypot(e.clientX-state.x,e.clientY-state.y)<9)return;e.preventDefault();if(!state.started){state.started=true;state.source.classList.add('touch-drag-source');state.ghost=state.source.cloneNode(true);state.ghost.className='touch-food-ghost';state.ghost.setAttribute('aria-hidden','true');state.ghost.setAttribute('tabindex','-1');state.ghost.removeAttribute('draggable');state.ghost.querySelectorAll('.name').forEach(n=>n.remove());document.body.append(state.ghost)}state.ghost.style.transform='translate('+(e.clientX-36)+'px,'+(e.clientY-36)+'px)';const zone=document.elementFromPoint(e.clientX,e.clientY)?.closest('.drop-target');if(state.zone!==zone){state.zone?.classList.remove('over');state.zone=zone;state.zone?.classList.add('over')}},{passive:false});
document.addEventListener('pointerup',e=>{const state=touchFoodDrag;if(!state||state.pointerId!==e.pointerId)return;const moved=state.started,id=state.id,zone=state.zone?.dataset.zone;clearTouchFoodDrag();if(!moved)return;e.preventDefault();suppressFoodClickUntil=Date.now()+650;if(validZones.has(zone)&&selected.has(id)){positions[id]=zone;save();render();notify(byId[id].name+' moved.')}});
document.addEventListener('pointercancel',()=>{if(touchFoodDrag?.started)suppressFoodClickUntil=Date.now()+650;clearTouchFoodDrag()});
document.addEventListener('click',e=>{if(Date.now()<suppressFoodClickUntil&&e.target.closest('[data-placed]')){e.preventDefault();e.stopImmediatePropagation()}},true);
window.addEventListener?.('blur',clearTouchFoodDrag);

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.food){add(b.dataset.food);return}if(b.dataset.placed){add(b.dataset.placed);return}if(b.dataset.category){category=b.dataset.category;renderBaskets();return}if(b.dataset.fav){const id=+b.dataset.fav;favorites.has(id)?favorites.delete(id):favorites.add(id);save();renderRecipes();return}if(b.dataset.recipe){openRecipe(+b.dataset.recipe);return}if(b.dataset.filter){filter=b.dataset.filter;visibleRecipes=12;document.querySelectorAll('.filter').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderRecipes()}});
$('foodSearch').addEventListener('input',e=>{foodQuery=e.target.value.trim().toLowerCase();renderBaskets()});$('selectedOnly').addEventListener('change',e=>{stockedOnly=e.target.checked;renderBaskets()});$('recipeSearch').addEventListener('input',e=>{recipeQuery=e.target.value.trim().toLowerCase();visibleRecipes=12;renderRecipes()});$('mealType').addEventListener('change',e=>{meal=e.target.value;visibleRecipes=12;renderRecipes()});$('loadMore').addEventListener('click',()=>{const old=visibleRecipes;visibleRecipes+=12;renderRecipes();document.querySelectorAll('[data-recipe]')[old]?.focus({preventScroll:true})});
$('clear').addEventListener('click',()=>{if(!selected.size){notify('Your fridge is already empty.');return}undoState={selected:[...selected],positions:{...positions}};selected.clear();positions={};save();render();notify('Fridge emptied. Your favorite recipes are saved.',true)});$('undoClear').addEventListener('click',()=>{if(!undoState)return;for(const id of undoState.selected){selected.add(id);positions[id]=undoState.positions[id]}undoState=null;save();render();notify('Your ingredients are back.');$('clear').focus()});

$('downloadList').addEventListener('click',()=>{const r=recipes.find(r=>r.id===activeRecipe);if(!r)return;const missing=r.need.filter(id=>!selected.has(id));const text=`Fill My Fridge!\nShopping list for ${r.title}\n\n${missing.map(id=>'[ ] '+(r.amounts?.[id]?r.amounts[id]+' ':'')+byId[id].name).join('\n')}\n\nCheck your quantities before shopping.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='shopping-list-'+r.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)});
$('closeModal').addEventListener('click',closeRecipe);$('modalBack').addEventListener('click',e=>{if(e.target===$('modalBack'))closeRecipe()});document.addEventListener('keydown',e=>{if(activeRecipe===null)return;if(e.key==='Escape'){e.preventDefault();closeRecipe()}if(e.key==='Tab'){const nodes=[...$('modalBack').querySelectorAll('button:not([hidden]),a[href],input,select')].filter(n=>!n.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
let dragged=null;
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-food],[data-placed]');if(!el)return;dragged=el.dataset.food||el.dataset.placed;if(e.dataTransfer){e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move'}});
document.querySelectorAll('.drop-target').forEach(z=>{z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('over')});z.addEventListener('dragleave',e=>{if(!z.contains(e.relatedTarget))z.classList.remove('over')});z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('over');const id=dragged||e.dataTransfer?.getData('text/plain');if(Object.hasOwn(byId,id)){selected.add(id);positions[id]=z.dataset.zone;save();render();notify(byId[id].name+' placed on the shelf.')}})});
document.addEventListener('dragend',()=>{dragged=null;document.querySelectorAll('.drop-target').forEach(z=>z.classList.remove('over'))});document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter===filter)));render();

